/* AMERICAN DICTATOR, cs deck translations (lazy-loaded). Falls back to English per field. */
AD.CARDT.cs = {"a-let-this-go":{"t":"„Doufám, že to dokážete“","x":"Požádal jste všechny ostatní, aby opustili místnost. Ředitelka Quist tu ještě je. Vyšetřování vašeho poradce pro národní bezpečnost běží devět týdnů a vy se k němu chystáte něco říct.","c":[["„Doufám, že najdete způsob, jak to nechat být.“","O dvacet minut později si to zapíše ve svém autě, opatří datem a rozdá kopie třem lidem. Slovo „doufám“ se pak dva roky pitvá u soudu."],["O případu neříkejte nic. Mluvte o čemkoli jiném.","Jedenáct minut o politice vůči rukojmím. Odchází zmatená a nic si nezapíše, což je jediný výsledek, který vám skutečně pomůže."],["Zeptejte se jí oficiálně, se záznamem, za přítomnosti právníka.","Nevhodná otázka za přítomnosti svědka mění popíratelný rozhovor v zdokumentovaný, ale aspoň je to rozhovor, který dokážete obhájit."],["Požádejte ji, ať raději jako odvedení pozornosti vyšetřuje vás.","Otevře spis. Je to skutečný spis se skutečným číslem jednacím. V roce 2029 je stále otevřený a nikdo ze zúčastněných to takhle nechtěl."]]},"a-no-quid":{"t":"Tři slova","x":"Kaylee to spočítala: stejnou třízlovou latinskou frázi jste za čtyři dny použil jedenáctkrát. „Pane, tuhle frázi nikdo ve veřejném životě deset let nepoužil. Teď je na hrnku na kávu.“","c":[["Použijte ji znovu. Hlasitěji. Je to dobrá fráze.","Opakovaným popíráním něčeho, na co se nikdo neptal, si sami vymyslíte otázku. Do třetího týdne je fráze zkratkou přesně pro to, co popírá."],["Přestaňte ji úplně používat. Nikdy víc.","Mlčení to za devět dní umoří hlady. Je to správné rozhodnutí, a zevnitř se to cítí přesně jako prohra."],["Zveřejněte záznam hovoru a nechte si ho lidi přečíst.","Je horší než shrnutí a lepší než spekulace. Zveřejnění zabije čtyři konkurenční fámy a odstartuje jednu pravdivou."],["Prodávejte ten hrnek na kávu.","Čtyři sta tisíc kusů po 28 dolarech, druhý nejprodávanější artikl, jaký hnutí kdy vyrobilo, a přímo na boku má vytištěnou latinu pro „není to úplatek“."]]},"a-withheld-aid":{"t":"Pozastávka","x":"„Čtyři sta milionů dolarů, schválených, závazně přidělených, a teď pozastavených, přičemž stopa vede zpátky do téhle budovy.“ Lyle vzhlédne. „Nikdo na ministerstvu mi neumí říct, kdo pozastávku nařídil, ani proč.“","c":[["Ponechte pozastávku. Bez udání důvodu.","Nevysvětlená pozastávka schválených peněz vyvolá čtyři samostatná šetření, dvě z nich ze zákona povinná, a ani jednomu se nevyhnete."],["Uvolněte je. Řekněte, že šlo o kontrolu.","Uvolněny s 55denním zpožděním a dvouřádkovým vysvětlením. Auditor si zpoždění všimne. Nikdo jiný ne."],["Ponechte je a svažte to s výslovně formulovanou podmínkou.","Písemná podmínka je nástroj politiky. Nepsaná je laskavost. Sepsat ji je z obou špatných možností ta méně katastrofální."],["Uvolněte je v měně, kterou nemohou utratit.","Převod dorazí v jednotce, kterou nikdo nepoužil od roku 1971. Jejich ministerstvo financí stráví čtyři měsíce převodem a stejně pošle děkovný dopis."]]},"a-fifty-forty-eight":{"t":"Padesát ku čtyřiceti osmi","x":"Hal má sečteno: padesát pro, čtyřicet osm proti, a dva členové se rozhodnou až v poslední hodině. Slyšení bylo mimořádné způsobem, na který nikdo v místnosti nezapomene.","c":[["Prosaďte hlasování ještě dnes večer. Dva hlasy jsou většina.","Potvrzen o dva hlasy. Slouží třicet let a slyšení se pak přehrává u každého dalšího potvrzování, oběma stranami, z opačných důvodů."],["Pozastavte hlasování na týden kvůli doplňujícímu šetření.","Šetření nevyřeší nic ani jedním směrem. O devět dní později je potvrzen poměrem 53:45. Ten týden navíc vás nic nestojí a čtyřem senátorům kupuje politické krytí."],["Stáhněte ho. Nominujte dalšího kandidáta.","Náhradník je potvrzen 61:39 a je podle všech měřítek spolehlivěji na vaší straně. Vaše základna vnímá stažení jako naprostou, neodpustitelnou porážku."],["Nominujte oba. Dvě místa, jedno hlasování.","Volné místo je přesně jedno. Druhá nominace se přesto podá a čtyři roky visí v senátním kalendáři, formálně, věčně nevyřízená."]]},"a-eight-days":{"t":"Osm dní do voleb","x":"Soudce zemřel osm dní před volbami. Bo: „Žádné pravidlo tomu nebrání. Existuje ale výrok, který v roce 2016 pronesli čtyři senátoři a teď si ho budou muset postupně, na kameru, spolknout.“","c":[["Potvrďte ho před volbami. Osm dní je osm dní.","Složí přísahu se šesti dny v rezervě. Čtyři senátoři si postupně na kameru spolknou svůj starý výrok, a přesto jsou všichni znovu zvoleni."],["Nominujte teď, potvrďte až potom. Stejný výsledek, méně kritiky.","Identický výsledek o čtrnáct dní později a se třetinovým mediálním pokrytím. Ukázalo se, že jedinou proměnnou, na které záleželo, bylo načasování, a bylo cennější než celá argumentace."],["Nechte to na tom, kdo vyhraje.","Prohrajete volby i to místo. Je to nejzásadovější věc, kterou za čtyři roky uděláte, a stojí vás to čtyři vztahy uvnitř vlastní strany."],["Potvrďte ho na místo, které není volné.","Desátý soudce je potvrzen k soudu, který má devět míst. Dostaví se, dostane kancelář a čtyři roky nenápadně dělá právní výzkum."]]},"a-order-struck":{"t":"Zrušeno natrvalo","x":"Soudkyně natrvalo zrušila váš příkaz proti firmě, v odůvodnění, které devětkrát použije slovo „protiústavní“. Sy: „Nezakázala ho, pane. Zneplatnila ho. Není proti čemu se odvolat.“","c":[["Napadněte rozhodnutí. Podepište téměř identický příkaz.","Druhý příkaz zneplatní za jedenáct dní tatáž soudkyně, obsáhle citující vlastní odůvodnění a přikládající první příkaz jako důkazní materiál."],["Podřiďte se. Obnovte prověrky. Neříkejte nic.","Firma je do čtrnácti dnů plně odškodněna. Čtyři jiné firmy, které už tiše ustoupily, své ústupky odvolají, což je ta skutečná cena."],["Podřiďte se, ale útočte na firmu přes zadávání zakázek.","Žádný příkaz, žádné rozhodnutí, žádné titulky, jen smlouvy, které se přestanou tiše obnovovat. Funguje to a žádný soudce nemá co zneplatnit."],["Najměte tu soudkyni.","Odmítne dopisem o čtyřech větách. Dopis je založen do spisu, zveřejní se a stane se nejvtipnějším dokumentem podaným za celý rok."]]},"a-accountability-order":{"t":"Příkaz o odpovědnosti","x":"„Příkaz nařizující agenturám prošetřit chování jmenovaných bývalých úředníků.“ Bo otočí stránku. „Pane, čtyři z těch jmen vás osobně vyšetřovali. Jednomu je 81 let a je v důchodu.“","c":[["Podepište ho. Všechna jména.","Nejdřív prověrky, pak osobní spisy, pak revize penzí. Nikdy nikdo není obžalován. Přesto se udělá všechno, protože nic z toho obžalobu nevyžadovalo."],["Podepište ho, ale vyškrtněte ty v důchodu.","Ušetřit toho 81letého je v médiích celý rozdíl mezi „politikou“ a „vendetou“, a v ničem jiném vůbec."],["Nepodepisujte. Místo toho nařiďte revizi revizí.","Metarevize podá zprávu za čtrnáct měsíců, najde procesní nesrovnalosti na všech stranách a neuspokojí nikoho, což je přesně k čemu revize slouží."],["Podepište ho a přidejte na seznam i vlastní jméno.","Prošetří vás vlastní ministerstvo podle vašeho vlastního příkazu. Za devět týdnů vás očistí a to očištění má hodnotu přesně takovou, kolik stálo ho vyrobit."]]},"a-ethics-divest":{"t":"Brífink o odprodeji majetku","x":"Miriam Applewhiteová předkládá standardní balíček: buď majetek rovnou prodat, nebo ho svěřit do skutečného slepého fondu spravovaného cizí osobou. „Existuje ještě třetí věc, které lidé říkají slepý fond a přitom ji svěří vlastním dětem. Není slepá, pane. Je to jen fond.“","c":[["Fond. Spravovaný rodinou. Nazvěte ho slepým.","O jeho výnosech se dozvídáte u večeře. Ve všech podáních se označuje za slepý a všechna podání jsou, formálně vzato, přesná co do papírování."],["Úplný odprodej. Prodejte všechno.","Stojí to jmění a natrvalo to eliminuje celou kategorii kauz. Ocenit to dokážete tak za tři roky."],["Ponechte si všechno. Prezident nemůže mít střet zájmů.","Právní pozice se skutečnou oporou v zákoně, ale bez jediné opory v padesáti letech praxe. Miriam v březnu rezignuje a v červnu svědčí."],["Svěřte ho fondu spravovanému cizí osobou, kterou pak zaměstnáte.","O jedenáct týdnů později je jmenován do federální poradní rady. Čtyři novináři si toho všimnou téhož odpoledne a ani jeden nedokáže prokázat souvislost."]]},"a-gift-log":{"t":"Evidence darů","x":"Jedenáct set inauguračních darů od zahraničních vlád. Cokoli nad stanovený limit ze zákona patří státu, ne vám. Položka 402 je kůň z ryzího zlata. Položka 403 je ještě větší.","c":[["Zapište je do evidence. Koně si odkupte za odhadní cenu.","Naprosto legální, plně zdokumentované, a stojí to 600 000 dolarů za dva zlaté koně, které jste nikdy nechtěl a nemáte je kde v budově vystavit."],["Zapište je jako vystavené v rezidenci. Ponechte si je.","Rezidence je vaše. „Vystavení“ je chodba. Podle jakéhokoli běžného výkladu toho slova si koně prostě ponechal."],["Vydražte celou sbírku ve prospěch veteránů. Veřejně.","Za odpoledne se vybere 2,1 milionu dolarů. Ceremoniální dýka připadne dvanáctiletému dítěti, což vyvolá krátký, upřímně roztomilý mezinárodní incident."],["Nechte koně roztavit. Razte z nich mince s vaší tváří.","Darující vláda si vyžádá fotografii koní pro vlastní archiv. Místo toho jí pošlete fotografii mincí."]]},"a-property-billing":{"t":"Ceník","x":"Duane má faktury. Ochranka zaplatila vašemu vlastnímu resortu za čtyři měsíce 1,1 milionu dolarů na ubytování. „Pane, musíme bydlet tam, kde bydlíte vy. A cenu určujete vy.“","c":[["Ponechte cenu. Je to tržní sazba.","Daňový poplatník teď platí prezidentovi za to, že chrání prezidenta v prezidentově vlastním hotelu. Je to zveřejněné, položkově vyčíslené, naprosto legální, a v tom je celý problém."],["Účtujte jim jeden dolar ročně.","Levné, teatrální a zdrcujícím způsobem účinné gesto, které zabije celou kauzu za cenu jednoho sendviče."],["Bydlete někde, co nevlastníte.","Camp David tři různí poradci označí za „vlastně fajn“. Po druhé návštěvě se tam už nikdy nevrátíte."],["Účtujte jim, a pak si sami sobě naúčtujte za způsobené nepříjemnosti.","Faktura od vás, vám, proplacená vládou, za obtíže způsobené vaší vlastní ochrankou. Projde. Nikdo nedokáže zjistit, kdo ji schválil."]]},"a-family-desk":{"t":"Stůl v Západním křídle","x":"Ivy by ráda dostala kancelář v Západním křídle, bezpečnostní prověrku a neplacený vyšší titul. Prověrka je ta část, na kterou dvakrát písemně upozornili kariérní bezpečnostní pracovníci.","c":[["Všechny tři. Přehlédněte varování.","Je skutečně schopná a to místo by nemohlo připadnout nikomu, kdo by nebyl vaše dcera. Obojí je pravda, a do novin se dostane jen jedno z toho."],["Titul a kancelář. Bez prověrky.","Na porady stejně chodí, ze židle u dveří, a předčí čtyři potvrzené úředníky, aniž by kdy viděla utajovanou stránku."],["Žádní příbuzní v budově.","Správné rozhodnutí, tečka. Zároveň to připraví o jediného živého člověka, který by vám v malé místnosti řekl pravdu."],["Dejte jí prověrku, a zároveň prověřte i ta varování.","Dva kariérní úředníci, kteří vznesli námitky, jsou zasvěceni přímo do toho programu, proti kterému protestovali. Oba okamžitě protestují znovu, tentokrát podstatně podrobněji."]]},"a-columbia":{"t":"Druhá univerzita","x":"Čtyři sta milionů dolarů, jedna univerzita, a seznam požadavků ohledně politiky protestů a dohledu nad katedrami. Ollis: „Ta první se zlomila rychle. Tahle má větší nadační fond a horšího právníka.“","c":[["Zrušte to. Celých čtyři sta milionů.","Za devět týdnů se zlomí a přijmou externí dohled nad jednou katedrou. Jedenáct dalších univerzit si přečte dohodu a rovnou přeskočí telefonát."],["Zrušte polovinu. Lékařský výzkum nechte být.","Ušetřit onkologické laboratoře odstraní jediný argument, který na veřejnost skutečně zabíral. Stejná páka, žádná fotka zavřené klinické studie."],["Financujte v plné výši. Útočte místo toho jen slovně.","Slova nic nestojí a nic nemění. Univerzita vás naprosto ignoruje a počet přihlášek stejně stoupne o 14 procent."],["Zrušte financování a přihlaste se tam na seminář.","Absolvujete čtyři lekce kurzu ústavního práva na instituci, kterou zrovna odřezáváte od peněz. Přepis se objeví v roce 2044 a nečekaně se dobře čte."]]},"a-minors-care":{"t":"Věková hranice","x":"Dr. Pike má návrh. „Podmiňuje to federální financování tím, že nemocnice ukončí určitou kategorii péče pro osoby mladší 19 let. Čtyři dětské nemocnice ve státech, které jste vyhrál, přestanou fungovat v den, kdy to podepíšete.“","c":[["Podepište to. Devatenáct let a méně, bez výjimek.","Devět nemocnic se do čtrnácti dnů zastaví, u některých pacientů uprostřed léčby. Dva soudy to částečně pozastaví, ale nemocnice se stejně znovu nerozjedou, protože nemocnice se nikdy znovu nerozjedou."],["Podepište to s výjimkou pro pokračující léčbu.","Nikdo není odříznut uprostřed léčby. Dosáhne se cíle politiky, aniž by vznikly ty čtyři konkrétní případy, které by ji definovaly ve všech titulcích."],["Žádný příkaz. Místo toho financujte dlouhodobou studii.","Výsledky přijdou za devět let, s největším souborem dat, jaký kdy kdo sestavil. Obě strany ho selektivně citují a ani jedna neustoupí ani o píď."],["Nastavte věkovou hranici na 47.","Pokyn k formulaci vzal doslovně někdo, kdo se nechtěl ptát. Chyba se odhalí při kontrole po čtyřech dnech a kauza úplně neumře nikdy."]]},"a-military-dei":{"t":"Příkaz o bojeschopnosti","x":"Tarrant položí vedle sebe příkaz a data o udržení personálu. „Provedu, cokoli podepíšete, pane. Musím vás ale upozornit, že nábor do čtyř z pěti nejhůře obsaditelných specializací probíhá právě přes úřady, které se tímto ruší.“","c":[["Podepište ho. Zrušte všechny úřady.","Nábor do těch čtyř specializací klesne za dva roky o 19 procent. Zpráva, která to dokazuje, je utajena na úrovni, jež ji drží mimo rozpočtové slyšení."],["Zrušte úřady. Náborové kanály zachovejte.","Cedule zmizí, funkce zůstane, jen se přejmenuje. Každý dostane přesně to, co říkal, že chce, a vůbec nic se ve skutečnosti nezmění."],["Nepodepisujte. Nejdřív nařiďte prověrku bojové připravenosti.","Prověrka shledá programy mírně přínosnými a mírně nákladnými. O devět měsíců později podepíšete užší příkaz a nikdo se neobtěžuje protestovat."],["Podepište ho a nahraďte úřady jediným seržantem.","Seržant Alvarez zdědí pracovní zátěž čtyř set lidí, zvládá to lépe než všech čtyři sta dohromady a za rok je dvakrát povýšen."]]},"a-passports":{"t":"Označení","x":"Muriel: „Žádosti o změnu označení se pozastavují. Ne zamítají, pozastavují. Je jich jedenáct tisíc a čtyři sta lidí má tento měsíc rezervovanou cestu.“","c":[["Pozastavte je na neurčito. Nevydávejte žádný pokyn.","Pozastavení bez rozhodnutí se nedá odvolat, protože formálně nebylo nic rozhodnuto. Je to nejúčinnější zamítnutí v dějinách ministerstva."],["Zamítněte je formálně. Dejte jim něco, proti čemu se mohou odvolat.","Formální zamítnutí lze žalovat, a taky se žaluje. Za čtrnáct měsíců prohrajete, což jsou, podotýkáme, čtrnáct měsíců."],["Vyřiďte je. Politiku změňte jen do budoucna.","Jedenáct tisíc žádostí je vyřízeno za šest týdnů a nové pravidlo platí pro všechny další. Nikomu neuletí letadlo a nikdo si toho ani nevšimne."],["Vydávejte všechny pasy úplně bez označení.","Čtyři země ty doklady na hranicích odmítají uznat. Ministerstvo stráví devět měsíců vyjednáváním o uznání kolonky, kterou samo úmyslně smazalo."]]},"a-ninety-day":{"t":"Devadesátidenní pauza","x":"Čtyři dny propadů. Lyle má plán: pozastavit sazby specifické pro jednotlivé země na devadesát dní a zvýšit tu vůči vašemu největšímu rivalovi na číslo, jaké nikdo nepoužil od třicátých let.","c":[["Pozastavte všechno. Jednu sazbu zvyšte na 125 procent.","Trhy vyletí za odpoledne o 9 procent nahoru. Pár lidí, kteří o pauze věděli o čtyřicet minut dřív, se pořádně obohatí, a čtyři vyšetřování toho nikam nedojdou."],["Pozastavte všechno. Nic nezvyšujte.","Čistý ústup, správně tak i vnímaný. Nárůst na trhu je stejně velký a vaše základna zuří kvůli číslu, které už neexistuje."],["Nic nepozastavujte. Držte linii.","Za týden odpadne dalších 6 procent. Penzijní účty ránu vstřebají a vaše preference u lidí nad 60 let udělají něco, čemu průzkumníci odborně říkají „geologické“."],["Pozastavte je a oznamte tu pauzu čtyřikrát.","Čtyři samostatná oznámení téže pauzy během devíti dní, každé z nich pohne trhem. Obchodní časopis to nazve nejvýnosnějším koktáním ve finanční historii."]]},"a-retaliation":{"t":"Odpověď","x":"Odpověděli dva partneři. Jeden zasáhl čtyři zemědělské státy s chirurgickou přesností. Druhý neudělal nic oficiálního, jeho občané prostě přestali kupovat americké výrobky.","c":[["Eskalujte proti oběma.","Přesně mířené odvetné cla se přes noc zdvojnásobí. Bojkot, který nemá žádný oficiální status, s nímž by se dalo vyjednávat, se nedá utišit a táhne se jedenáct let."],["Vyjednávejte se státem. Bojkot ignorujte.","S vládou se dohodnete za čtyři měsíce. Spotřebitelské nálady se zotavují devět let a žádná dohoda se jich ani nedotkne."],["Zrušte cla. Prohlaste, že jste dokázal svoje.","Vše se za šest týdnů odvine zpět. Dva drobné ústupky za jedenáct měsíců chaosu, poctivý, i když nepůsobivý výsledek."],["Bojkotujte je taky. Osobně. Na kameru.","Veřejně se zřeknete jejich čtyř nejslavnějších produktů. Domácí prodeje všech čtyř stoupnou. Jedna země vám pošle zdarma bednu s velmi krátkým vzkazem."]]},"a-strike-timing":{"t":"Časový plán","x":"Váš ministr obrany zveřejnil okna pro odpal a seznamy cílů v komerční chatovací aplikaci dvě hodiny předtím, než letadla vzlétla. Tarrant: „Kdyby se to dostalo k nepovolané osobě, pane, tento týden bych psal kondolenční dopisy.“","c":[["Nikoho nepotrestáme. Dopadlo to dobře.","Skutečně to dopadlo dobře. Poučení, které si z toho odnese každý důstojník, se týká následků, ne aplikace."],["Odvolejte ho. Řekněte přesně proč.","Odpovědnost, vyslovená jasně, jednou. Čtyři spřátelené zpravodajské služby tiše obnoví sdílení informací, které minulý měsíc pozastavily."],["Ponechte ho ve funkci. Zakažte tu aplikaci v celé vládě.","Systémová oprava bez personální. Vyřeší to tento konkrétní incident a přesně nula z důvodů, proč k němu došlo."],["Přidejte posádku letadel do chatu, ať to dostanou rychleji.","Někdo se o to skutečně pokusí, než ho fyzicky zastaví. Pokus skončí ve zprávě generálního inspektora jako číslované zjištění."]]},"a-war-plans":{"t":"„Nikdo nic nepsal esemesky“","x":"Vy i ministr jste na kameru shodně prohlásili, že nikdo nic takového nepsal. Kaylee: „Pane, časopis má snímky obrazovky. V šest je zveřejní v plném znění.“","c":[["Držte linii. Popírejte to i po zveřejnění.","Snímky obsahují doslovný text. Popírání poté, co jsou důkazy veřejné, mění bezpečnostní selhání v selhání důvěryhodnosti, natrvalo."],["Připusťte fakta. Rozporujte jejich závažnost.","Spor o to, jestli to bylo vážné, je bitva, kterou přežijete. Spor o to, jestli se to vůbec stalo, není, a moudře se do druhé nepouštíte."],["Předběhněte to. Zveřejněte zprávy sám ve čtyři.","Předčasné zveřejnění zabije jedním tahem jak senzaci, tak nařčení z utajování. Časopis svůj článek stejně otiskne, ale jen třetinu tak dlouhý, jak měl v plánu."],["Tvrďte, že snímky jsou z jiného chatu.","Obsahují vaše vlastní zobrazované jméno a profilovou fotografii. Na to upozorní během čtyř minut, živě, přímo osoba, která snímky drží."]]},"a-cabinet-praise":{"t":"Kolem stolu","x":"Chet navrhuje zahájit televizní zasedání vlády tak, že se postupně obejde stůl a každý ministr řekne, co pro něj osobně sloužit vám znamená. „Zlidští to tým,“ říká a dívá se přitom přímo na vás.","c":[["Udělejte to. Obejděte stůl dvakrát.","Čtyřicet jedna minut, kdy dospělí lidé v přímém přenosu děkují jednomu muži za výsadu pracovního poměru. Profesor srovnávací politologie zastaví záznam a nahlas, do prázdné místnosti, řekne: „Tady to máme.“"],["Udělejte to, ale po čtyřech to ukončete.","Čtyři stačí na to, aby se rituál ustavil, aniž by vznikl kompletní sestřih k výsměchu. Chet si to číslo poznamená a založí."],["„Tohle dělat nebudeme. Podejte zprávu o svých úřadech.“","Skutečně produktivní jednání s devíti reálnými rozhodnutími. Chet celou hodinu píše do malého notesu, netuše, co se to vlastně stalo."],["Obejděte stůl a místo toho poděkujte vy jim.","U každého z dvaadvaceti jmenujete jednu konkrétní věc, kterou udělal. Trvá to padesát minut, čtyři jsou viditelně dojatí a Chet vůbec nechápe, co to sleduje."]]},"a-crowd-number":{"t":"Letecké snímky","x":"Letecké fotografie jsou venku. Dav je skutečný, nadšený a zhruba tak velký jako oblastní psí výstava. Noviny otiskly obě léta vedle sebe, pro případ, že by to někomu uniklo.","c":[["Pošlete tam Kaylee, ať řekne, že to byl vůbec největší dav v historii. Tečka.","Řekne to s plným nasazením. Nikdo tomu nevěří ani slovo, ale všichni si všimnou, že to řekla, a přesně o to od začátku šlo."],["„Davy jsou posedlost médií.“ Další otázka.","Kauza za čtyřicet minut umře. Něco ve vás umře spolu s ní."],["Nařiďte správě parků, ať zveřejní opravená čísla.","Kariérní fotoarchivář je přeložen do místnosti bez oken v Suitlandu. Nové číslo, 1,9 milionu, je sepsané a oficiální."],["Spočítejte je sám. V televizi. Nahlas.","Dostanete se ke čtyřem stům jedenácti, než se úplně ztratíte. Vysílá se to celé a stane se to zdaleka nejsledovanějším příkladem počítání v dějinách televize."]]},"a-misspellings":{"t":"Katalog","x":"Ověřovací oddělení jedenáct měsíců katalogizuje vaše pravopisné chyby. Seznam má už 340 položek. Brayden si myslí, že vás to zlidšťuje. Kaylee si myslí, že to vypadá, jako byste psal ve čtyři ráno, což děláte.","c":[["Přispívejte dál bez úprav. Je to autentické.","Katalog naroste na 900 položek. Zároveň je to opravdu důvod, proč čtyři miliony lidí věří, že příspěvky píšete sám, což bohužel děláte."],["Nechte příspěvky před zveřejněním zkontrolovat.","Míra zapojení klesne za měsíc o 22 procent. Správný pravopis působí jako práce komise, a komise pro vaši základnu vypadá jako všichni ostatní."],["Jedno slovo pište vždy úmyslně chybně. Přiznejte se k tomu.","Stane se to podpisem, pak poznávacím znamením. Příznivci vám to začnou psát stejně špatně zpátky a ověřovatelé to tiše přestanou počítat."],["Prohlaste, že se mýlí slovník.","Čtyři lexikografové reagují s upřímným potěšením a jeden napíše překvapivě dobrou esej o deskriptivismu, která se nečekaně stane virální."]]},"a-khan":{"t":"Rodiče","x":"Otec vojáka, který zahynul při ochraně své jednotky, vás ze pódia kritizoval a přitom v ruce držel kapesní vydání ústavy. Tarrant přichází s jednou větou: „Pane, neexistuje verze odpovědi jemu, která by dobře skončila.“","c":[["Odpovězte mu. Zpochybněte matčino mlčení.","Kauza se táhne jedenáct dní. Čtyři členové vaší vlastní strany se od vás veřejně distancují jménem a doslechne se to každý sloužící důstojník, většina z nich mlčí, což je samo o sobě vzkaz."],["Neříkejte vůbec nic. Pošlete soukromý dopis.","Dopis se nikdy nezveřejní. O léta později se otec zmíní, že byl psaný rukou a lepší, než čekal, a víc už k tomu neřekne."],["Na příští akci vyzdvihněte syna jménem.","Bez poznámek přesně uvedete hodnost i jednotku. Trvá to třicet vteřin a je to jednoznačně nejúčinnější věc, kterou ten měsíc uděláte."],["Kupte čtyři tisíce kapesních ústav a rozdejte je.","Do týdne se vyprodají po celé zemi. Vydavatel vám napíše poděkování. Čtyři z vašich vlastních příkazů se vám pak citují zpátky, z výtisků, které jste sám zaplatil."]]},"a-deferred-resignation":{"t":"Nabídka","x":"„E-mail všem federálním zaměstnancům. Rezignujte hned, plat vám poteče do září, bez otázek.“ Deborah má právní poznámku. „Pane, na výplatu do září nemáme schválené prostředky.“","c":[["Pošlete to všem 2,3 milionu. Peníze vyřešíme později.","Přijme to sedmdesát sedm tisíc lidí. Jako první odejdou ti, kteří mají kam jít, řízení letového provozu, jaderná bezpečnost, sledování nákaz, protože to tak vždycky bývá."],["Pošlete to jen tam, kde skutečně chcete snížit počty.","Přesnost místo brokovnice. Stejné snížení počtu lidí, ale jen tam, kde jste ho skutečně chtěl, a inspektoři reaktorů zůstávají na místě."],["Neposílejte to. Snižujte přirozeným odchodem.","Počet zaměstnanců klesá o 4 procenta ročně, aniž by odešel jediný e-mail. Pomalejší, levnější a nevyvolá to naprosto žádné soudní spory."],["Pošlete to, a pak pošlete druhý e-mail s odvoláním.","Do té doby, než dorazí odvolání, už jedenáct tisíc lidí stihlo rezignovat. Čtyři odmítnou rezignaci vzít zpět ze zásady a napořád zůstanou, s pocitem, že udělali dobře."]]},"a-thirty-days":{"t":"Třicetidenní lhůta","x":"„Zákon vyžaduje třicetidenní písemné oznámení Kongresu, než odvoláte generálního inspektora. Jedna věta.“ Sy pokrčí rameny. „Žádný sankční paragraf tam není. Kontroloval jsem to čtyřikrát.“","c":[["Přeskočte oznámení. Odvolejte ho dnes večer e-mailem.","Soudkyně to za osm měsíců prohlásí za protiprávní, ale nikoho nevrátí do funkce s odůvodněním, že byste ho stejně podruhé vyhodil správně. Má pravdu a přímo to v rozsudku napíše."],["Dodržte třicet dní. Pak ho odvolejte.","Papírování je bezvadné a výsledek stejný. Deborah na ubrousek napíše „elegantní“ a sní ho."],["Ponechte ho ve funkci. Místo toho mu seškrtejte rozpočet.","Jeho zprávy teď chodí s jedenáctiměsíčním zpožděním, černobíle, nesvázané. Nikdo je nečte, což byl zjevně celý požadavek."],["Dodržte lhůtu u jednoho a ostatní vyhoďte rovnou.","To jedno řádně provedené odvolání se pak cituje ve všech podáních jako důkaz dobré víry. Jeden ze sedmnácti se ukáže jako překvapivě účinný poměr."]]},"a-rule-count":{"t":"Devadesát osm v řadě","x":"Cassandra má tabulku. „Devadesát osm předpisů by se dalo zrušit. Jednotlivě je každý z nich technická novela, o které nikdo nepíše. Dohromady je to největší změna v ochraně životního prostředí od roku 1970, a o té taky nikdo psát nebude.“","c":[["Všech devadesát osm. Jeden týdně. Nikdy je neoznamujte.","Dva roky oznámení ve Sbírce federálních předpisů. O čtyřech se napíše. Souhrnný dopad je měřitelný z orbity a ani jednou se nedostane na titulní stranu."],["Těch dvanáct, co skutečně stojí pracovní místa. Ty hájte nahlas.","Obhajitelná pozice, se kterou v televizi skutečně můžete vyhrát, což je mimochodem devět desetin hodnoty jakékoli pozice vůbec."],["Žádný. Financujte transformaci v postižených okresech.","Ve čtyřech státech, které jste vyhrál, se otevře jedenáct tisíc rekvalifikačních míst. Funguje to, pomalu, a slavnostní pásku pak přestřihne váš nástupce."],["Zrušte devadesát osm předpisů a napište devadesát devět nových.","Nová sada je delší, přísnější a sepsali ji titíž kariérní úředníci. V budově si toho jedenáct měsíců nikdo nevšimne."]]},"a-smoot":{"t":"Srovnání","x":"Lyle má jednu stránku. „Každý oslovený ekonom sáhl po stejném srovnání s rokem 1930. Ne většina z nich, pane. Všichni. Včetně čtyř, kteří formálně pracují pro vás.“","c":[["Přijměte to srovnání. Ta cla zemi vybudovala.","Nevybudovala. Je to nejzkoumanější politické selhání v americké ekonomické historii a všichni čtyři vaši vlastní ekonomové to týž týden napíší, písemně."],["Odmítněte srovnání. Argumentujte rozdíly.","Skutečné rozdíly existují a argumentujete jimi kompetentně. Nejobsažnějších dvacet minut vašeho prezidentství, se strašnou sledovaností."],["Zakažte to srovnání v oficiální komunikaci.","Slovo se ve skutečnosti zakázat nedá. Jeho používání za čtrnáct dní vzroste o 400 procent, čistě proto, že jste se o to pokusil."],["Pojmenujte nová cla úmyslně po těch z roku 1930.","Přivlastnit si srovnání dřív, než ho stihne udělat někdo jiný, je buď geniální, nebo katastrofální, a čtyři různé knihy nakonec dojdou ke čtyřem různým závěrům, které z toho platí."]]},"a-first-of-many":{"t":"„První, snad, z mnoha“","x":"Dva tisíce vojáků je v jednom městě. Novinář se zeptal, jestli budou další. Tarrant potichu: „Pane, odpověď na tuhle otázku je celá politika. Ne nasazení. Odpověď.“","c":[["„První, snad, z mnoha.“","Čtyři guvernéři preventivně aktivují vlastní Národní gardu, jen aby vám vzali záminku. Jedna věta právě změnila vojenské rozmístění třetiny země."],["„Tohle jedno. Kvůli tomuhle. A víc nic.“","Nasazení skončí za tři týdny a nic po něm nenásleduje. Omezující formulace je nejlevnější dostupná deeskalace a stojí vás přesně jednu větu na mítinku."],["Odmítněte odpovědět. Ať hádají.","Záměrná nejednoznačnost odvede práci hrozby, aniž byste za hrozbu nesl odpovědnost. Každý guvernér počítá s nejhorším a ani jeden vás nemůže citovat."],["„První ze přesně tří.“ Jmenujte ty tři.","Bez přípravy jmenujete tři města. Všechna tři vás do týdne zažalují. Jedno z nich nebylo na žádném seznamu, který by kdokoli reálně připravil."]]},"b-motives":{"t":"Otázka pohnutky","x":"„Rozsudek dělá něco, co si lidi ještě neuvědomili.“ Sy má to místo označené třemi barvami. „Nejde jen o to, že úřední úkony jsou imunní. Jde o to, že se soud nemůže ptát, *proč* jste je udělal. Pohnutka už není přípustná. Pane, pohnutka byla celý ten případ.“","c":[["Tak to řekněte nahlas v každém příkazu. Pohnutka nepodléhá přezkumu.","Jedenáct příkazů teď bez vyzvání začíná touto doktrínou vytištěnou tučně. Nikdo tu formulaci nevyžadoval. Právě to z ní dělá hrozbu."],["Využijte to. Nikdy o tom nemluvte.","Štít funguje mlčky úplně stejně dobře a nikdo nenapíše sloupek o doktríně, kterou jste byl příliš zdvořilý na to, abyste se jí chlubil."],["Nechte právníky argumentovat úzkou verzí, pro případ, že by se hodila později.","Sy podá tak skromné podání, že mu dva soudci osobně poděkují. Ukládá si tak argument na den, kdy bude mít větší cenu."],["Prohlaste všechny své úkony za úřední, včetně snídaně.","Zveřejněný harmonogram označuje za úřední úkon každou hodinu, kdy nespíte. Je založen do spisu a posměšně citován v devíti samostatných nesouhlasných stanoviscích."]]},"b-emergency-docket":{"t":"Dvacet devět žádostí","x":"„Dvacet devět nouzových žádostí za toto období.“ Sy otočí stránku. „Pro srovnání, dvě předchozí administrativy podaly dohromady osm, za šestnáct let. Pane, my už tu výjimku nepoužíváme. Vydláždili jsme ji a postavili tam pouliční osvětlení.“","c":[["Podejte další. Výjimka je teď silnice.","Většinu vyhrajete. Každé vítězství přichází bez podpisu, bez odůvodnění, v devět večer, a zavazuje celou zemi, dokud si někdo nenajde volné odpoledne, aby vysvětlil proč."],["Podávejte jen tam, kde byste stejně vyhráli i ve věci samé.","Devět žádostí místo dvaceti devíti, a každá z nich pak obstojí. Nudné, trvanlivé a žádný právnický časopis o tom nikdy nenapíše."],["Projděte si normálním soudním řízením jako všichni ostatní.","Trvá to dva roky místo dvou týdnů. Dvě ze čtyř politik přežijí plné projednání, což jsou o dvě víc než obvykle."],["Podejte jednu žádost obsahující všech dvacet devět.","Čtyři sta stránek, jeden nadpis, devět nesouvisejících otázek. Podatelna to vrátí s poznámkou, kterou si později dají do rámečku a pověsí na zeď."]]},"b-unsigned":{"t":"Bez podpisu, bez odůvodnění","x":"Předsedkyně Nejvyššího soudu Stoneová volá kvůli něčemu jinému než rozsudku. „Dvacet tři z vašich dvaceti osmi žádostí dopadlo ve váš prospěch. Skoro žádná neuvedla proč. Soud, který se neodůvodňuje, není soud, pane prezidente. Je to úřad, který razítkuje povolení.“","c":[["„To zní jako vnitřní záležitost soudu.“","Je to vnitřní záležitost soudu, a soud tu při sobě prohrává, tiše, veřejně, v poznámkách pod čarou, které nikdo nečte, dokud nezačnou být důležité."],["Veřejně požádejte o odůvodněné stanovisko u každé z nich.","Odůvodnění fungují na obě strany a vaše vypadají hůř napsaná než vyřčená. Ze čtyř dalších případů dva prohrajete a soudnictví si vrátí něco, co pomalu ztrácelo."],["Neříkejte vůbec nic. Berte si povolení.","Mlčení je zadarmo a rozhodnutí dál přicházejí. Stoneová napíše souhlasné stanovisko, které vždycky chtěla napsat, a přečtou si ho čtyři lidé."],["Nabídněte, že jim to odůvodnění napíšete sám.","Vypracovaný text odůvodnění je kurýrem doručen soudu a vrátí se neotevřený, s lístkem s pozdravem, což dopadne nějak hůř než přímé pokárání."]]},"b-humphreys":{"t":"Devadesátiletý precedens","x":"„Právě jste odvolal úředníky ze čtyř agentur, které Kongres zřídil výslovně proto, abyste to nemohl udělat.“ Sy zní téměř obdivně. „Existuje precedens z roku 1935, který říká, že nemůžete. Soud nechal stát každé odvolání a ani jednou ho necitoval. Přehlasovává se to mlčením, pane. Nikdo nikdy neviděl provést ten trik tak čistě.“","c":[["Pokračujte v odvolávání. Mlčení je nejužitečnější druh povolení.","Devět agentur za rok. Precedens z roku 1935 zůstává formálně platným právem a už ho necituje naprosto nikdo, v ničem, nikdy."],["Požádejte je, ať to zruší řádně, věcně a otevřeně.","Případ přijmou a rozhodnou ve váš prospěch poměrem 6:3, s odůvodněním. Získáte tutéž pravomoc plus deset let legitimity, kterou jste v úterý ještě neměl."],["Zastavte se u čtyř. Ostatní nechte být.","Čtyři se čtou jako série rozhodnutí. Devět by se čtlo jako politika. Jen jedno z toho se dá žalovat jako vzorec chování."],["Odvolejte úředníky a pak je znovu jmenujte, abyste zjistil, jestli to funguje.","Všichni čtyři se vrátí ke stejným stolům s novým jmenováním a podstatně horší jistotou zaměstnání. Tři vám za to poděkují, což je na tom nejznepokojivější."]]},"b-kagan-dissent":{"t":"Nesouhlasné stanovisko","x":"Bylo zveřejněno nesouhlasné stanovisko obsahující větu, která je teď na transparentech. Varuje, že nouzový mechanismus se používá k přesunu pravomocí z Kongresu na prezidenta. Kaylee: „Pane, vytiskli ji na plátěnou tašku. Dvakrát se vyprodala.“","c":[["Útočte na autorku stanoviska jménem. Opakovaně.","Její další nesouhlasné stanovisko je delší, ostřejší a přednesené nahlas ze soudcovské lavice, což devět let nedělala, a teď to díky vám dělá pravidelně."],["„Nesouhlasná stanoviska jsou způsob, jak soud diskutuje sám se sebou.“ Jděte dál.","Jen přístup, který to bere jako běžnou věc, z toho běžnou věc udělá. Za čtyři dny to zmizí z titulní strany, aniž by to komukoli chybělo."],["Nechte to zástupce vlády u soudu zodpovědět v příštím podání.","Poznámka pod čarou reagující na nesouhlasné stanovisko je zdaleka nejestablišmentovější věc, jakou vaše administrativa kdy udělala, a funguje to přesně tak, jak establishmentové věci fungují."],["Kupte si tu tašku. Nechte se s ní vyfotit.","Na nějakých devět dní to celou kauzu zneškodní. V její kanceláři to prý považují za velmi vtipné, ale oficiálně to nepotvrdí."]]},"b-marshal":{"t":"Exekutoři soudu","x":"Soudce nařídil něco, co nemáte v úmyslu udělat. Bo prověřil, jak to funguje. „Soud nemá armádu. Výkon rozhodnutí zajišťuje exekutivní služba soudu. Ta odpovídá mému ministerstvu. Které odpovídá vám. Pane, upřímně si přeju, abyste se mě na tohle nebyl ptal.“","c":[["Sdělte exekutivní službě, že příkaz je v přezkumu.","Nic se neodmítne a nic se neudělá. Čtyři bývalí soudci nezávisle na sobě napíší stejný komentář a dojdou ke stejnému slovu: dutý."],["Podřiďte se, pomalu, a mezitím se odvolávejte.","Zdržování je poslušnost s časovým rozvrhem. Ztratíte čtyři měsíce, ale zachováte si to podstatné, být účastníkem sporu, ne jeho terčem."],["Podřiďte se plně, ještě dnes, a hlasitě to oznamte.","Veřejně a okamžitě uposlechnete příkaz, který nesnášíte. Stojí vás to týden, ale dalších jedenáct rozhodnutí máte předplacených."],["Požádejte exekutivní službu, ať doručí příkaz soudci.","Zástupce skutečně dorazí k soudní budově, než to zachytí někdo výše postavený. Soudce kopii přijme s bezvadnou zdvořilostí a založí ji do spisu."]]},"b-facilitate":{"t":"Jedno slovo, jednomyslně","x":"Devět nula. Ne šest ku třem, ne pět ku čtyřem, devět nula. Příkaz obsahuje přesně jedno sloveso: *zajistit*. Muriel: „V devíti nulách není žádný prostor k manévrování, pane. Je tam jen to slovo. A jejich právníci s našimi teď stráví rok tím, co znamená.“","c":[["„Zajistit“ znamená, že nebráníme. Nedělejte nic.","Slovo zvolené kvůli jednomyslnosti se ukáže jako slovo zvolené kvůli nejednoznačnosti. Nižší soudce to písemně, dvakrát, přesně tak i nazve."],["Posaďte ho tento týden do letadla a mějte to za sebou.","Za jedenáct dní je po všem. Vaše základna to správně nazve kapitulací, a zároveň je to poslední den, kdy se ten případ dostane na titulní stranu."],["Vyjednejte předání přes třetí zemi. Dejte si na to tři měsíce.","Řešení, které zachrání tvář a splní příkaz bez jediné fotky letadla. Diplomacie se za celé funkční období vyplatí zhruba jednou, a je to teď."],["Zajistěte to tak, že mu pošlete jízdní řád autobusu.","Vládní podání skutečně přiloží vytištěný jízdní řád trasy, která nepřekračuje oceán. Je založen do spisu jako důkaz C."]]},"b-sotomayor":{"t":"Věta v poznámce pod čarou","x":"„Naše stanovisko v podání je, že rozhodnutí o vyhoštění nepodléhá přezkumu, tečka.“ Sy přestane číst nahlas. „Nesouhlasné stanovisko upozorňuje, že naše stanovisko ani jednou nepoužije slovo ,osoba bez občanství‘. Podle naší vlastní teorie, pane, se to nezastaví u pasu.“","c":[["Nechte podání tak, jak je. Teorie je aktivum.","Argument vytvořený pro jednu kategorii je teď na papíře platný pro všechny. Vašemu nástupci ho pak citují zpátky v případu, který si tady nikdo nedokázal představit."],["Upravte podání. Slovo „bez občanství“ tam napište čtyřicetkrát.","Omezující zásada dnes nic nestojí a ukáže se jako jediný důvod, proč doktrína přežije i druhé desetiletí."],["Teorii úplně stáhněte. Argumentujte fakty.","Případ vyhrajete na faktech a prohrajete doktrínu. Sy to nazve správnou výměnou a pro jednou to nemyslí diplomaticky."],["Přidejte poznámku pod čarou slibující, že k tomu budete přistupovat rozumně.","Podání k nejvyššímu soudu země obsahuje větu „v praxi bychom to nedělali“. Při ústním jednání se přečte nahlas. Pomalu."]]},"b-injunction-scope":{"t":"Procesní vítězství","x":"„Vyhráli jsme.“ Bo nevypadá jako muž, který vyhrál. „Omezili celostátní soudní zákazy. Jeden soudce už nemůže zmrazit politiku pro celou zemi. To je obrovské.“ Otočí stránku. „Je to ale čistě procesní. Neřekli, že politika je zákonná, a naše šance, až se k tomu dostanou, se mi vůbec nelíbí.“","c":[["Vyhlaste totální vítězství. Zaveďte to všude, okamžitě.","O čtrnáct měsíců později se dostanou k věci samé a poměrem 6:3 to zruší. Všechno zavedené se musí odvinout zpět, a to odvíjení je pak celá kauza."],["Vezměte si procesní vítězství. Zaveďte to jen tam, kde jste vyhrál.","Mozaika, které rozumí právníci a nikdo jiný. Ošklivé, obhajitelné, a přežije to."],["Pozastavte politiku, dokud se nerozhodne ve věci samé.","Zdrženlivost, za kterou nezískáte žádné uznání. Znamená to ale taky, že když prohrajete, prohrajete plán, ne už rozjetý program."],["Oslavte procesní vítězství přehlídkou.","Alegorické vozy, kapela, transparent s nápisem SOUDNÍ ZÁKAZ JE MRTEV. Jediná přehlídka v americké historii věnovaná občanskému soudnímu řádu."]]},"b-framers":{"t":"„Jedině Kongres“","x":"Šest ku třem, a předseda ho napsal osobně. Všichni citují větu, že tvůrci ústavy svěřili tuto pravomoc jedině Kongresu. Lyle: „Dva z vašich vlastních jmenovaných soudců hlasovali s většinou, pane. Tohle není soud, který je politický. Tohle je soud, který je záměrně soudem, v tu nejhorší možnou chvíli pro nás.“","c":[["Napadněte soud. Řekněte, že ho ovládla druhá strana.","Útočíte na soud, který jste sám sestavil, kvůli rozsudku, který napsal muž, jehož jste osm let po sobě chválil. I vaše vlastní televize odvysílá časovou osu proti vám."],["Podřiďte se a požádejte Kongres, ať cla schválí řádně.","Zákon projde na dvou třetinách sazby, kterou jste chtěl, za devět měsíců, s datem ukončení platnosti. Zato ho žádný soud už nikdy nezruší."],["Tento zákon dodržte. Do pátku najděte jiný.","Užší pravomoc, menší číslo, a žádný rozsudek, který by šlo porušit. Lyle to nazve jedinou skutečně chytrou věcí, kterou letos kdokoli udělal."],["Zeptejte se, který konkrétně tvůrce ústavy, a žádejte, ať vám ho ukážou.","Otázka je písemně předložena úřadu zástupce vlády u soudu. Někdo tam na ni velkoryse odpoví v plném rozsahu, i s daty."]]},"b-vought":{"t":"„Žádné nezávislé agentury neexistují“","x":"Váš ředitel rozpočtu to bez vyzvání oficiálně prohlásil v pěti slovech: žádné nezávislé agentury neexistují. Deborah: „Pane, to je celá teorie jednotné exekutivy podaná jako pokrčení rameny. Devět hlavních právních poradců už volalo, jestli to bylo schváleno.“","c":[["Potvrďte to. Je to teorie a je to plán.","Vyslovit to nahlas mění právní argument v politický program a dává každému odpůrci jednu jasnou větu, kolem které se lze zorganizovat."],["„Popisoval odpovědnost, ne kontrolu.“","Rozlišení bez jakéhokoli praktického obsahu, což je přesně důvod, proč vydrží dva roky."],["Veřejně ho opravte. Některé agentury nezávislé jsou.","Oprava je upřímná a vaše vlastní strana ji vnímá jako zradu. Čtyři komisaři tiše přestanou aktualizovat svá životopisy."],["Udělejte ho šéfem všech nezávislých agentur najednou.","Jedenáct souběžných funkcí pověřeného ředitele v rukou jednoho muže s jedním diářem. Diář je předvolán jako důkaz a stane se nejvtipnějším dokumentem celého období."]]},"b-probationary":{"t":"Šestnáct tisíc","x":"Šestnáct tisíc zaměstnanců ve zkušební době propuštěno podle šablony, během týdne. Deborah má následnou zprávu. „Jedna agentura se tiše pokusila čtyři sta z nich znovu přijmout, protože se ukázalo, že dělali přesně to, kvůli čemu agentura existuje. Jedenáct dalších řeklo ne.“","c":[["Žádné zpětné přijímání. Nikde. Číslo je to podstatné.","Počet zaměstnanců drží a čtyři zákonem dané funkce tiše přestanou fungovat. Devatenáct měsíců si toho nikdo nevšimne, a pak si toho všimnou všichni najednou."],["Nechte agentury tiše přijmout zpět ty, které nutně potřebují.","Číslo v tiskové zprávě zůstává stejné. Lidé se vracejí zadními dveřmi s novými smlouvami. Obojí je pravda a hlásí se jen jedno z toho."],["Zvraťte to. Omluvte se těm čtyřem stům jmenovitě.","Jmenovité uvedení je to, co skutečně zapůsobí. Dva z nich se rozpláčou v přímém přenosu a reportáž se vysílá celý týden."],["Přijměte je zpět jako neplacené dobrovolníky.","Nabídkový dopis je skutečný a je rozeslán čtyřem stům lidí. Devět ho přijme, což je na tomhle příběhu ta opravdu znepokojivá statistika."]]},"b-schedule-list":{"t":"Seznam k reklasifikaci","x":"\"Seznam k reklasifikaci.\" Deborah ho opatrně pokládá na stůl. \"Padesát tisíc kariérních míst přesunutých do kategorie s nulovou ochranou před propuštěním. Meteorologové. Posuzovatelé grantů. Dvě stě statistiků.\" Odmlčí se. \"Statistiky bych se bál nejvíc, pane.\"","c":[["Reklasifikovat všech padesát tisíc.","Nikdo nemusí být vyhozen. Padesát tisíc lidí teď prostě ví, že by mohli být, a statistiky, které produkují, se začnou nepatrně, samy od sebe zlepšovat."],["Reklasifikovat jen politické posty. Technické nechat být.","Hranice mezi politikou a měřením, stará sto čtyřicet let, existuje přesně kvůli tomuhle."],["Seznam úplně stáhnout.","Meteorologové dál předpovídají a statistici dál počítají, a za devatenáct měsíců vám jeden z těch součtů zachrání volby."],["Reklasifikovat je a nechat je reklasifikovat vás.","Recipročním formulářem, který koluje jako vtip, vyplní za jeden den jedenáct tisíc federálních zaměstnanců. Výsledky nikdy nikdo nezveřejní."]]},"b-weyland":{"t":"Nesouhlasný badatel","x":"Dr. Weirová vám přinesla něco nečekaného. \"Vážený vědec, který tvrdí opak konsenzu, že instituce drží, že poplach je přehnaný, že tohle přejde.\" Podává vám to. \"Pane prezidente, chci mít jasno, že jsem to přinesla, protože je to dobrá práce, ne proto, že s ním souhlasím.\"","c":[["Dát ho do všech pořadů. Je to protiargument.","Je to opatrný muž, který říká opatrné věci, a tím, že si ho osvojíte, přijde přesně o tu vlastnost, díky které stálo za to si ho osvojit."],["Přečíst si to pořádně. Nic neměnit.","Je to nejzajímavější hodina vašeho prezidentství. Nic z ní neplyne a dr. Weirová se k tomu už nikdy nevrátí."],["Nechat ho debatovat s konsenzem, naživo, a sám se do toho nemíchat.","Dvě hodiny opravdové debaty před devíti miliony lidí. Nic to nevyřeší, ale je to zdaleka nejzdravější věc, co se ten rok stane."],["Jmenovat ho, ať prověří, jestli jste autoritář.","Přijme to pod podmínkou plného přístupu a práva na zveřejnění. Obojí mu písemně přiznáte, aniž byste si zjevně přečetl to druhé."]]},"c-defiance":{"t":"Příkaz, který neuposlechnete","x":"Šest ku třem, a napsáno tak, že by to pochopilo i dítě. Sy přestal dělat poznámky. \"Pane, do dneška každý spor byl o tom, co příkaz *znamená*. Tenhle znamená jen jedno. Pokud ho budete ignorovat, poprvé to tak udělá někdo. A každý badatel, co se tímhle živí, to už napsal černé na bílém: tohle je ta hranice.\"","c":[["Neuposlechnout. Říct to nahlas.","Republika toho odpoledne nepadne. Stane se místo toho něco tišího: každá instituce v zemi si v soukromí přepočítá, na co se může spolehnout, a žádná tu novou hodnotu nezveřejní."],["Uposlechnout, a rok denně útočit na soud.","Poslušnost okořeněná pohrdáním vás strukturálně nic nestojí a koupí vám rok obsahu plného křivd. Je to tah, který udělal každý váš předchůdce, jen nikdy tak nahlas."],["Uposlechnout. Plně. Říct, že to bylo správné rozhodnutí.","Přijdete o politiku i o ten týden. Čtyři badatelé, kteří už napsali, že neuposlechnete, tiše vydají opravu, a ta oprava se ukáže jako to nejcennější, co vlastníte."],["Uposlechnout ve státě, který neexistuje.","Žádost o splnění příkazu uvádí jurisdikci, která není na žádné mapě. Přesto ji zaevidují. Čtyři úředníci stráví čtrnáct dní debatou, jestli je to překlep, nebo manifest."]]},"c-postpone":{"t":"Datum","x":"Deborah za sebou zavřela dveře. \"Existuje argument, špatný, ale argument, že mimořádné pravomoci sahají až na správu federálních voleb.\" Nesedá si. \"Pane, pracuju pro vás čtyři roky. Chci mít v záznamu, že jsem vám řekla, že tohle je ta chvíle.\"","c":[["Odložit je. O devadesát dní. Kvůli bezpečnosti.","Čtyři guvernéři oznámí, že volby uspořádají stejně, v původním termínu, podle státního práva, na které mají plné právo. Jediná otevřená otázka je, jestli je někdo přijde zastavit."],["Volby uspořádat. Napadnout každý těsný okres potom.","Bojovat proti sčítání je boj uvnitř systému. Zrušit sčítání ne. Ten rozdíl vás nic nestojí a ukáže se, že je to celý rozdíl."],["Uspořádat je v termínu. V případě prohry uznat porážku.","Tu větu vyslovíte nahlas, předem, před kamerou. Převáží nad vším, co jste za čtyři roky řekl, a vaše vlastní hnutí vám to, že jste to myslel vážně, tak úplně neodpustí."],["Uspořádat volby o týden dřív, jako překvapení.","Čtyři státy se to dozví poštou. Účast tam skončí na 19 procentech a všechny výsledky se zruší, aniž by to musel kdokoli žalovat, protože se pro jednou všichni okamžitě shodli."]]},"c-jail-opponent":{"t":"Obžaloba","x":"Bo má na Cordelii Ruiz-Bloomovou spis a drží ho, jako by byl ještě teplý z tiskárny. \"Nesrovnalost v podání z roku 2019 a procesní argument, za který bych se styděl, kdybych ho měl vyslovit nahlas. Před soudem by to neobstálo.\" Odkládá ho. \"Nemusí to obstát před soudem, aby ji to udrželo v soudní síni dva roky.\"","c":[["Obvinit ji. Dnes. Proces je trest.","Za dvacet šest měsíců ji zprostí viny a do té doby je nejslavnější opoziční osobností na polokouli. Čtyři země, kterým běžně kážete o právním státu, ji dají jako první příklad."],["Vyšetřovat. Neobviňovat. Nechat to viset.","Otevřený spis bez obvinění je verze, která skutečně funguje: všechen stín, žádný proces, a nic, proti čemu by se dalo odvolat."],["Zavřít spis. Říct jí, že jste ho zavřel.","Devět měsíců vám nevěří. Když nakonec uvěří, řekne to veřejně, a stojí vás to čtyři body ve státě, který jste potřeboval."],["Obvinit ji jen z chyby v podání z roku 2019 a z ničeho jiného.","Národní opoziční vůdkyně stojí obviněná kvůli úřednímu formuláři. Maximální trest je pokuta 400 dolarů, kterou zaplatí v hotovosti na schodech soudu, před kamerou, a účtenku si nechá."]]},"c-enabling":{"t":"Zmocňovací zákon","x":"Hal Grimes něco navrhl a vypadá, jako by ho to zaživa zžíralo. \"Čtyři stránky. Dávají vám pravomoc měnit nebo pozastavit jakýkoli zákon během vyhlášeného stavu nouze, a stav nouze vyhlašujete vy.\" Odkládá to. \"Dokážu to protlačit touhle komorou, pane. Přesně to mě děsí.\"","c":[["Schválit ho. Obě komory. Tento měsíc.","Zákonodárný sbor, který si odhlasuje pryč vlastní funkci, byl poslední položkou na seznamu každého badatele. Teď je to jediná odškrtnutá položka."],["Schválit verzi se dvouletou doložkou o zániku platnosti.","Doložka o zániku platnosti je celý rozdíl mezi delegací a abdikací. O dva roky později tiše vyprší, protože ji všichni zapomenou obnovit."],["Nepředkládat ho. Místo toho žádat čtyři konkrétní zákony.","Běžným hlasováním dostanete tři ze čtyř. Jsou trvalé, nenapadnutelné, a nikdo o nich nikdy nenapíše kapitolu do knihy."],["Schválit ho a pravomoc rovnou delegovat zpátky Kongresu.","Zákon, který na vás přenáší pravomoc, a příkaz, který ji hned přenáší zpátky, oba podepsané téhož odpoledne. Čtyři ústavní právníci tomu říkají \"smyčka\" a moudře to tam nechají."]]},"c-vote-machines":{"t":"Certifikace","x":"Čtyři státy dosud necertifikovaly výsledky. Jejich guvernéři jsou z obou stran a řekli přesně totéž: certifikace je pravomoc státu a sčítání je sčítání. Bo: \"Můžeme vydat federální pokyn, ať to pozastaví. Nemá to žádnou právní sílu. Má to obrovské množství té druhé.\"","c":[["Vydat pokyn. Nařídit všem čtyřem pozastavení.","Tři přesto do dne certifikují. Čtvrtý pozastaví na jedenáct dní a jeho zákonodárný sbor je na vlásku od něčeho, o čem se soudí ještě v roce 2039."],["Poslat federální pozorovatele. Žádný pokyn.","Pozorovatelé sledují sčítání a napíší zprávu, že to skutečně bylo sčítání. Je to nejstarší a nejnudnější nástroj v bedně a funguje přesně proto, že takový je."],["Neříkat nic. Certifikace je jejich věc.","Všechny čtyři státy certifikují podle plánu. O čtyři roky později je tohle fakt, na který se při vaší obhajobě odvolávají nejčastěji, a to lidé, u kterých byste to nečekal."],["Certifikovat výsledky sám, odsud.","Podepsaný federální certifikát pro státní volby se pošle do státu, který už vydal vlastní. Jeho tajemník ho založí do složky \"korespondence\"."]]},"c-electors":{"t":"Alternativní volitelé","x":"\"Ve třech státech byla sestavena druhá sada volitelů.\" Sy čte z dokumentu, o kterém zjevně přál, aby mu nikdy nepřistál na stole. \"Žádný právní základ. Podepsané formuláře. Pane, celá teorie je, že podepsaný formulář vytvoří spor, a spor vytvoří volbu.\"","c":[["Předat všechny tři sady. Ať si vybere Kongres.","Čtyři z lidí, kteří ty formuláře podepsali, jejich vlastní státy do dvou let stíhají. Nikdo z nich nedostal informaci, že tohle je na stole."],["Předat je, ale zbavit se jakéhokoli právního účinku.","Sada volitelů zbavená účinku je tisková zpráva s ověřeným podpisem. Vyvolá veškerou nevoli a žádná obvinění."],["Odmítnout sady. Veřejně. Jmenovitě.","Tiše uchráníte čtyřicet jedna lidí trestní odpovědnosti, o které se nikdy nedozvědí, protože věc, které jste zabránil, nikdy nedostane jméno."],["Sestavit třetí sadu, která hlasuje pro opozici.","Předloženo čistě proto, aby to zamotalo záznamy, a povede se to nad veškerá rozumná očekávání. Nikdo, na žádné straně, si to nedokáže vysvětlit devět měsíců."]]},"c-third-term-poll":{"t":"Otázka v průzkumu","x":"Nadia Fisková spočítala čísla. \"Čtyřicet jedna procent vašich vlastních voličů říká, že byste měl zůstat i po skončení funkčního období. Ne 'zvážil bych to'. 'Měl by.'\" Zvedne oči. \"Pane, tu otázku jsem do průzkumu nedala já. Někdo z vašeho týmu mě o to požádal, a chci to mít v záznamu.\"","c":[["Zveřejnit číslo. Nechat ho, ať odvede práci.","Číslo není návrh, a právě proto je užitečnější než návrh. Nikdo ho nemusí hájit a všichni na něj musí reagovat."],["Průzkum zamést pod koberec. Tu otázku už nikdy nepokládat.","Nadia sama smaže data. O čísle vědí čtyři lidé v budově a žádný z nich ho už nikdy nevysloví nahlas."],["\"Dvě funkční období, to je smysl úřadu.\" Říct to jednou.","Jedna jasná věta ukončí devět měsíců spekulací v jednom zpravodajském cyklu. Vaše hnutí to oplakává jako smrt v rodině."],["Zeptat se i na čtvrté funkční období.","Podpora je 29 procent, což je záhadně zároveň nižší i vyšší, než kdokoli čekal. Nadia tomu říká \"nejhorší číslo, jaké jsem kdy sama vyprodukovala\"."]]},"c-term-reset":{"t":"Dodatek, který vynuloval hodiny","x":"Dr. Weirová přinesla srovnávací materiál. \"Bylo to uděláno pořádně. Ústavní dodatek, referendum, opravdová většina. Hodiny se vynulovaly a už odsloužená funkční období jednoduše přestala počítat.\" Zavírá složku. \"Pane prezidente, to není převrat. To je papírování.\"","c":[["Zahájit proces schvalování dodatku. Veřejně.","Vyžaduje třicet osm států a vy máte devatenáct. Pokus je pro vás cennější, než by kdy byl dodatek sám, a všichni zúčastnění to vědí."],["Nechat přátelský zákonodárný sbor státu, ať to navrhne. Sám se do toho nemíchat.","Vy jste o nic nežádal. Bylo to navrženo. Ten rozdíl je nosnou zdí celého podniku a drží celé dva roky."],["\"To dělají jiné země.\" Nechat to tak.","Táhnout čáru u cizí ústavy je nejlevnější vlastenectví, co je k mání, a v tomhle konkrétním případě je navíc upřímné."],["Navrhnout dodatek, který zkrátí funkční období na dva roky.","Nikdo nedokáže určit, jestli je to blaf, past, nebo opravdové přesvědčení. Získá to čtyři spolupředkladatele a tiše to zemře ve výboru, aniž by to kdy kdo vysvětlil."]]},"c-gold-room":{"t":"Renovace","x":"Alvin má připravené faktury a fotky před a po. \"Zlaté lišty na římse, kolem dveří, na krbové římse a orlu. Reverzibilní, pane, v tom smyslu, že se to teoreticky dá zase odloupnout.\" Zaváhá. \"Každý návštěvník to hned vyfotí.\"","c":[["Víc zlata. Lišty, zrcadlo, rámy.","Místnost, která působí jako trůnní sál, v budově výslovně navržené tak, aby žádný neměla. Objeví se v devíti stech zahraničních zpravodajstvích do roka."],["Zastavit, kde to je. Stačí to.","Střídmé množství zlata působí jako vkus. Velké množství působí jako argument, a vy jste se zastavil o jednu vrstvu laku před tím, než byste ho vyslovil."],["Zbavit se ho. Obnovit místnost.","Alvin osobně dohlíží na obnovu a poprvé za čtyři roky vypadá opravdu šťastně. Nikdo mimo budovu si toho vůbec nevšimne."],["Pozlatit i zasedačku kabinetu, chodbu a výtah.","Výtah je detail, který napáchá skutečnou škodu. Čtyři sta tisíc lidí si posílá jednu fotku pozlaceného výtahu a ani jeden z nich není na vaší straně."]]},"c-birthday":{"t":"Den volného vstupu","x":"Boyd Hackler má připravenou a podepsatelnou proklamaci. \"Volný vstup do všech národních parků a památníků, na váš narozeniny, navždy.\" Přešlápne. \"Pane, volný vstup do parků je opravdu populární. Problém je jen v datu, a existuje tři sta šedesát čtyři jiných možností.\"","c":[["Podepsat to. Moje narozeniny.","Čtyři miliony lidí dostanou den volného vstupu do parku, vybraný kvůli jednomu muži. Většina z nich zažije nádherné odpoledne, a každou fotku z toho doprovodí krutý popisek."],["Podepsat to místo toho na Den nezávislosti.","Identická politika, univerzálně oblíbená, nepřipsaná nikomu konkrétnímu. Boyd si to založí jako výhru a v soukromí to oplakává jako prohru."],["Žádný svátek. Místo toho pořádně financovat parky.","Dokončí se jedenáct zpožděných údržbových projektů. V Montaně se přestaví most. Nikdo nikdy nevystopuje jediný trám zpátky k vám."],["Podepsat to a účast udělat povinnou.","Slovo \"povinná\" přežije čtyři koncepty a dvě právní kontroly, než ho konečně někdo odchytí v jedenáct večer, noc před tiskem."]]},"c-name-on-buildings":{"t":"Smlouva na cedule","x":"\"Smlouva na cedule pro čtyři sta federálních budov.\" Deborah čte specifikaci nahlas. \"Vaše jméno, nad dveřmi, bronzové, metr vysoké. Pane, ty budovy jsou pojmenované po lidech, kteří jsou mrtví. Není to pravidlo. Je to prostě to, co se historicky vždycky dělalo.\"","c":[["Všech čtyři sta. Bronz. Metr.","Čtyři sta budov teď nese jméno žijícího muže. Sundat je později stojí 60 milionů dolarů, číslo, které bude každá budoucí administrativa ráda opakovat."],["Čtyři budovy. Ty, co jsme opravdu postavili.","Pojmenovat po sobě něco, co jste postavil, je nenápadné. Pojmenovat po sobě něco, co jste nepostavil, vyznívá úplně jinak, a tomu jste se vyhnul."],["Žádná. Budovy si nechají svá jména.","Deborah zaznamená rozhodnutí do spisu jediným slovem, \"zamítnuto\", a je to záznam, na který je za čtyři roky nejpyšnější."],["Pojmenovat je všechny po svých předchůdcích, podle abecedy.","Matoucí, nákladné a nějak úplně okouzlující. Čtyři historické spolky napíšou, že si toho váží, a jeden pošle dort."]]},"c-invasion-within":{"t":"Místnost plná generálů","x":"Každý vlajkový důstojník ve službě je v jedné místnosti, protože jste si je osobně vyžádal. Tarrant má návrh projevu a jednu poznámku. \"Pane, ta fráze je 'invaze zevnitř'. Řeknete ji čtyřem stům lidí, kteří celou kariéru studovali, na koho přesně smí, a na koho nesmí, namířit zbraň.\"","c":[["Říct to. Sledovat místnost.","Nikdo nevstane. Nikdo neodejde. Čtyři sta důstojníků sedí v naprostém tichu a každý z nich to ten samý večer komukoli vytočí."],["Říct to, pak dodat, že myslíte politický argument.","Vysvětlení zapadne pod frázi, jak to vysvětlení vždycky udělá, ale přežije v přepisu, a Tarrant se postará, aby se rozšířilo."],["Vyškrtnout to. Mluvit o náboru a platech.","Dvacet minut o bytových příspěvcích čtyřem stům generálů. Nejlépe přijatý projev celého funkčního období a nedostane se mu naprosto žádného pokrytí."],["Zeptat se místnosti, kdo z nich je ta invaze.","Jeden generál zvedne ruku. Dodnes se neurčilo, jestli to byla neposlušnost, nebo vtip, a on odmítl to vyjasnit."]]},"c-monarch":{"t":"\"Fakticky monarcha\"","x":"Historik v televizi použil dvě slova: fakticky monarcha. Dr. Weirová to sledovala. \"Nemyslel to sprostě, pane prezidente. Myslel to strukturálně, úřad, na kterém neběží žádná účinná kontrola. Řekl to smutně, a přesně proto to zapůsobilo.\"","c":[["Přijmout to. Nechat to vytisknout.","Řada merchandise postavená na varovném štítku. Prodává se výjimečně dobře a citují ji, zcela bez ironie, ve třech zahraničních parlamentech při debatě o vlastních vůdcích."],["Odmítnout to. Vyjmenovat věci, které vás zastavily.","Přesně, zpaměti, jmenujete čtyři prohry u soudu a jeden neúspěšný zákon. Nejpřesvědčivější věc, co za rok uděláte, a vaše základna nenávidí každou slabiku."],["Neříkat nic. Je to jeden historik.","Za jedenáct měsíců se to stane názvem kapitoly a za tři roky názvem knihy, a do té doby už vaše mlčení nikoho nezajímá."],["Formálně, písemně požádat o korunu.","Memorandum úřadu kurátora se ptá, co by to obnášelo. Čtyřsetslovná odpověď bere otázku s naprostou, znepokojivou vážností."]]},"c-restored-republic":{"t":"Obnovení republiky","x":"\"Vrátil to všechno.\" Dr. Weirová popisuje muže mrtvého dva tisíce let. \"Veřejně, formálně, v senátu, každou mimořádnou pravomoc, vzdal se jí na místě. Pak si dvě obyčejné podržel doživotně, a ty dvě se ukázaly jako dostatečné.\" Odmlčí se. \"Je to nejúspěšnější politický manévr v dějinách, pane prezidente, a vypadal přesně jako rezignace.\"","c":[["Udělat to. Vzdát se mimořádných pravomocí. Podržet si ty dvě, na kterých záleží.","Pokrytí je nadšené a téměř úplně mylné. Vzdal jste se třiceti devíti věcí, které jste nikdy nepoužil, a tiše si podržel dvě, které dělají tu práci."],["Vzdát se všech. Doopravdy.","Ne manévr. Skutečné obnovení, provedené pořádně, a stojí vás to všechno, co jste za čtyři roky nashromáždil. Dr. Weirová o tom píše zbytek kariéry."],["Nechat si všechno. Divadlo je pro slabší muže.","Muž z toho příběhu si nechal všechno otevřeně a vlastní senát ho za to probodl. Dr. Weirová to zmíní; vy jí řeknete, že to byla úplně jiná situace."],["Vzdát se jich v latině.","Proklamace je vydána jen v latině. Čtyři klasičtí filologové najdou tři gramatické chyby a jeden napíše 6000 slov jen o konjunktivu."]]},"c-acerbo":{"t":"Pravidlo dvou třetin","x":"Halovi ukázali něco z roku 1923 a už to nedokáže odestat. \"Změna volebního zákona. Kdo skončí první, jakkoli těsně, jakkoli malým rozdílem, dostane dvě třetiny mandátů.\" Je bledý. \"Schválil to parlament, kterému pak nezbylo nic dalšího ke schválení. Pane, ukazuju vám to, abyste to viděl.\"","c":[["Připravit americkou verzi. Předložit ji.","Neprojde. Bude předložena, což znamená, že teď existuje, což znamená, že může být předložena znovu, jednou, někým se skrupulemi menšími než vy."],["Místo toho agresivně přeskupit volební obvody. Stejný výsledek, běžné nástroje.","Devět států předělaných až na hranici zákona. Naprosto konvenční, naprosto brutální, a obě strany to dělají už dvě stě let."],["Nic. Buď mandáty vyhrát, nebo ne.","Přijdete o jedenáct mandátů, které byste jinak měl. Zbyde komora, která vám ještě dokáže technicky říct ne, a za devatenáct měsíců to udělá."],["Přiznat dvě třetiny mandátů tomu, kdo skončí druhý.","Navrženo čistě proto, aby to ilustrovalo tu svévoli. Čtyři poslanci se k tomu upřímně připojí a jeden pronese v jeho prospěch skutečně dojemný projev."]]},"c-judicial-purge":{"t":"Čtyři tisíce","x":"Předsedkyně Nejvyššího soudu Stoneová přišla osobně a přinesla výtisk. \"Čtyři tisíce soudců a žalobců odvoláno během jediného roku, v zemi, kde se pořád konají volby. Sto padesát novinářů uvězněno.\" Položí to na stůl. \"Neobviňuju vás z ničeho, pane prezidente. Říkám vám, jak to vypadá zevnitř, protože lidé, kterým se to stalo, to taky neviděli přicházet.\"","c":[["Zahájit přezkum chování federálních soudců. Celé.","Nikdo není odvolán. Devět set soudců je teď prostě lidí se spisem, a soudce se spisem rozhoduje jinak, což byl jediný výsledek, který kdo kdy potřeboval."],["Přezkoumat jedenáct, kteří proti nám rozhodli nejčastěji.","Cílit na viditelné je horší než cílit na všechny, protože vzorec je od prvního dne jasně čitelný a devět médií zveřejní seznam do oběda."],["Poděkovat jí. Neudělat vůbec nic.","Už to nikdy nezmíní. O dva roky později, v případu, který zoufale potřebujete, napíše nečekané souhlasné stanovisko, a vy se nikdy nedozvíte proč."],["Nabídnout, že se necháte přezkoumat soudní mocí místo toho.","Formální žádost, aby soudní konference prošetřila vaše vlastní chování. Přijmou ji. Zprávu podá za čtyři roky, kdy už to bude problém někoho jiného."]]},"c-crossed-over":{"t":"Text, který říká, že jsme to překročili","x":"Dr. Weirová má ten text. \"Tvrdí, že země přestala být plnou demokracií, ne že se stala diktaturou, ale že sklouzla do jiné kategorie úplně. A říkají, že ten obrat byl rychlejší než první rok čtyř případů, které jmenují.\" Pokládá to. \"Pane prezidente, jejich slovo je *soutěživá*. Volby jsou pořád skutečné. To je celý ten rozdíl a odvádí to spoustu práce.\"","c":[["Dokázat, že mají pravdu. Naplno se do toho opřít.","Text dostane nový oddíl v druhém vydání. Citují vás čtyřicet jednou, a ani jedna citace není laskavá."],["Dokázat, že se mýlí. Udělat jednu věc, o které řekli, že neuděláte.","Podřídíte se rozsudku, kterému jste se snadno mohl vzepřít, a přijdete o politiku, kterou jste chtěl. Dva ze čtyř autorů to veřejně zaznamenají, jediná oprava, kterou o vás kdy vydají."],["Napadnout metodologii. Financovat konkurenční index.","Váš index řadí zemi na čtvrté místo na světě. Nikdo ho necituje, nakonec ani lidé, které jste zaplatil, aby ho vytvořili."],["Zeptat se jich, jaké skóre by to napravilo, a přesně to obejít.","Odpoví upřímně a podrobně, protože to akademici dělají. Vylepšíte devět ukazatelů, aniž byste změnil jedinou skutečnou věc, a skóre se posune o čtyři body nahoru."]]},"c-index-drop":{"t":"Padesáté první","x":"Muriel má otevřený index. \"Z dvacátého na padesáté první místo za jeden rok. Poprvé za víc než padesát let mimo nejvyšší klasifikaci.\" Otočí stránku. \"Věta, kterou pořád dokola čtou na každém zahraničním ministerstvu, je ta o *rychlosti*, pane. Říkají tomu bezprecedentní v moderních dějinách.\"","c":[["Vystoupit z organizace, která ten index financuje.","Je to akademické konsorcium na švédské univerzitě, a vy ho nefinancujete. I tak se pokus o jeho zrušení dostane do titulků ve čtyřiceti zemích."],["Zpochybnit žebříček. Ignorovat rychlost.","O žebříčku samotném se nikdo nechystal hádat. Šlo vždycky o tempo poklesu, a vy jste se právě rozhodl o tom nevést spor."],["Zveřejnit dílčí skóre a napravit tři nejhorší.","Nezávislost soudnictví, přístup tisku, kapacita dohledu. Náprava tří ukazatelů trvá jedenáct měsíců a vrátí vás na třicáté čtvrté místo."],["Požádat o zařazení do úplně jiné kategorie.","Formální žádost, aby byla země hodnocena jako rozvíjející se demokracie místo etablované. Zdvořile zamítnuto ve čtyřech různých jazycích."]]},"c-insurrection-act":{"t":"Zákon bez definice","x":"\"Zákon nikde nedefinuje povstání.\" Tarrant to konstatuje suše, spíš jako fakt než argument. \"Říká, že smíte jednat, jakmile usoudíte, že nějaké probíhá. Žádný test, žádná hranice, a žádný soud tu volbu nikdy nezpochybnil.\" Čeká. \"Pane, to je nejširší pravomoc, jaká v americkém právu zbývá, a byl byste první za padesát osm let, kdo ji takhle skutečně použije.\"","c":[["Použít ho. Celostátně.","Řadové jednotky v amerických ulicích na základě zákona bez definice a bez kontrolora. Je to nejzákonnější věc, co jste kdy udělal, a přitom se nepodobá ničemu z toho, co jste dělal dřív."],["Použít ho pro jedno město. Na dvacet jedna dní. Písemný limit.","Limit, který si sám uložíte, je jediný limit kdekoli v celém zákoně. Tarrant tu dvaceti jednodenní lhůtu vepíše do příkazu osobně a děkuje vám za to."],["Nepoužívat ho. Nasadit gardu pod velením státu.","Pomalejší, a přece to funguje, protože guvernéři se zájmem na výsledku se ukážou být užitečnější než vojáci s příkazem v ruce."],["Použít ho proti počasí.","Proklamace prohlásí hurikán za povstání. FEMA a Severní velitelství svolají společný hovor jen proto, aby zjistili, kdo z nich to teď má za úkol."]]},"c-registry":{"t":"Seznam úplně všech","x":"Duane Krisp má návrh od dodavatele. \"Sloučit všechny federální databáze. Daně, dávky, cestování, licence, imigrační status. Každá zvlášť zákonná.\" Odkládá to. \"Pane, dohromady je to jeden spis o tři sta čtyřiceti milionech lidí, a o tom dohromady nikdy nikdo nehlasoval.\"","c":[["Postavit to. Celé. Jeden soubor.","Funguje to přesně, jak slibovali, a v prvním roce se do toho dotáže devět milionů dotazů. Čtyři z nich se později ukáží jako dotazy na novináře."],["Sloučit jen sady relevantní pro imigraci.","Užší systém s deklarovaným účelem, jediný druh, který kdy přežije soudní přezkum. Dělá to taky 80 procent toho, co jste vlastně chtěl."],["Zabít to. Napsat pravidlo proti sloučení.","Pravidlo přežije vaši administrativu o desítky let a dodavatel žaluje za náklady na vývoj a prohraje na plné čáře."],["Postavit to a dát to na veřejné webové stránky.","Radikální transparentnost dotažená do logického konce. Zůstane to online jedenáct minut, což je o devět minut déle, než trvalo, než to bylo archivováno navždy."]]},"c-data-center":{"t":"Zařízení v poušti","x":"Errol Hance má plán lokality. \"Úložiště je teď v podstatě neomezené. Můžeme uchovávat všechno, navždy, na základě teorie, že to jednou možná budeme potřebovat.\" Nesedá si. \"Pane, pravidla byla napsaná v době, kdy bylo úložiště drahé. Pravidla počítala s tím, že si stejně budeme muset vybírat.\"","c":[["Uchovat všechno. Navždy. Rozhodnout proč později.","Trvalý záznam o celé zemi, uchovávaný pro účel, který ještě nikdo nevymyslel. Zdědí ho čtyři budoucí administrativy a ani jedna z nich nesmaže jediný bajt."],["Uchovat to, s pětiletým plánem výmazu.","Lhůta uchovávání je jediná smysluplná brzda takového systému, a nestojí nic, dokud je budova napůl prázdná."],["Sbírat jen s určeným účelem.","Errol proti tomu dvacet minut v kuse argumentuje, pak to bezchybně provede, přesně to, co dělá s každým rozhodnutím, které prohraje."],["Naplnit zařízení místo toho papírovými spisy.","Čtyři miliony krychlových stop tištěných záznamů, dovezených vlakem během devíti měsíců. Naprosto bezpečné a naprosto neprohledatelné, což jistí lidé rozhodně upřednostňují."]]},"c-church":{"t":"Národní bohoslužba","x":"Reverend Dale Muncy přišel s návrhem a neobvykle váhá. \"Týdenní bohoslužba, v budově, vysílaná, s kanceláří placenou z rozpočtu.\" Obrací klobouk v rukou. \"Pane, přišel bych. Chci být upřímný, že si nejsem tak úplně jistý, jestli mám být ten, koho se ptáte.\"","c":[["Financovat kancelář. Vysílat bohoslužbu. Týdně.","Čtyři denominace, které vás podporovaly, protestují první a nejhlasitěji, protože o téhle historii toho přečetly podstatně víc než kdokoli u vás v kanceláři."],["Konat bohoslužbu. Bez federálního financování, bez kanceláře.","Soukromá bohoslužba v soukromém sídle, přesně to, na co má každý obyvatel té budovy vždycky nárok."],["Pozvat jedenáct vyznání na rotaci. Nefinancovat žádné.","Rotace, která rovnoměrně otravuje všechny a zákonně neurazí nikoho. Dale si vezme čtvrtou neděli a nazve to nejspravedlivější nabídku na stole."],["Prohlásit se hlavou nové denominace.","Zakládací listina je doslova podaná v Delaware. Devět tisíc lidí se přihlásí do čtrnácti dnů a Dale ten samý den odpoledne rezignuje."]]},"c-broadcast-license":{"t":"Slyšení o obnovení licence","x":"Blíží se obnovení licence a váš regulátor svolal slyšení o \"veřejných zájmových povinnostech\". Kaylee: \"Obnovení je rutina, pane. Rutina je to už šedesát let. Naplánovat kvůli tomu slyšení je celé to sdělení, a všichni v oboru ho dostali už před devátou ráno.\"","c":[["Slyšení uspořádat. Skutečně ohrozit licenci.","Licence se obnoví. Za jedenáct měsíců, co to trvalo, síť tiše vyměnila dva moderátory a jednoho výkonného producenta, a nikdo je o to nemusel žádat."],["Slyšení uspořádat. Obnovit ji na konci.","Proces s předem daným výsledkem je stojí rok právního rozpočtu a rok opatrnosti, což je většina toho, co jste stejně chtěl."],["Obnovit ji automaticky, jako posledních šedesát let.","Nic se nestane. Je to učebnicové vyřízení obnovy licence a neobjeví se to přesně v žádných novinách na světě."],["Udělit licenci síti, která neexistuje.","Fiktivní žadatel s poštovní schránkou vyhraje licenci na velký trh. Čtyři měsíce vysílá zkušební obraz, než si toho na úřadu někdo všimne."]]},"c-cabinet-25":{"t":"Dvacátý pátý dodatek","x":"Chet Danforth požádal o soukromou schůzku a nikoho s sebou nepřivedl. \"Existuje mechanismus,\" říká opatrně, \"který potřebuje mě a většinu kabinetu. Chci, abyste věděl, že se mnou o tom čtyři lidi už mluvili, a já jsem všem čtyřem řekl ne.\" Odmlčí se. \"Říkám vám, že jsem jim řekl ne.\"","c":[["Vyměnit ty čtyři. A vyměnit Cheta.","Kabinet teď vybraný výhradně pro neochotu vás odvolat. Každé rozhodnutí, které od teď udělá, dělají lidé vybraní přesně pro tuhle vlastnost."],["Vyměnit ty čtyři. Cheta nechat na dohled.","Zůstane, protože jednou řekl pravdu v práci, kde se právě ukázalo, že to lze přežít. Než skončí funkční období, udělá to ještě dvakrát."],["Poděkovat mu. Nic neměnit.","Mechanismus už od nikoho nikdy nezazní, po zbytek funkčního období. Jestli je to loajalita, nebo prostá aritmetika, se nikdy úplně nedozvíte."],["Použít ho proti sobě, ať vidíte, co se stane.","Sepíše se, a katastrofálně skutečně odešle, dopis o vaší vlastní nezpůsobilosti. Chet je úřadujícím prezidentem padesát jednu minutu a nedělá s tím vůbec nic."]]},"c-treaty":{"t":"Dohoda, která nebyla smlouvou","x":"Muriel má dokument. \"Práva na základnu, klauzule o vzájemné bezpečnosti, čtyřicetiletá platnost. Nazvete to smlouvou a potřebujete šedesát sedm senátorů, které nemáte. Nazvete to výkonnou dohodou a stačí váš podpis.\" Zvedne oči. \"Pane, je to identický dokument tak jako tak.\"","c":[["Podepsat to jako výkonnou dohodu. Čtyřicet let.","Čtyřicetiletý závazek vzájemné bezpečnosti, uzavřený jedním mužem za odpoledne. Druhá země to považuje za závazné, a to je ta část, kterou už nikdy nikdo nemůže vzít zpět."],["Poslat to jako smlouvu. Bojovat o těch šedesát sedm.","Po devíti ponižujících měsících vyjednávání seženete sedmdesát jedna hlasů. Nezrušitelné žádným nástupcem, což se výkonné dohodě nikdy nepovedlo."],["Podepsat pětiletou verzi. Zbytek nechat na Kongresu.","Krátká dohoda, která kupuje čas na pořádnou smlouvu později. Muriel tomu říká profesionální odpověď a myslí to jako skutečnou pochvalu."],["Podepsat to jako smlouvu, dohodu i memorandum zároveň.","Tři dokumenty, stejný text, tři různé právní statusy. Druhá země ratifikuje všechny tři, možnost, se kterou nikdo vlastně nepočítal."]]},"c-emergency-extend":{"t":"Obnovení, které nikdo nečte","x":"\"Vyhlášení se automaticky obnovuje, pokud neřeknete jinak, a Kongres to může ukončit usnesením, což neudělá.\" Sy má formulář připravený. \"Jeden podpis, pane. Čtvrté obnovení. Původní stav nouze v jakémkoli obyčejném slova smyslu skončil zhruba před dvěma lety.\"","c":[["Obnovit ho. A těch dalších jedenáct taky.","Dvanáct stavů nouze, z nichž žádný není nouzí, všechny nosné. Pravomoci jsou teď prostě způsob, jak se země vede, a nikdo pro to nikdy nehlasoval."],["Obnovit jen ty čtyři, které opravdu ještě fungují.","Nechat osm propadnout se u vašich lidí interpretuje jako slabost, u ostatních jako zdravý rozum. Obojí čtení je k dispozici a ani jedno není chybné."],["Nechat je všechny propadnout. Vládnout podle zákonů.","Dobrovolně se vzdáte toho aparátu. Čtyři politiky se okamžitě zhroutí a dvě, které přežijí, se ukážou jako jediné dvě, které kdy byly skutečné."],["Obnovit ho na sto let.","Nástroj uvádí datum vypršení někdy ve dvaadvacátém století. Zveřejní se to. Ve Federálním registru to nemá nikdo pravomoc zpochybnit."]]},"c-lincoln":{"t":"Precedens, který byste preferoval","x":"\"Vaši obhájci pořád sahají po jednom konkrétním prezidentovi,\" říká dr. Weirová. \"Pozastavil habeas corpus, fakticky ignoroval sedícího soudce Nejvyššího soudu a zvažoval odklad voleb.\" Nechá to viset ve vzduchu. \"Pane prezidente, srovnání je přesné. Je to ale taky srovnání s mužem, který tohle všechno dělal během občanské války, a na vašem místě bych ho používal velmi opatrně.\"","c":[["Spoléhat se na to pořád. Má pravdu.","Každý oslovený historik odpoví stejnými třemi slovy o té válce, a ta tři slova jsou nezvratná, a vy k tomu srovnání přesto pořád sahá."],["Srovnání zavrhnout. Najít mírové.","Žádné neexistuje, což je to skutečné zjištění, a dr. Weirová se to ani neobtěžuje vyslovit nahlas, protože nemusí."],["Tvrdit, že nouze *skutečně existuje*, a pojmenovat ji.","Pojmenovat stav nouze je nutný předpoklad pro všechno, co následuje, a jednou pojmenovaná se už nikdy tiše neodpojmenuje, aniž byste se toho vzdal celého."],["Zeptat se jí, kterému prezidentovi se nejvíc podobáte.","Odpoví okamžitě, bez sebemenšího zaváhání, jménem někoho z padesátých let 19. století, o kom v místnosti nikdo nikdy neslyšel. Čtyři dny trvá pochopit, jak kruté to bylo."]]},"c-fdr":{"t":"Čtyři funkční období","x":"Dr. Weirová má připravené další srovnání. \"Dvanáct let, čtvery volby, celá federální vláda přebudovaná od základu, a internace. Taky se pokusil rozšířit soud a jeho vlastní strana ho veřejně odmítla.\" Dodává: \"To odmítnutí je ta část, kterou vaše strana nikdy necituje, pane prezidente, a je to ta část, na které záleželo.\"","c":[["Zkusit rozšíření soudu. Zjistit, jestli vás tahle strana odmítne.","Devět vašich vlastních senátorů odmítne do týdne. Největší jednorázový akt odporu z vaší vlastní strany za čtyři roky, a nikdy se z toho úplně nezotavíte."],["Nezkoušet to. Přijmout ten bod.","Zdržíte se pokusu o něco, co byste stejně jen prohrál. Nikdo si nevšimne věci, ke které nedošlo, a proto se zdrženlivost nikdy neoceňuje."],["Rozšířit místo toho nižší soudy. Tam se nikdo nedívá.","Šedesát tři nová okresní soudcovská místa obsazená za čtrnáct měsíců. Zlomek pokrytí za mnohonásobný skutečný efekt."],["Zmenšit soud na sedm.","Zákon zmenšující lavici odvoláním jeho dvou nejnověji potvrzených členů. Oba jste potvrdil vy, fakt, který na plénu zazní ve velké délce."]]},"c-uncommon-momentum":{"t":"Malá energie na legislativu","x":"Hal má žlutě zvýrazněnou větu z think-tanku. \"'Neobvyklé rané tempo', a pak tohle: 's malou energií vynaloženou na legislativní cesty.'\" Kouká přes okraj stránky. \"Pane, to je zdvořilý způsob, jak říct, že nic z toho není zajištěné, a říkám vám to už dva roky, jen míň zdvořile.\"","c":[["Zachovat tempo. Zajišťovat věci je pomalé.","Všechno, co jste vybudoval, stojí jen na vašem podpisu. Váš nástupce zruší 80 procent toho za jedno odpoledne, přesně tím stejným nástrojem, co vy."],["Poslední dva roky věnovat proměně příkazů na zákony.","Čtyři návrhy zákonů, dva projdou. Jsou to jediné části vašeho prezidentství, které za dvacet let ještě stojí, a nikdo si nepamatuje, že jsou vaše."],["Dělat obojí. Prosadit ty čtyři, co záleží, ostatní vydat příkazem.","Přístup, který nepotěší nikoho z obou stran, a s odstupem dvaceti let se ukáže jako naprosto správný."],["Nechat Kongres schválit jeden zákon, který ratifikuje všechny příkazy naráz.","Dvě stě sedmnáct příkazů ratifikovaných v jednom hlasování, poslanci, kteří mezi sebou přečetli čtyři z nich. Projde o jedenáct hlasů a je napaden hned další ráno."]]},"c-succession-machine":{"t":"Hnutí po vás","x":"Chet má vnitřní čísla a viditelně z nich radost nemá. \"Hnutí má podporu padesát čtyři procent. Vy máte čtyřicet jedna.\" Nechá to chvíli viset. \"Pane, přerostlo vás. To je buď to nejlepší, co jste kdy vybudoval, nebo poslední problém, jaký kdy budete mít, a já upřímně nevím, co z toho.\"","c":[["Svázat ho se sebou. Přísahy loajality, moje jméno na všem.","Hnutí, které vás nemůže přežít, taky nemůže vás přežít, a obě fakta se stanou pravdou v ten samý den, který jste si nevybral."],["Vybudovat instituci. Nechat ji přežít mě.","Stranický aparát s pravidly, pokladnou a procesem nástupnictví. Vyhraje tři z dalších pěti voleb a od druhých voleb vás už skoro nezmiňuje."],["Předat ho teď Chetovi, dokud si mohu vybrat.","Přijme to vděčně a kompetentně, a do jedenácti týdnů udělá rozhodnutí, aniž by se vás nejdřív zeptal, a nic se mu za to nestane."],["Nechat hnutí odhlasovat, jestli vás ještě potřebuje.","Nadia vás prosí, ať to nedělá. Přesto to zadáte. Číslo se vrátí na 38 procent a unikne do čtyř dnů, a ten únik je zdaleka nejmenší z vašich problémů."]]},"c-what-was-it-for":{"t":"Otázka ve dveřích","x":"Je pozdě a Deborah už ani nepředstírá, že drží složku. \"Čtyři roky. Dvě stě sedmnáct příkazů, jedenáct stavů nouze, čtyři sta budov s vaším jménem.\" Není v tom žádná krutost. \"Pane, kdybych se zeptala, co z toho vás přežije, co byste vlastně řekl?\"","c":[["\"Všechno. Protože nikam neodcházím.\"","Zapíše si to. Je to věta, kterou začíná každý popis téhle administrativy napsaný v následujících čtyřiceti letech, a je to ona, komu se přisuzuje, že ji zachytila."],["\"Soudci. Soudci přežijí všechny.\"","Je to správná odpověď. Dvě stě třicet jedna doživotních jmenování, průměrný věk čtyřicet šest, jediná věc tady, která je opravdu trvalá."],["\"Upřímně? Ty dva zákony. Možná.\"","Deborah chvíli mlčí. Pak řekne \"ano\" a odejde, a je to nejblíž, co za čtyři roky dostanete ke schválení."],["\"Ten sál.\"","Je, uznejme, velmi pravděpodobné, že bude ještě stát. Uzná ten bod, a ani jeden z vás se k tomu rozhovoru už nikdy nevrátí."]]},"c-lame-duck":{"t":"Slovo, které nikdo neříká","x":"Nadia má to znamení. \"Čtyři předsedové výborů tento týden nevrátili hovor. Ne nepřátelsky, jen zaneprázdněně. Pane, přesně takhle to vypadá. Nikdo neoznámí, že se vás přestal bát. Jen se najednou stane hrozně, hrozně zaneprázdněným.\"","c":[["Udělat z jednoho z nich příklad. Veřejně.","Přežije primárky o devět bodů, a ostatní tři prostě přestanou vůbec zvedat telefon. Strach je měna a vy jste právě zjistil, že kurz je špatný."],["Dát jim, co chtějí. Koupit si poslední dva roky.","Čtyři obvodní projekty a předsednictví výboru. Transakční, neefektní a koupí to jedenáct dalších měsíců fungující většiny."],["Ignorovat to. Vládnout příkazy až do posledního dne.","Na příkaz je nepotřebujete, a přesně proto je příkaz cenný podstatně méně než ta věc, kterou od nich už nedostanete."],["Zavolat všem čtyřem ve tři ráno, jestli jsou v pořádku.","Všichni čtyři to zvednou. Všichni čtyři jsou velmi znepokojeni. Tři z nich pak šest měsíců vracejí každý hovor; čtvrtý si jednoduše změní číslo."]]},"c-library":{"t":"Knihovna","x":"Miriam má otevřené účty nadace. \"Čtyři sta deset milionů, pane. Z vyrovnání, od dárců s věcmi projednávanými před vládou, a od čtyř cizích státních příslušníků.\" Pokládá to. \"Je to knihovna. Žádná povinnost zveřejnění vůbec. To není mezera v zákoně. Je to prostě zákon.\"","c":[["Vzít to všechno. Je to knihovna.","Nikdo nikdy nikoho úspěšně nenapadl kvůli knihovně. Je to nejčistší způsob, jak dostat peníze v americkém veřejném životě, a vždycky tomu tak bylo."],["Zveřejnit všechny dárce dobrovolně.","Jedenáct dárců se do čtrnácti dnů stáhne, což leccos napovídá o těch jedenácti. Zbylý seznam je nudný a naprosto neotřesitelný."],["Odmítnout zahraniční peníze. Zbytek vzít.","Jedna linka, vedená někam, kde se snadno hájí a snadno ověřuje. Miriam tomu říká \"minimum\" a schválí to."],["Postavit knihovnu bez jediné knihy.","Zařízení o 90 000 čtverečních stopách obsahující čtyři sta fotografií, obchod se suvenýry a repliku kanceláře. Návštěvnost prvního roku předčí každou předpověď."]]},"c-pardon-list":{"t":"Seznam na poslední stránce","x":"Sy má milostný seznam připravený. \"Čtyřicet jedna jmen. Devět z nich pro vás pracovalo. Čtyři odmítli spolupracovat s vyšetřováním proti vám.\" Nekomentuje to. \"Pane, ta pravomoc je nepřezkoumatelná. Žádný soud, žádné hlasování, žádné odvolání. Je to jediná věc v celé ústavě, na kterou vůbec žádná kontrola neplatí.\"","c":[["Podepsat všech čtyřicet jedna. Poslední ráno.","Nepřezkoumatelné znamená nepřezkoumatelné. Nikomu z nich se nikdy nic nestane, a vzkaz všem, kdo ještě sedí na nějakém tajemství, dorazí naprosto jasně."],["Podepsat těch devět se skutečně nepřiměřenými tresty.","Devět obhajitelných případů, každý s vlastním memorandem. Dvě advokátní skupiny, které vás nesnáší, vydají prohlášení podpory, což nikdo nečekal, oni nejméně."],["Nepodepsat žádnou.","Čtyři lidé, kteří kvůli vám mlčeli, přesto jdou do vězení. Jestli je to integrita, nebo nevděk, se dohaduje třicet let."],["Preventivně omilostnit úplně všechny v zemi.","Plošná proklamace všeobecné milosti pro každý federální trestný čin. Podepsáno ve čtyři ráno, zrušeno v sedm, existovalo to celkem tři hodiny."]]},"c-guardrails":{"t":"Co vydrželo","x":"Dr. Weirová přišla se rozloučit a přinesla přesně jednu stránku. \"Závěr literatury, k dnešnímu dni: soudy proti vám pořád rozhodovaly a vy jste je občas poslechl. Volby se konaly a opozice tu a tam vyhrála. Na tisk se tlačilo a přesto dál publikoval.\" Podává to. \"Pane prezidente, každá z těch vět je o něčem, co se nestalo. To je, co znamená hráz.\"","c":[["Pak najít tu, která ještě nebyla testovaná.","Vždycky nějaká existuje. Zbytek funkčního období strávíte hledáním, a samo to hledání se ukáže jako nejnebezpečnější věc, co za celé volební období uděláte."],["Nechat je stát. Vzít si výhru, kterou máte.","Nakonec jste prezident, který úřad enormně rozšířil, a přesto ho nechal fungovat. Nejméně uspokojivý dostupný výsledek, a nejvzácnější."],["\"Vydržely, protože jsem to dovolil.\" Říct to veřejně.","Je to chvástání, které naráz přizná úplně všechno. Čtyři badatelé to citují jako nejodhalující větu celé administrativy, a žádný z nich se nemýlí."],["Požádat ji, ať to sepíše jako seznam, abyste to mohl projít.","Odmítne, poprvé za čtyři roky, jediným slovem. Pak zvedne kabát a naposledy opustí budovu."]]},"e-covfefe":{"t":"To slovo","x":"Usnul jste uprostřed příspěvku a věta se prostě zastaví, po slovu, které není slovo, před jedenácti miliony lidí. Brayden má čísla. \"Čtyři sta tisíc sdílení, pane. Je to nejsledovanější věc, co jste kdy napsal, a nikdo, včetně vás, neví, co to znamená.\"","c":[["Nechat to tam. Říct, že jen vy víte, co to znamená.","Slovo, které neznamená nic, se stane heslem, tričkem a nakonec dostihovým koněm, a přežije všechny politické úspěchy vašeho funkčního období dohromady."],["Smazat to a zveřejnit dokončenou větu.","Dokončenou myšlenku o obchodních deficitech si přečtou čtyři tisíce lidí. Ten překlep měl jedenáct milionů a dokončení nepotřeboval."],["Podrobně vysvětlit, že to byl překlep.","Vysvětlovat vtip, který jste nechtěl udělat, je jediný známý způsob, jak ho zhoršit. Brayden to sleduje s viditelnou tělesnou bolestí."],["Zařadit ho do slovníku výnosem.","Výnos to definuje jako \"stav pohotovostní bdělosti\". Čtyři lexikografové reagují s upřímným nadšením a jeden napíše esej lepší než cokoli jiného, co vaše administrativa ten rok vyprodukuje."]]},"e-hamberders":{"t":"Bufet","x":"Personál kuchyně je na nucené dovolené, tak jste osobně koupil tisíc rychlých hamburgerů a rozložil je na stříbře pod lustry. Alvin je řadí podle výšky. Ve vašem oznamovacím příspěvku je přeškrtnuté jediné slovo, na kterém záleží.","c":[["Nechat pravopis. Zveřejnit fotku té hromady.","Fotka je opravdu radostná, ten překlep opravdu nesmrtelný, a jedenáct mistrovských sportovců nezávisle na sobě prohlásí, že to byl nejlepší večer jejich života."],["Opravit příspěvek. Nechat hamburgery.","Správný pravopis, stejné hamburgery, čtvrtina pokrytí. Někde v komunikačním oddělení je jeden člověk tiše potěšen a všichni ostatní se posunuli dál."],["Zrušit to. Kuchyni na jednu noc znovu otevřít.","Čtyři propuštění kuchaři dostanou příplatek za vaření pro jedenáct sportovců uprostřed rozpočtového výpadku, a někdo nevyhnutelně spočítá cenu za talíř."],["Podávat je na státním porcelánu.","Sada z roku 1918 po Wilsonovi, pod ohřívacími lampami, obložená cheeseburgery. Kurátorova hlášení má čtyři stránky a čte se jako výhrůžný dopis."]]},"e-misspell-count":{"t":"Běžící součet","x":"Někde je stůl, kde celé funkční období počítají vaše pravopisné chyby. Kaylee má dnešní číslo. \"Devět set čtyři, pane. Mají teď kategorie. Existuje podkategorie pro slova, která jste napsal špatně víc než jedním způsobem.\"","c":[["Zveřejňovat neupravené. Navždy. Je to důkaz, že je píšu já.","Je to důkaz, a čtyři miliony lidí tomu věří přesně z toho důvodu, a shodou okolností mají pravdu. Zapojení je o 22 procent vyšší než u čehokoli, co zveřejní zaměstnanec."],["Nechat je před odesláním číst někoho jiného.","Správný pravopis vyznívá jako výbor, a výbor vyznívá jako všichni ostatní. Účet se přes noc stane nerozeznatelným od čtyř set jiných."],["Jedno slovo pokaždé úmyslně přepsat, navždy.","Stane se to podpisem, pak heslem poznávacím. Podporovatelé to vám začnou přeříkávat zpátky a počítající úřad tu kategorii tiše zruší."],["Vydat vázané opravené vydání vlastních příspěvků.","Dva pevně vázané svazky, profesionálně korigované, prodají se v 90 000 kusech a dostanou seriózní recenzi ve třech literárních přílohách."]]},"e-503":{"t":"Pět set tři","x":"Ověřovací organizace zveřejnila součet za celé funkční období. Kaylee to čte bez emocí. \"Třicet tisíc pět set sedmdesát tři, pane. Zhruba dvacet jedna denně. Denní rekord je pět set tři a padl v pondělí.\"","c":[["Rekord překonat. Úmyslně. Ve čtvrtek.","Do oběda máte přes šest set. Proměnit tabulku ve vlastní skóre ji zničí jako kritiku, a přesně proto to funguje."],["Zpochybnit metodologii. Vydat vyvrácení.","Vyvrácení napadá čtyři sta z třiceti tisíc a zbytek prostě mlčením přizná, a přesně to je ta část, kterou všichni pokryjí."],["Neříkat nic. Číslo je jen číslo.","Zpráva žije den a půl. Nic, co byste mohl říct, by to nezkrátilo, a leccos by to naopak natáhlo na týden."],["Zaměstnat všechny ověřovatele.","Nabídky jdou celému oddělení. Dva přijmou, dostanou se do interní revize, a vytvoří memorandum tak přesné, že je do týdne utajené."]]},"e-stable-genius":{"t":"Sebehodnocení","x":"Ve třetí větě příspěvku jste se písemně popsal jako velmi stabilní génius. Dr. Prine je tu kvůli něčemu jinému a přečetl si to z telefonu ve dveřích. \"Pane, chtěl bych mít v záznamu, že jsem to nepotvrdil.\"","c":[["Zopakovat to. Přidat \"jako fakt hrozně chytrý\".","Obě fráze vstoupí do jazyka natrvalo, a žádnou z nich už nikdy nikdo kromě vás nepoužije upřímně."],["Nechat to být. Neopakovat to.","Řečeno jednou, je to chvástání. Řečeno dvakrát, je to symptom. Zůstanete u jednou, což tady v budově nikdo nečekal."],["Nechat Prina udělat skutečný kognitivní test.","Skórujete naprosto normálně, což polovina země nahlásí jako skandál a druhá polovina jako triumf, ze stejného čísla."],["Objednat test IQ a zveřejnit jen obálku.","Zapečetěná obálka projede čtyři shromáždění a nikdy se neotevře. Jako kus politického divadla je téměř dokonalá."]]},"e-sharpie":{"t":"Opravená předpověď","x":"Řekl jste, že bouře zasáhne stát, který nikdy nebyl v predikovaném kuželu. Mapa předpovědi na stole má teď navíc dokreslenou smyčku černým fixem. Kaylee: \"Pane. Ta mapa je federální vědecký produkt. Její úprava je trestný čin. Někdo ji upravil. Fixem.\"","c":[["Ukázat mapu na kameru. Smyčku nezmiňovat.","Všichni tu smyčku vidí. Nikdo o ní čtyři minuty přímého vysílání nahlas nemluví, a stane se z toho definující obraz roku."],["Nechat meteorologický úřad vydat podpůrné prohlášení.","Nepodepsané prohlášení na vaši podporu vyjde v devět večer. Každý meteorolog v úřadu se ten samý večer dozví, k čemu je úřad teď skutečně."],["\"Dostal jsem raný odhad.\" Jít dál.","Je to dokonce technicky pravda, jeden raný odhad ten stát skutečně zahrnoval. Kdybyste to řekl první den, skončilo by to; čtvrtý den to neskončí."],["Překreslit celé pobřeží, když už u toho jste.","Upravená mapa posune dva státy do vnitrozemí. Vyfotí ji, zarámují, a na katedře meteorologie visí dodnes jako varovný exponát."]]},"e-mortality":{"t":"Číslo z univerzity","x":"Univerzita vypočítala odhad nadúmrtnosti po hurikánu: zhruba tři tisíce. Dr. Pike má metodologii. \"Je to standardní postup, pane, ten samý, který vaše vlastní administrativa používá pro všechno ostatní. Zpochybnit tohle číslo znamená zpochybnit metodu, na kterou spoléháme.\"","c":[["Zpochybnit ho. Říct, že bylo vymyšlené, aby vám uškodilo.","Tři tisíce rodin slyší prezidenta nazvat jejich mrtvé příbuzné politickým konstruktem. Čtyři z nich vystoupí na kameru a příspěvek se vysílá týden."],["Číslo přijmout. Říct, že reakce byla přesto dobrá.","Obhajitelný argument, který skutečně můžete vyhrát, podaný hned vedle čísla, se kterým jste se rozhodl nebojovat. Je to nejkratší možná verze tohoto příběhu."],["Nařídit federální přezkum, ať vyprodukuje vlastní číslo.","Za jedenáct měsíců se vrátí s 2 975, což je pro vás horší než původní číslo, protože teď je oficiálně vaše."],["Házet další papírové utěrky.","Druhá návštěva, druhá tělocvična, druhé házení podpaží. Někdo, kdo byl v místnosti poprvé, je tam znovu, a řekne to na kameru."]]},"e-war-hero":{"t":"Zajatý muž","x":"Před lety jste řekl, že preferujete lidi, kteří se nenechali zajmout. Ten muž je teď mrtvý a dnes ráno, přímo dotázán, jste řekl, že jste nikdy nebyl jeho fanoušek a nikdy nebudete. Styčný důstojník pro veterány si vyžádal čtyři minuty a ještě si nesedl.","c":[["Trvat na tom. Byl přeceňovaný a řekl jsem to.","Čtyři senátoři z vaší vlastní strany zareagují jmenovitě do hodiny. Dva z nich jsou veteráni a jeden vede Senát."],["Dál nic neříkat. Nikdy.","Mlčení to za devět dní utiší. Je to nejlevnější dostupná odpověď a zároveň ta jediná, kterou je pro vás nejtěžší skutečně dát."],["Navštívit hrob. Bez kamer. Bez prohlášení.","Hrobník to o čtyři měsíce později nevyžádaně zmíní reportérovi, který píše o něčem úplně jiném. Zapůsobí to víc, než by dokázalo jakékoli prohlášení."],["Udělit mu posmrtnou medaili za to, že byl zajat.","Text vyznamenání píše někdo na Pentagonu s naprostou upřímností. Je to opravdu dojemné a nemožné přijmout s grácií."]]},"e-parade":{"t":"Obrněnci na třídě","x":"Tarrant má technické posouzení. \"Hlavní bojové tanky váží sedmdesát tun. Třída na tu zátěž není dimenzovaná a mosty taky ne.\" Otočí stránku. \"Dá se to udělat. Silnici budeme opravovat až do října a účet za opravu vyjde dráž než ta přehlídka.\"","c":[["Tanky. Všechny. Dolů po třídě.","Fotografie jsou výjimečné a doletí dál než cokoli jiného, co za rok uděláte. Čtyři spojenecké ambasády pošlou nevyžádané zprávy jen o té symbolice."],["Jen přelet. Žádné obrněnce.","Letadla jsou zdarma, oblíbená a nezanechávají koleje. Stejná přehlídka, desetina ceny, a žádné z titulků, které by vynesly tanky."],["Žádná přehlídka. Peníze do bydlení pro veterány.","Postaví se jedenáct set bytů. Stuhu za čtyři roky přestřihne někdo jiný a vaše jméno na budově nikde nebude."],["Řídit jeden tank osobně.","Seržant vám dá čtyři hodiny výcviku a viditelně si každou minutu užívá. Sejmete pouliční lampu. Vysílá se to živě."]]},"e-greenland-nasty":{"t":"\"Absurdní\"","x":"Nabídl jste koupi jejich území. Jejich premiérka použila slovo absurdní, anglicky, na kameru. Muriel má diář. \"Státní návštěva je za jedenáct dní, pane. Zrušit ji kvůli jednomu přídavnému jménu je možnost. Není to dobrá možnost, ale je to možnost.\"","c":[["Zrušit návštěvu. Nazvat ji protivnou.","Čtyři sta let starý spojenec je veřejně urážen kvůli jedinému slovu. Jejich parlament to den debatuje a jejich turistický úřad hlásí rekordní počet amerických rezervací."],["Jet stejně. Udělat si z toho vtip na večeři.","Sám otevřete tím slovem a místnost se opravdu zasměje. Je to nejlepší diplomatický večer vašeho funkčního období, a nikdo doma o něm neinformuje."],["Nabídku úplně stáhnout. Nikdy ji už nezmiňovat.","Úplně zmizí, osud každého nápadu, který nikdo nebrání. Čtyři poradci se uleví a jeden je, potichu, zklamaný."],["Nabídnout koupi premiérky místo toho.","Myšleno jako vtip, přenesené jako depeše, přijaté jako formální návrh. Odpověď jejich ministerstva zahraničí je mistrovské dílo zdvořilého úžasu."]]},"e-fell-in-love":{"t":"\"Zamilovali jsme se\"","x":"Popsal jste svou korespondenci s dědičným diktátorem frází \"zamilovali jsme se\". Muriel má přepis a tlustou složku reakcí spojenců. \"Pane, čtyři smluvní partneři se zvlášť ptali, jestli tohle znamená změnu politiky.\"","c":[["Zopakovat to. Ty dopisy byly krásné.","Podle každého, kdo je skutečně četl, jsou to kompetentně lichotivé formulářové dopisy sepsané výborem někde v suterénu."],["Zarámovat to jako osobní chemii sloužící národnímu zájmu.","Profesionálně znějící verze totožného tvrzení. Čtyři ministerstva zahraničí s tím dokážou pracovat a ani jedno tomu nevěří ani slovo."],["Vzít to zpět. Osobní vřelost není politika.","Ústup se nahlásí jednou. Ta fráze se hlásí deset let. Je to standardní směnný kurz a nikdy se nezlepší."],["Zveřejnit dopisy v plném znění.","Ukážou se nudnější, než si kdo dovedl představit, a dvakrát zmiňují golfové hřiště. Zveřejnění příběh okamžitě ukončí a zklame naprosto všechny."]]},"e-riviera":{"t":"Přestavba","x":"Navrhl jste, aby Spojené státy převzaly válkou poškozené území a přestavěly ho na letovisko. Muriel drží reakční depeši a ruka se jí netřese ustáleně. \"Devět spojeneckých vlád, pane. Všech devět. Dvě použily slovo 'vysídlení' a jedna mnohem starší slovo.\"","c":[["Rozvinout to. Ukázat vizualizace.","Architektonická vizualizace přímořského letoviska na masovém hrobě se objeví na tiskovce a koluje roky jako doklad číslo jedna něčeho."],["Přerámovat to jako fond na obnovu.","Nudný, obhajitelný, naprosto konvenční návrh pomoci, který čtyři spojenci okamžitě spolupodepíšou. Stejné peníze, žádné pobouření."],["Stáhnout to. Říct, že to byla myšlenka, ne plán.","\"Myšlenka, ne plán\" je přiznání, že prezident řekl věc bez toho, aby ji promyslel, což je menší příběh než ta alternativa, jen o vlásek."],["Nabídnout přestavbu na golfové hřiště místo toho.","Osmnáct mistrovských jamek, navržených za čtyři dny někým, kdo zjevně neměl ponětí, co pod nimi nedávno bylo."]]},"e-fifty-first":{"t":"\"Guvernére\"","x":"Oslovil jste sousedního premiéra veřejně čtyřikrát \"guvernére\" a nahlas uvažoval o hospodářském nátlaku. Muriel: \"Pane, jejich maloobchodní bojkot amerického zboží je teď na devíti procentech dovozu a stoupá, a je naprosto dobrovolný, což znamená, že není s kým to vyjednat pryč.\"","c":[["Dál mu říkat guvernére. Zjevně to funguje.","Jejich domácí politika se přeskupí kolem toho, že nechtějí být anektováni. Strana, která byla čtrnáct bodů pozadu, vyhraje jasně, kampaň staví skoro výhradně na vás."],["Přestat. Oslovovat ho premiérem a myslet to vážně.","Bojkot postupně slábne asi dva roky. Nikdy úplně neskončí, protože nákupní zvyk přežije clo o pořádnou míli."],["Eskalovat na cla. Udělat z toho vtipu nákladnou záležitost.","Dvě propojené ekonomiky se rozpojí o čtyři procenta za rok. Čtyři pohraniční města na vaší vlastní straně ztratí svého největšího zaměstnavatele."],["Formálně je pozvat, ať zažádají o členství ve federaci.","Skutečná přihláška je doručena kurýrem na jejich ambasádu, vyplněná do posledního políčka jako vtip, a vrácena. Nikdy se nezjistilo, kdo ji vyplnil."]]},"e-currency":{"t":"Portrét na bankovce","x":"Lyle má odpověď mincovny a čte ji jako muž, který něco odzbrojuje. \"Neexistuje zákon zakazující žijící osobu na měně. Existuje sto padesát let stará praxe, interní směrnice a velmi dlouhé ticho, když jsem se zeptal proč.\"","c":[["Stovku. Udělat to.","Každá transakce v zemi teď nese vaši tvář. Čtyři země, jejichž měna to dělá, jsou jmenovány v každém článku, který se kdy napíše."],["Pamětní minci. Omezený náklad.","Vyprodá se za devět hodin a obchoduje se za čtyřnásobek nominální hodnoty. Legální, populární, a stojí to přesně jeden odstavec kritiky."],["Ani jedno. Měna na to není.","Lyle vydechne způsobem, který jste od něj nikdy neslyšel. Směrnice přežije ještě jednu administrativu, což je maximum, čeho směrnice kdy dosáhne."],["Dát svou tvář jen na jednocentovou minci.","Nejmenší nominální hodnota, ta, kterou už i tak ruší. Vyznívá to buď jako mimořádná skromnost, nebo kolosální omyl, a nikdo se neshodne, co z toho."]]},"e-arts-board":{"t":"Schůze rady","x":"Deborah má připravené dopisy. \"Rada odvolána, nová rada dosazena, a vy jako předseda. Je to v mezích vaší jmenovací pravomoci.\" Odmlčí se. \"Pane, rezignace začnou přicházet do hodiny, a u dvou z nich to budou lidé, kterých je opravdovými fanoušky vaše vlastní rodina.\"","c":[["Odeslat je všechny. Osobně předsedat první schůzi.","Čtyři významní umělci odstoupí do týdne od sezóny. Budova si udrží program tím, že najme lidi, kteří si nemohli dovolit odmítnout."],["Vyměnit radu. Předsednictví si nenechat.","Stejná kontrola, minus fotografie. Nikdo nerezignuje kvůli radě, kterou nikdy nepotkal a nedokáže jmenovat."],["Radu nechat být. Přijít místo toho na premiéru.","Sedíte čtyři hodiny na moderním tanci s viditelnou statečností. Umělecká ředitelka řekne čtyřem lidem, že to byl nejpřekvapivější večer její kariéry."],["Předsedat a sám sestavit program sezóny.","Vaše sezóna je devět poctových koncertů, kouzelník a symfonický orchestr hrající filmovou hudbu. Prodá se o 40 procent víc než minulá sezóna, fakt, o kterém nikdo zúčastněný nechce mluvit."]]},"e-rename-water":{"t":"Vodní plocha","x":"Nařízení přejmenovává vodní plochu ohraničenou třemi zeměmi. Muriel má praktickou poznámku. \"Můžeme ji přejmenovat na vlastních mapách, pane. Na cizích mapách ne, a mezinárodní hydrografický úřad rozhodne o čemkoli tak za jedenáct let.\"","c":[["Podepsat to. Naše mapa je jediná, na které záleží.","Dvě sousední země to odmítnou převzít. Každá letecká mapa na světě teď nese obě jména, oddělená lomítkem, trvalý pomník sporu."],["Podepsat to pro domácí použití. Netlačit to v zahraničí.","Domácí mapy se změní, zahraniční vztahy ne, a celá akce stojí 400 000 dolarů na přetisk."],["Nepodepsat to. Má jméno.","Nic se nestane, což je správný výsledek pro návrh přejmenovat moře, a nahlásí se to přesně nikde."],["Pojmenovat ji po sobě.","Čtyři kartografové to písemně odmítnou. Jeden to udělá, následně nesežene práci, a mapa se do deseti let stane sběratelským kouskem."]]},"e-wire-ban":{"t":"Redakční příručka","x":"Tisková agentura pořád používá staré jméno té vody, protože to říká její redakční příručka, a ta příručka řídí čtyři tisíce redakcí. Kaylee: \"Můžeme je vyloučit z místnosti, pane. Nemůžeme je vyloučit z příručky, a příručka je to skutečné bojiště.\"","c":[["Vyloučit je. Ze všeho. Dnes.","Žalují, vyhrají, částečně prohrají v odvolání, a příručky se nikdy nedotknou. Strávil jste jedenáct měsíců přesouváním jednoho slova uvnitř jedné budovy."],["Vyloučit je jen z malé místnosti. Velké akce zachovat.","Dost na to, aby to udělalo dojem, ne dost na to, aby to založilo žalobu. Jejich právníci žalobu o zasedací pořádek nedoporučí."],["Nechat to být. Je to redakční příručka.","Staré jméno zůstane standardem všude na světě. Vždycky by tomu tak bylo, a vy jste právě ušetřil soudní řízení a rok života."],["Vydat federální redakční příručku a nařídit ji.","Čtyři sta stran, vydaných všem úřadům, jedenáct pravidel o vašem jméně a jedno o oxfordské čárce, což je jediné pravidlo, které vyvolá vzpouru."]]},"e-complicated":{"t":"\"Nikdo to nevěděl\"","x":"Řekl jste na kameru, že nikdo nevěděl, že zdravotnictví může být tak komplikované. Dr. Pike drží hromadu papíru. \"Pane, tohle je žádost o výjimku jednoho jediného státu. Má jedenáct set stran. Všichni to věděli. V určitém smyslu je to jediná věc, kterou kdokoli poslední třicet let vůbec ví.\"","c":[["Trvat na tom. Nikdo mi neřekl, že je to tak zlé.","Prezident veřejně přizná, že nevěděl, že centrální otázka domácí politiky jeho kariéry je komplikovaná. Obě strany to citují navždy, z opačných důvodů."],["\"Myslel jsem, že mi to nikdo poctivě nevysvětlil.\" Obrat.","Záchrana, která je zároveň obratná i přibližně pravdivá. Pike, který to vysvětluje poctivě dvacet let, tentokrát výjimečně mlčí."],["Sednout si s Pikem na čtyři hodiny a fakt se to naučit.","Vyjdete z toho schopen bez poznámek vysvětlit rizikové skupiny pojištěnců. Je to nejužitečnější odpoledne vašeho prezidentství, a nikdo o tom nikdy nenapíše."],["Prohlásit zdravotnictví za jednoduché výnosem.","Výnos má šedesát jedna stránek definic ustanovujících, co jednoduchost znamená. Ironii zaznamená úplně každý, kdo to čte."]]},"e-light":{"t":"Ta druhá věc na brífinku","x":"Nešlo jen o tu první poznámku. Na stejném brífinku jste se ptal, jestli by se do těla nedalo přivést velmi silné světlo. Dr. Pike je tu s jednostránkovou poznámkou. \"Pane, čtyři nemocnice přijaly hovory. Ne mnoho. Ale čtyři.\"","c":[["Říct, že jste to myslel sarkasticky.","Přepis nezní jako sarkasmus, ani video ne. Tvrzení se stane vlastním, menším, déle trvajícím příběhem než ta poznámka sama."],["Nechat Pika vydat jasný pokyn. Sám neříkat nic.","Jednostránková klinická poznámka dorazí na každé pohotovostní oddělení v zemi do šesti hodin. Hovory ustanou."],["Přestat s brífinky.","Brífinky vám byly hodné čtyř bodů týdně a stály zhruba stejně. Ukončit je je remíza, kterou nikdo na žádné straně vlastně nechtěl."],["Nechat světelný nápad pořádně prozkoumat.","Skutečná rešerše se vrátí s popisem čtyř skutečných nitrožilních světelných terapií a zdvořile uzavře, že tohle žádná z nich nebyla."]]},"e-testing":{"t":"Zpomalit testování","x":"Řekl jste, že když se testuje v takovém rozsahu, najde se víc případů, a proto jste požádal, ať se testování zpomalí. Dr. Pike úplně ztuhne. \"Pane, byl to vtip? Mám čtyři ředitele zdravotnictví ze států, kteří se mě ptají, a já upřímně nevím, co jim mám říct.\"","c":[["Nebyl to vtip. Testování zpomalit.","Testování se ve skutečnosti nezpomalí, protože ho provádí státy a nemocnice, ne vy. Ta věta přežije danou politiku o dobrou dekádu."],["\"Byl jsem sarkastický.\" Nechat to tak.","Čtyři z vašich vlastních úředníků do dne veřejně řeknou, že jste nebyl, protože pokyn už dostali a jednali podle něj."],["Testování zdvojnásobit a čísla hlásit denně.","Počet případů prudce stoupne, protože je teď skutečně nacházíte. Pike tomu říká nejodvážnější politické rozhodnutí, jaké kdy viděl, a stojí vás to devět bodů."],["Testovat jen lidi, u kterých je pravděpodobný negativní výsledek.","Někdo to v dobré víře sepíše a rozešle jako návrh protokolu, než ho odchytí. Návrh přežije v archivu dodnes."]]},"e-send-her-back":{"t":"Skandování","x":"Dav začal skandovat o sedící kongresmance a je to tři slova dlouhé. Přestal jste mluvit. Deborah do sluchátka: \"Zatím třináct vteřin, pane. Cokoli uděláte v příštích pěti, je to, co se bude přehrávat.\"","c":[["Počkat. Nechat to doznít. Pak pokračovat.","Třináct vteřin ticha, vysílaných živě. Čtyři vaši vlastní členové se od toho jmenovitě distancují a vy strávíte týden vysvětlováním jedné pauzy."],["Přerušit to. \"Tohle u nás neděláme.\"","Dav okamžitě přestane, což dokazuje, že by přestal okamžitě kdykoli během předchozích třinácti vteřin, kdybyste ho o to požádal."],["Mluvit skrz to. Změnit téma uprostřed věty.","Žádná konfrontace, žádné schválení. Je to zbabělá volba a s velkým odstupem ta nejúčinnější na stole."],["Zahájit jiné skandování. Okamžitě. Jakékoli.","Začnete skandovat o infrastruktuře. Dav se přidá, zmatený, ale loajální, a třicet tisíc lidí stráví devadesát vteřin křikem o mostech."]]},"e-stand-by":{"t":"Odpověď z debaty","x":"Vyzván, ať je odsoudíte, jste jim řekl, ať ustoupí a jsou připraveni. Kaylee má dopad. \"Vytiskli si to na merchandise, pane. Do hodiny. Berou to jako pokyn, a upřímně, gramaticky je to pokyn.\"","c":[["Odmítnout to upřesnit. Nechat je, ať si to vykládají, jak chtějí.","Ozbrojená skupina teď věří, že má od prezidenta pohotovostní rozkazy. Na tomhle uspořádání se během následujících měsíců nic nezlepší."],["Odsoudit je jmenovitě příští ráno.","Jmenovitě, bez vyzvání, jednou větou. Merchandise se přestane prodávat a čtyři organizátoři veřejně řeknou, že se cítí opuštěni, což byl ten záměr."],["Odsoudit \"veškerý extremismus\", aniž byste kohokoli jmenoval.","Odsouzení, které nikoho nejmenuje, slyší všichni jako odsouzení nikoho, což je přesně a doslova to, čím je."],["Nařídit jim, ať ustoupí *dopředu*, aby otestovali tu teorii.","Vysvětlení je v každém měřitelném ohledu horší než originál. Čtyři sta lidí to do dne vezme naprosto doslova."]]},"e-hostages":{"t":"Slovo pro ně","x":"Začal jste odsouzené výtržníky nazývat rukojmími. Sy: \"Pane, čtyři se přiznali. U soudu. S obhájcem. Přiznání viny je věc, kterou rukojmí fyzicky nemůže učinit, a přepisy jsou veřejné dokumenty.\"","c":[["Pokračovat v tom. Pouštět jejich telefonáty na shromážděních.","Nahrávka odsouzených vězňů zpívajících hraje předtím, než vejdete na pódium, čtyřicetkrát, a nikdy nepřestane být mimořádná."],["Místo toho tvrdit, že tresty byly nepřiměřené.","Argument o výši trestu je aspoň argument. Čtyři z těch trestů opravdu byly dlouhé, a kdybyste řekl jen tohle, ten bod byste si skutečně vybojoval."],["Přestat to slovo používat.","Vaše hnutí si toho do dne všimne a bere to jako první krok zrady, což v jejich pojetí víceméně je."],["Nabídnout jejich výměnu za skutečné rukojmí.","Návrh se odešle na ministerstvo zahraničí, které to vůbec nečekalo. Jejich odpověď upřímně žádá o vyjasnění podmínek."]]},"e-acting":{"t":"Pověřený","x":"Deborah má organizační schéma a většina jména je kurzívou. \"Jedenáct vedoucích úřadů je pověřených. Čtyři jsou pověřeni už přes rok. Pověřený úředník slouží zcela podle vaší libosti a dá se vyměnit do oběda, proto ho máte rád, a proto je zákonná lhůta už dávno překročená.\"","c":[["Nechat je všechny pověřenými. Natrvalo.","Vláda lidí, kteří se dají okamžitě odvolat. Všechno funguje trochu hůř a nic se nikdy neodmítne, což byla vždycky ta výměna."],["Nominovat ty čtyři, které by potvrdili.","Čtyři potvrzení ministři s nezávislým postavením, každý vám za rok jednou řekne ne. Všechny čtyřikrát jste se mýlil."],["Nominovat všechny. Přijmout ztráty.","Sedm potvrzeno, čtyři odmítnuti. Odmítnutí bolí a potvrzení jsou trvalá, a trvalost je ta věc, kterou jste si dosud jen půjčoval."],["Jmenovat jednu osobu pověřenou pro všech jedenáct rolí.","Je to na chvíli zákonné. Zastává jedenáct ministerstev devět dní a pak o tom napíše knihu, se kterou se hodně těžko polemizuje."]]},"e-loyalty-lunch":{"t":"Oběd","x":"Je večeře a jste tam sami dva. Ředitelka Quistová si už všimla dvou prostřených míst v místnosti pro čtyřicet. Chystáte se použít slovo, které vám Bo dvakrát, písemně, zakázal používat.","c":[["\"Potřebuju loajalitu. Očekávám loajalitu.\"","Místo toho vám nabídne upřímnost. Ta výměna se do hodiny sepíše, s datem, na parkovišti, a do roka se přečte nahlas výboru."],["Požádat o nezávislost, a myslet to vážně.","Řekne to veřejně o měsíc později, nevyžádaně, pod přísahou. Je to nejcennější věta, kterou o vás kdo za celé funkční období pronese."],["Mluvit o jídle. Neptat se na nic.","Devadesát minut o vínu. Odejde zmatená a nesepíše nic, což je jediný výsledek, který vám tady vlastně pomůže."],["Požádat ji, ať podá loajalitu.","Vtip, špatně podaný, přesně v okamžiku, kdy usoudila, že ten večer je neškodný. Zapíše si ho přesto, doslovně, s otazníkem."]]},"e-witch-hunt":{"t":"Ta fráze","x":"Kaylee zase počítala. \"Čtyři sta jedenáct použití stejných dvou slov za osmnáct měsíců. Teď je s vámi spojenější než se sedmnáctým stoletím.\" Zaváhá. \"Pane, vyšetřování se za chvíli zveřejní, a ta fráze bude to, co budou lidé mít místo zprávy.\"","c":[["Říct to ještě čtyři sta krát.","Funguje to naprosto. Zpráva vyjde a 61 procent země už ji má zaškatulkovanou pod frází, kterou slyšeli dřív, než slyšeli cokoli jiného."],["Přestat to říkat. Napadnout raději zjištění.","Hádat se s dokumentem je těžší, než dokument odmítnout, a podstatně účinnější u těch čtyř procent, co vlastně rozhodují volby."],["Plně spolupracovat a neříkat vůbec nic.","Vyjde včas, najde míň, než chtěla obě strany, a nepřečte si to nikdo, standardní osud jakéhokoli dokumentu, o kterém nikomu neřekli, ať se o něj zajímá."],["Nechat si tu frázi zaregistrovat jako ochrannou známku.","Přihláška se podá vážně a zamítne se s odůvodněním, že termín je běžně užívaný, hlavně díky vám."]]},"e-hotel-booking":{"t":"Rezervace delegace","x":"Miriam má rezervace. \"Čtyři zahraniční delegace, všechny ve vašem hotelu, všechny čtrnáct dní před svými obchodními jednáními.\" Odkládá je. \"Nikdo je o to nepožádal. To je ta část, kterou pořád nedokážu jasně vysvětlit: nikdo se nemusel ptát.\"","c":[["Vzít ty rezervace. Je to hotel.","Platba od cizího státu prezidentovi, za zveřejněnou cenu, za skutečný pokoj. Je to nejčistší možná verze nejstaršího možného problému."],["Vzít je. Zisk poslat do státní pokladny.","Dobrovolný, neověřitelný odhad možného zisku, zveřejňovaný ročně, odstraní 90 procent kritiky za zlomek nákladů."],["Nařídit hotelu odmítat rezervace zahraničních států.","Pokyn se sepíše a dodrží. Stojí to zhruba 12 milionů dolarů ročně a je to jediná položka na tomhle seznamu, která opravdu něco řeší."],["Naúčtovat jim čtyřnásobek a nazvat to clem.","Dvě delegace to bez námitek zaplatí, což je nejalarmnější dostupný výsledek a všimnou si ho čtyři zpravodajské služby."]]},"e-jet":{"t":"Letadlo","x":"Cizí vláda nabídla letadlo. Tarrant má bezpečnostní posouzení a pečlivě volí slova. \"Zbavit ho vnitřního vybavení a přestavět na náš standard trvá čtyři roky a stojí víc, než koupit nové rovnou. A pane, formulace je sporná. Oni tvrdí, že bylo nabídnuto. Někdo z naší strany se zeptal první.\"","c":[["Přijmout to. Nazvat to nevyžádaným darem.","Záznam o tom, kdo koho oslovil jako první, vyjde na povrch do čtrnácti dnů, protože vždycky vyjde, a slovo \"nevyžádaný\" se místo letadla stane příběhem."],["Přijmout ho pro letectvo. Ne osobně.","Dar státu státu, řádně převedený, nakonec do muzea. Je to nudná odpověď, a přežije každý výbor, který se jí dotkne."],["Odmítnout ho. Koupit vlastní.","Stojí to čtyři miliardy dolarů, trvá to šest let, a nezbývá o tom naprosto nic napsat. Tarrant tomu říká dobře utracené peníze."],["Přijmout ho a odletět s ním do muzea osobně.","Nemáte kvalifikaci na ten typ letadla. Sednete si na levé sedadlo, na zemi, na fotku, a popisek napíše někdo, kdo si to napřed ověřil."]]},"e-poll-numbers":{"t":"Data z průzkumů","x":"Nadia má skutečná čísla a ta, která jste citoval. Liší se o devatenáct bodů. \"Ten, co používáte, je online dobrovolný průzkum mezi vašimi vlastními podporovateli, pane. Vím, kdo ho zadal, protože mě požádali, ať ho navrhnu, a já jsem odmítla.\"","c":[["Citovat dál ten dobrý. Existuje.","Skutečně existuje, což ho dělá spíš nevyvratitelným než pravdivým, a nevyvratitelnost se na volném trhu, jak se ukazuje, cení podstatně víc."],["Citovat ten skutečný. Říct, že máte práci.","Upřímnost k číslu je vám za čtvrtletí čtyři body vydatnější, než kdy dodalo falešné číslo."],["Přestat vůbec citovat čísla.","Nadia tomu říká nejzdravější rozhodnutí funkčního období. Vydrží jedenáct dní."],["Objednat průzkum, jestli jsou průzkumy vůbec přesné.","Šedesát jedna procent řekne ne, což citujete jako důkaz, že průzkumy ukazující vaši prohru jsou chybné, použití zjištění, se kterým Nadia opravdu nepočítala."]]},"e-rally-length":{"t":"Devadesátá minuta","x":"Jste devadesát čtyři minuty do čtyřicetiminutového slotu. Boyd Hackler v zákulisí dělá gesto, o kterém jste se rozhodl, že znamená \"pokračujte\". Aréna se musí uvolnit pro hokejový zápas a venku v mrazu stojí čtyři tisíce lidí s lístky na něj.","c":[["Ještě čtyřicet minut. Přišli si pro tohle.","Hokejový zápas začne o devadesát minut později. Jeho fanoušci, dotázaní cestou dovnitř, mají na to velmi jasný názor."],["Zabalit to do pěti minut. Silný závěr.","Sevřený, úderný konec, který v televizi zabírá líp než předchozích devadesát čtyři minut. Boyd si čas poznamená a nikdo si toho nevšimne."],["Skončit teď a zůstat podávat ruce místo toho.","Dvě hodiny podávání rukou čtyřem tisícům lidí, cennější než ten projev, a žádná kamera kvůli tomu nezůstane."],["Zůstat na pódiu a sledovat hokej.","Sledujete tři třetiny ze skládací židle u mantinelu. Je to nejoblíbenější věc, co za rok uděláte, a to o míle."]]},"e-golf-count":{"t":"Účetní kniha odpolední","x":"Někdo vede webovou stránku počítající vaše odpoledne na vlastních hřištích. Kaylee má číslo. \"Dvě stě osmdesát jedna dní, pane, a stránku teď citují jako zdroj i tiskové agentury, což znamená, že povýšila z koníčku na fakt.\"","c":[["Jít víc. Oznamovat každé.","Přiznat to odstraní úder a nahradí ho číslem, které veřejně jen dál roste, což se ukáže jako podstatně horší."],["Chodit dál, ale přestat účtovat vládě detaily.","Náklad byl vždycky ten skutečný příběh. Odstraňte ho, a zbyde muž hrající golf, což není příběh nikde na světě."],["Omezit to. Na čtvrtletí pracovat i o víkendech.","Tři měsíce viditelné práce vám přinesou čtyři body podpory navíc a učiní vás na celé čtvrtletí nesnesitelným."],["Konat schůze kabinetu na hřišti.","Jedenáct ministrů ve flotile golfových vozíků, zapisujících poznámky. Přijmou se dvě opravdu užitečná rozhodnutí a poznámky se nikdy nenajdou."]]},"e-enemy-phrase":{"t":"Nepřátelé lidu","x":"Dr. Weirová si vyžádala pět minut kvůli jedné frázi. \"Pane prezidente, nejsem tu, abych vám řekla, ať neútočíte na tisk. Jsem tu, abych vám řekla, odkud přesně ta konkrétní formulace pochází, protože myslím, že to nikdo neudělal, a nepochází to odnikud, odkud byste chtěl.\"","c":[["Nechat si to. Zabírá to a vím, odkud to pochází.","Čtyři historici napíšou nezávisle na sobě stejný sloupek. Její pointa nikdy nebyla, že to selže; bylo to, že to zabere, a řekne vám to cestou ven ze dveří."],["Přejít na \"fake news\". Stejný boj, žádná genealogie.","Identický efekt, žádná poznámka pod čarou, žádní historici. Je to nejúčinnější úprava, kterou za čtyři roky ve svém slovníku uděláte."],["Frázi i celý ten boj opustit.","Pokrytí se nezlepší. Nikdy by se nezlepšilo. Ten boj byl vždycky ta věc, co skutečně fungovala, a vy jste v ní právě přestal."],["Zeptat se jí, které režimy to používaly, a dělat si poznámky.","Odpoví podrobně, s daty, dvacet minut. Popíšete čtyři stránky poznámek. Ona stráví zbytek života přemýšlením, k čemu to bylo."]]},"e-vermin":{"t":"Návrh s tím zvířecím slovem","x":"Gideon Poe označil podstatné jméno v zítřejším projevu. \"Je to slovo pro zvíře, použité na občany, ve větě o životě mezi námi.\" Nezvedá oči. \"Pane, já to nenapsal. Snažím se zjistit, kdo to napsal, a nedaří se mi to, což je samo o sobě odpověď.\"","c":[["Nechat to. Přednést to přesně, jak je napsáno.","Historici zareagují do hodiny, ve velkém počtu, citují tři stejné režimy. Je to nejcitovanější věta vašeho prezidentství, a nikdy ne pochvalně."],["Vyměnit to podstatné jméno. Nechat větu.","Stejná reakce sálu, žádné archivní záběry, žádné sloupky. Gideon tomu říká nejlevnější úprava, jakou kdy udělal, a myslí to naprosto vážně."],["Vyškrtnout celý ten úsek.","Projev je o čtyři minuty kratší a podstatně lepší. Nikdo si nevšimne absence, ta trvalá, nevděčná tragédie dobré redakce."],["Přednést to, ale o vlastní straně.","Sál neví, co s tím. Dva lidé zatleskají. Je to nejopravdověji znepokojivých devadesát vteřin celého funkčního období."]]},"e-tylenol":{"t":"Rada z pódia","x":"Spojil jste běžný lék proti bolesti s vývojovou poruchou a navrhl rozvolnit dětské očkování. Dr. Pike přijde bez pozvání. \"Pane, čtyři velké studie tvrdí opak a mohu vám je mít na stole do hodiny. Pediatrická sdružení už píšou stanoviska.\"","c":[["Zopakovat to. Hlasitěji. Lidé to musí slyšet.","Termíny očkování klesnou za čtvrtletí o devět procent ve čtyřech státech. Číslo se zveřejní, přisoudí, a už se nikdy nevrátí zpátky."],["\"Nejsem lékař. Zeptejte se svého.\" Jít dál.","Šest slov napraví většinu škody. Pike poté řekne, že to byla správná odpověď a že od vás nečekal, že ji skutečně uslyší."],["Nechat Pika, ať vede brífink místo vás, od teď.","Nudný muž dvakrát týdně po rok čte fakta. Dvanáct měsíců v kuse se nic nezvrtne, a nikdo za to nikomu nepoděkuje."],["Vzít si lék na kameru, ať dokážete, že je v pořádku.","Vezmete si dva, naživo v televizi, poté, co jste je právě nazval nebezpečnými. Nikdo v místnosti nedokáže vymyslet doplňující otázku."]]},"e-blago":{"t":"Velmi slušný člověk","x":"Zmírnil jste trest guvernérovi odsouzenému za pokus prodat senátorské křeslo a popsal ho potom jako velmi slušného člověka. Sy: \"Porota ho odsoudila za prodej veřejného úřadu. Pane, to je ten trestný čin. To je přesně to, co udělal.\"","c":[["Zopakovat to. Zacházeli s ním nespravedlivě.","Dalších čtyři lidé žádající o milost si najme stejného právníka, jakého použil on, což je tržní signál, a přesně tak se to i nahlásí."],["Zmírnit trest potichu. O tom muži neříkat nic.","Zmírnění trestu bez přívlastku je rutinní akt milosti. Ten přívlastek byl vždycky celý ten příběh."],["Stáhnout to. Byl to špatný případ.","Udělenou milost nelze vzít zpátky. Sy to vysvětluje a vy strávíte celé čtyři minuty odmítáním tomu uvěřit."],["Jmenovat ho do něčeho.","Federální poradní rada pro veřejnou integritu. Jmenování je skutečné, oznámí se v pátek, a trvá jedenáct dní."]]},"e-antifa":{"t":"Označení","x":"Duane má návrh výnosu a jeden problém. \"Označuje organizaci. Pane, žádná organizace to není. Žádné členství, žádné vedení, žádný bankovní účet, a nic, na co by šlo doručit soudní obsílku. Úřad se písemně ptá, koho přesně mají zatýkat.\"","c":[["Podepsat to. Nechat úřad, ať vyřeší podrobnosti.","Bez organizace, kterou by šlo skutečně obžalovat, se označení začne uplatňovat na jednotlivce podle jejich názorů, což byl vždycky jediný způsob, jak to mohlo fungovat."],["Označit čtyři konkrétní skupiny, které skutečně existují.","Jmenované entity s bankovními účty a vedením, stíhatelné podle stávajícího zákona. Do dvou let následují čtyři odsouzení a ani jedno se neruší."],["Nepodepisovat to. Použít zákony, které máme.","Stávající zákony fungují dobře, protože politické násilí je nezákonné už dvě stě let a mezera v zákoně nikdy neexistovala."],["Označit sám sebe, ať otestujete standard.","Papíry se sepíšou jako demonstrace a, katastrofálně, opravdu podají. Strávíte devět dní na seznamu, než si toho někdo všimne."]]},"e-shithole-confirm":{"t":"O osm let později","x":"Před osmi lety jste popřel to slovo. Dnes ráno, nevyžádaně, v rozhovoru o něčem úplně jiném, jste ho použil znovu a potvrdil původní tvrzení. Kaylee má oba záznamy připravené a nepouští je. \"Pane, právě jste potvrdil zprávu, kterou jste celý rok nazýval smyšlenou.\"","c":[["Říct, že jste to vždycky tvrdil a měl jste pravdu.","Oba záznamy běží vedle sebe čtrnáct dní. Novináři, které jste rok nazýval lháři, jsou nakonec nezvykle velkorysí, když to celé skončí."],["Říct, že popírání se týkalo přesného znění.","Je to, technicky, přesně to, co původní popření řeklo. Obhajoba \"technicky co to řeklo\" nikdy nefungovala, a nezačne teď."],["Omluvit se novinářům jmenovitě.","Čtyři jména, nahlas, nevyžádaně. Vaše hnutí to bere jako zradu, a dva ze čtyř novinářů veřejně řeknou, že to nic nezměnilo, a přece na tom záleželo."],["Tvrdit, že jste citoval někoho jiného v místnosti.","Každý další v té místnosti je pořád naživu, a čtyři z nich se do hodiny na to zeptají. Všichni čtyři odmítnou stejnou opatrnou větou."]]},"e-invasion-word":{"t":"Podstatné jméno pro příchozí","x":"Gideon má graf četnosti. \"To slovo se objevuje v každém projevu šest týdnů, a jen v šesti týdnech před volbami. Pane, to není popis, to je harmonogram, a někdo tenhle graf zveřejní.\"","c":[["Používat ho víc. Funguje to, protože je to pravda.","Graf se zveřejní. Korelace s volebním kalendářem je přesná, což je horší než jakékoli jednotlivé použití toho slova."],["Používat ho dál i po volbách.","Konzistence úplně odstraní obvinění z cynismu a nic vás nestojí, protože to slovo dělá stejnou práci v březnu jako v říjnu."],["Zavrhnout ho. Mluvit místo toho o mzdách a bydlení.","Ekonomický argument, obhajitelný a nudný. Přesvědčí o čtyři sta tisíc lidí víc a nikoho naprosto nenadchne."],["Použít to slovo na něco jiného úplně.","Špatnou pylovou sezónu dvakrát popíšete jako invazi, s naprostým přesvědčením. Čtyři alergologické spolky vydají prohlášení, a jeden vám poděkuje."]]},"e-lee":{"t":"Generál na podstavci","x":"Nazval jste ho skvělým generálem. Dr. Weirová nezpochybňuje to vojenské hodnocení a řekne to na rovinu. \"Byl schopný velitel, pane prezidente. Byl schopný velitel armády postavené na tom, aby lidi drželi jako majetek, a socha vznikla šedesát let po jeho smrti, kvůli lidem, kteří si tím dělali poznámku o něčem, co se dělo přesně tehdy.\"","c":[["Nařídit ochranu soch. Všech.","Federální ochrana pomníků postavených jako politická prohlášení, obhajovaná jako historie. O komentář požádají čtyři historiky a všichni čtyři citují to samé datum."],["Nechat to na obcích. Dál nic neříkat.","Čtyřicet jedna obcí rozhodne čtyřicet jedna odlišnými způsoby za čtyři roky, a nic z toho se nestane celostátní zprávou."],["Chválit vojáka, podporovat odstranění.","Rozlišení, které čtyři historici pokládají za intelektuálně poctivé a vaše základna za přímou zradu, ze stejných dvou faktů."],["Nahradit je všechny sochami sebe.","Jedenáct podstavců se přestaví. Čtyři z nových soch spadnou do deseti let, stejným procesem, se stejnými argumenty, a nikomu to tehdy nepřijde vtipné."]]},"e-crowd-again":{"t":"Letecký snímek, znovu","x":"Jiná akce, jiná letecká fotografie, stejný spor. Kaylee má oba roky vedle sebe. \"Pane, tenhle boj jste vedl už počtvrté. Nikdo ho nikdy nevyhrál. Fotku pořizuje satelit a satelit nemá názor.\"","c":[["Bojovat s tím. Znovu. Nařídit opravená čísla.","Archivář z povolání je podruhé za čtyři roky přeložen, do té samé budovy bez oken, a číslo je opět oficiální."],["\"Davy jsou posedlost médií.\" Další otázka.","Příběh zemře za čtyřicet minut. Něco ve vás s ním zemře taky a Kaylee si poznamená, ať tu větu použije znovu příště."],["Zveřejnit vlastní záznam z dronu. Nechat lidi počítat.","Záběry ukazují velký, skutečný, nadšený dav, zhruba třetinu udávané velikosti. Zveřejnit ho je nejlepší dostupná verze prohry."],["Uspořádat příští shromáždění tam, kde nejde nafotit z letadla.","Hala s tvrdou kapacitou devět tisíc lidí, kterou pak oznámíte, že navštívilo osmdesát tisíc."]]},"e-cabinet-italics":{"t":"Rezignační dopis","x":"Dva členové rady odstoupili a zveřejnili své dopisy. Deborah má oba. \"Zdvořilé, konkrétní, čtyři odstavce dlouhé. Ani jeden vás jménem nezmiňuje, pane, což je přesně ta věc, díky které se rozletí do světa.\"","c":[["Osobně napadnout oba dva.","Jmenovat lidi, kteří odmítli jmenovat vás, celou tu výměnu obrátí naruby. Jejich dopisy se čtou nahlas ve čtyřech pořadech; váš v žádném."],["Přijmout rezignace bez komentáře.","Rezignace, na kterou nikdo nereaguje, je jen rezignace. Rezignace, na kterou někdo reaguje, je skandál, a vy jste se rozhodl tu druhou polovinu nedodat."],["Požádat je, ať zůstanou. Osobně. Telefonem.","Jedna zůstane. Řekne o tom hovoru čtyřem lidem, a příběh se změní na prezidenta, který zvedl telefon, což se nikdy předtím nestalo."],["Přijmout rezignace a oběma nabídnout něco lepšího.","Oba odmítnou, písemně, se zjevnými obtížemi. Jedna si dopis s nabídkou schová a zmíní ho o jedenáct let později v memoárech."]]},"e-birthday-parade":{"t":"Náhoda","x":"Boyd má problém s datem. \"Přehlídka k výročí ozbrojených sil padá na vaše narozeniny. Doopravdy, je to skutečné výročí a skutečná náhoda.\" Pohne se. \"Nikdo mimo tuhle místnost tomu neuvěří, pane. Kalendář jsem si sám ověřil čtyřikrát, protože jsem tomu taky nevěřil.\"","c":[["Uspořádat ji. Zmínit narozeniny z pódia.","Skutečná náhoda se jedinou větou promění v úmyslnou, před jedenácti tisíci sloužícími vojáky."],["Uspořádat ji. Narozeniny nikdy nezmínit.","Výročí se oslaví řádně. Čtyři média zmíní shodu dat v devátém odstavci a nikdo nikdy nečte devátý odstavec."],["Přesunout přehlídku na jiný víkend.","Přesunout dvěstěpadesátileté výročí kvůli implikaci je samo implikací, a Boyd to poznamená, správně, ale příliš pozdě."],["Přesunout vlastní narozeniny.","Proklamace určí jiné oficiální datum. Podepíše se. Čtyři úřady si opraví záznamy a jeden pak posílá přání od té doby oba dny."]]},"e-pen-set":{"t":"Pera","x":"Alvin má tác. \"Dvaadvacet per na podpis, pane, a vy jste podepsal sto čtyřicet tři příkazů.\" Provede výpočet, aniž by ho o to kdo žádal. \"Tři tisíce sto čtyřicet šest per. Ty dobré nám došly, a rezerva je zásoba z roku 1974.\"","c":[["Objednat čtyřicet tisíc dalších. Zlatých. S mým podpisem.","Dorazí za jedenáct týdnů. Podpis je na všech čtyřiceti tisících mírně mimo střed, a nikdo se to neodváží zmínit."],["Použít zásobu z roku 1974. Někdo by měl.","Pero z úplně jiného prezidentství podepíše příkaz, který by jeho původního majitele ohromil. Alvina to baví víc než kohokoli jiného."],["Jedno pero na podpis. Nechat si je všechna.","Kompletní sada, v pořadí, v pouzdru, se stane nejcennějším předmětem, jaký kdy z téhle budovy kdo odnese."],["Podepisovat vším navždy stejným perem.","Dojde mu inkoust u příkazu číslo devadesát jedna, uprostřed podpisu, před kamerami. Příkaz zůstane technicky nedokončený čtyři hodiny, než si toho někdo všimne."]]},"g-registry-quota":{"t":"Strop na jednu zemi","x":"Třetí verze omezení vstupu prošla přezkumem, protože je formulovaná kolem prověřování, nikoli národnosti. Muriel: „Je to identický seznam, pane. Přežil jen proto, že třetí návrh přidal odstavec o procesu.“","c":[["Rozšiřte ho, teď když rámec funguje.","Z devíti zemí je najednou čtrnáct. Odstavec o prověřování se pokaždé kopíruje slovo od slova a nikdy se doopravdy nezhodnotí, zda má vůbec smysl."],["Nechte to na devíti. Rámec nezkoušejte.","Zdrženlivost zrozená z čistě právní opatrnosti. Vydrží to čtyři roky, prostě proto, že nikdo soudu nedal důvod podívat se na to znovu."],["Nahraďte to skutečným prověřováním jednotlivých žadatelů.","Stojí to čtyři sta milionů dolarů, rozjezd trvá jedenáct měsíců a odmítá to víc lidí, než kdy dokázal seznam, a to na základě důvodů, které obstojí u každého soudního přezkumu."],["Přidejte zemi, která nemá vládu.","Nezůstal tam nikdo, kdo by mohl podat protest, což si čtyři úředníci pochvalně poznamenají, dokud se jeden z nich nezeptá, co bude s žadateli, kteří jsou už uprostřed letu."]]},"g-health-story":{"t":"Ten příběh o vašem zdraví","x":"Nějaké noviny otiskly článek o vašem zdraví, se zdroji od čtyř lidí přímo z budovy. Kaylee: „Není to špatně, pane. A přesně proto to nemůžu nechat opravit.“","c":[["Zaútočte na noviny. Nazvěte je nepřítelem lidu.","Příběhem se teď stává ten útok, ne vaše zdraví. Ta výměna funguje, ale funguje jen proto, že tím zároveň potvrdíte, že tam bylo co skrývat."],["Zveřejněte skutečné záznamy. Všechny.","Ukáže se, že jsou naprosto nezajímavé, dokonce trochu nudné. Jejich zveřejnění ukončí čtyři roky spekulací během jednoho odpoledne a Prine konečně dostane pokoj."],["Najděte ty čtyři zdroje. To je ten skutečný problém.","Dva se podaří odhalit a odstranit. Zbylí dva s vámi prostě přestanou mluvit a začnou si všechno zapisovat, což je mnohem horší."],["Vyzvěte šéfredaktora na fyzický souboj.","Je mu šedesát tři a okamžitě přijímá, s viditelným nadšením. K souboji nakonec nikdy nedojde. Oba pak roky tvrdíte, že to zrušil ten druhý."]]},"g-pool-slot":{"t":"Trvalé místo","x":"„Tiskové agentury mají trvalé místo v tiskovém poolu od osmdesátých let devatenáctého století. Ne ze zákona, ale ze zvyku.“ Kaylee zavírá složku. „Pool řídíme my, pane. Mohli bychom prostě přestat nějaký mít.“","c":[["Zrušte trvalé místo. Pool si vybereme sami.","Sto čtyřicet let zvyklosti skončí jedním e-mailem. Náhradníci jsou přívětivější, otázky měkčí a žádný zákon nebyl porušen, protože žádný zákon nikdy neexistoval."],["Přidejte k agenturám přátelská média.","Ředění místo odstranění. Agentury si podrží místo, ale ztratí monopol na první otázku, což bylo od začátku to jediné, na čem záleželo."],["Nechte to být. Ten zvyk přežije každého prezidenta.","Kaylee jedenáct minut v kuse argumentuje proti vlastnímu doporučení a je viditelně, slyšitelně ulevená, že prohrává."],["Dejte trvalé místo studentským novinám ze střední školy.","Sedmnáctiletá dívka z Daytonu ve čtvrtém týdnu na place položí jednoznačně nejlepší otázku roku a čtyři televizní stanice s ní otevírají zpravodajství."]]},"g-summit-praise":{"t":"Společné prohlášení","x":"Stojíte na pódiu vedle hlavy státu, kterou vaše vlastní tajné služby obvinily z vměšování, a v přímém přenosu se vás ptají, čí verzi věříte. Hance to sleduje ze vzdálenosti necelých dvou metrů.","c":[["Řekněte, že nevidíte důvod, proč by to měli být oni.","Členové vaší vlastní strany vydávají prohlášení dřív, než stačíte sejít z pódia. Celý následující den vysvětlujete, že jste tam měl vlastně říct slovo „ne“."],["Postavte se za vlastní služby. Rovnou. Na pódiu.","Devět slov, pronesených přímo vedle něj, bez jediné výhrady. Hance nijak nereaguje, což je u Hance ekvivalent standing ovace."],["Odmítněte otázku. Mluvte o obchodní dohodě.","Odbočka tak zjevná, že si jí všimne každý, ale nikdo z ní nemůže přímo citovat. Je to správná odpověď a neuspokojí naprosto nikoho."],["Řekněte, že věříte oběma verzím zároveň.","V jedné jediné větě záměrně zastáváte dvě naprosto protichůdná stanoviska a vyzýváte kohokoli, ať si jedno vybere. Čtyři redakce otisknou celý citát, protože shrnout ho prostě nejde."]]},"g-tariff-autos":{"t":"Pětadvacet procent","x":"Čtvrtinové clo na dovážená vozidla a díly. Lyle: „Čtyřicet procent auta vyrobeného v téhle zemi tvoří dovážené díly. My to prezentujeme jako obranu domácí výroby, přitom je to daň na domácí výrobu.“","c":[["Zaveďte ho. Všechna vozidla, všechny díly.","Náklady na domácí montáž vzrostou o jedenáct set dolarů na kus. Čtyři továrny odloží rozšíření. Oznámení je přitom nesmírně populární přesně v těch městech, kde ty továrny stojí."],["Jen vozidla. Díly vyjměte.","Verze, kterou by skutečně sepsal ekonom. Chrání montáž, šetří dodavatelský řetězec a je tak z třetiny stejně uspokojivá při hlasitém oznámení."],["Osmnáct měsíců jím hrozte. Nikdy ho nezavádějte.","Vymůžete si čtyři ústupky od tří vlád za clo, které nikdy fakticky neexistovalo. Je to ta nejvýnosnější věc, kterou nikdy neuděláte."],["Zdaňte jen auta jedné konkrétní barvy.","Celní úřad musí formálně rozhodovat o odstínech barvy. Čtyři dovozci přestříkají auta přímo v přístavu během pár dní a výsledný celní sazebník má devadesát stran názvů barev."]]},"g-six-cities":{"t":"Šest měst","x":"Šest měst, šest guvernérů, čtyři z nich odmítli souhlas. Tarrant: „Šest zvládnu, pane. Těch šest není problém. Problém je sedmé. Vždycky existuje nějaké sedmé.“","c":[["Všech šest. Najednou.","Logisticky to funguje, ve všem ostatním to selhává. Do čtvrtého měsíce stojí nasazení tři sta třicet dva milionů dolarů a je souběžně žalováno u pěti odvolacích obvodů."],["Dvě města. Ta, co o to sama požádala.","Nasazení se souhlasem se ukáže jako nekontroverzní, účinné a v celostátním zpravodajství naprosto neviditelné."],["Žádné. Místo toho profinancujte místní policii.","Miliarda dvě stě milionů dolarů do rozpočtů městské policie. Kriminalita ve čtyřech ze šesti měst za dva roky klesá a všichni zúčastnění starostové si připisují plnou zásluhu."],["Nasaďte jednotky do sedmého města, o kterém nikdo nemluvil.","Město s devíti tisíci obyvateli, kde nejsou žádné nepokoje. Jeho starosta svolá tiskovku, aby se upřímně zeptal, co přesně se to jeho městu děje."]]},"g-stand-down":{"t":"Tichý ústup","x":"Čtyři soudy rozhodly proti vám a pátý je na řadě. Duane připravil prohlášení o stažení jednotek, které popisuje nasazení jako splnění všech cílů. „Pane, tu větu nikdo neuvěří. Ale taky ji nikdo nebude žalovat.“","c":[["Stáhněte se. Vyhlaste naprostý úspěch.","Všechno skončí v úterý, dvouodstavcovým prohlášením. Je to nejlevnější varianta ústupu na stole a byla k dispozici od samého začátku, což je to nepříjemné na celé věci."],["Stáhněte se a poviňte konkrétní soudy jmenovitě.","Ustupujete a útočíte zároveň, což udrží základnu spokojenou, ale páté rozhodnutí, až přijde, dopadne mnohem tvrději, než muselo."],["Eskalujte to až k pátému případu. Ani nemrkněte.","Prohrajete sedm ku dvěma, s většinovým stanoviskem, které se bude citovat třicet let, a doktrínou, která nakonec ponese jméno přesně tohohle případu."],["Stáhněte se a přeřaďte vojáky ke správě národních parků.","Čtyři tisíce vojáků stráví léto opravou turistických stezek. Je to zdaleka nejoblíbenější věc, kterou celé nasazení kdy přineslo, a někdo vážně navrhne, aby to zůstalo natrvalo."]]},"g-competitive":{"t":"Odborný termín","x":"Tři politologové zabývající se komparativní politologií publikovali text, podle nějž země překročila jistou hranici. Dr. Weirová: „Ten termín zní kompetitivní autoritářství, pane. Je to odborný pojem. Má svůj kontrolní seznam. My splňujeme většinu bodů.“","c":[["Přijměte ten termín. Noste ho jako odznak. Prodávejte na něj klobouky.","Proměna diagnózy v merchandising ji zneškodní pro vaše příznivce a zároveň potvrdí pro všechny ostatní, výměna, kterou uděláte bez sebemenšího zaváhání."],["Nechte ty akademiky pozvat dovnitř. Diskutujte s nimi.","Devadesát minut, na záznam, proti třem akademikům, kteří přečetli víc historie než všichni v budově dohromady. Viditelně prohrajete a nějakým způsobem to vypadá lépe, než kdybyste vyhrál."],["Ignorujte to. Akademici se už spletli i dřív.","To se stalo. Tentokrát se ale nemýlí, kontrolní seznam je teď veřejný a srovnání si může udělat úplně kdokoli."],["Zeptejte se, které body kontrolního seznamu vám ještě chybí.","Ptáte se upřímně. Zbývají čtyři body. Deborah vás sleduje, jak si je zapisujete, a týden pořádně nespí."]]},"g-anticipatory-two":{"t":"Univerzita","x":"Druhá univerzita se sklonila, ještě než bylo skutečně zmrazeno jakékoli financování, ještě než byl odeslán jediný dopis. Ollis: „Přečetli si, co se stalo té první, a spočítali si to. Nikdo z týhle budovy s nimi vůbec nemluvil.“","c":[["Zveřejněte to. Ať je ten výpočet jasný i všem ostatním.","Devět dalších institucí se do roka srovná do latě, aniž byste je jedinkrát oslovil. Je to ta nejlevnější moc, jaká existuje, a nemusíte pro ni hnout ani prstem."],["Neříkejte nic. Ať to dál probíhá potichu.","Neviditelná poslušnost má větší cenu než ta viditelná, protože na ni nemá nikdo co namířit kameru."],["Řekněte jim veřejně, že to nebylo nutné.","Jedna ze dvou škol se do dvou týdnů vrátí zpátky. Druhá ne, a její rektor soukromě přizná, že se už neodváží zkusit se vrátit."],["Pošlete jim dodatečně dopis s požadavky.","Formální požadavek na ústupky, které už udělaly. Dopis je podán, zodpovězen a splněn podruhé, a nikdo ze zúčastněných neumí vysvětlit proč."]]},"g-officers-pardon":{"t":"Dva policisté","x":"Dva policisté odsouzení za honičku, při které zemřel muž. Bo má záznam z procesu. „Odsouzení je právně v pořádku, pane. Tresty jsou možná přehnaně tvrdé. To jsou ale dvě různé věci a jen jedna z nich znamená milost.“","c":[["Plná milost. Oběma. Oznamte to na policejní akci.","Rodina se to dozví z vysílání, stejně jako všichni ostatní. Čtyři policejní odbory vás do měsíce podpoří, město, kterému ti policisté sloužili, ne."],["Zmírněte tresty. Odsouzení nechte platit.","Užší krok, ten, který skutečně řeší podstatu věci. Získáte polovinu uznání za desetinu hněvu."],["Nic. Slyšela to porota, ne vy.","Správná odpověď, která vás stojí čtyři procentní body u voličů, kteří ještě žádnému prezidentovi neodpustili použití téhle konkrétní pravomoci."],["Udělte jim milost a jmenujte je do revizní komise.","Dva muži omilostnění za způsobení smrti teď sedí přímo v komisi, která smrtelné případy posuzuje. Jmenování je legální, ironie zůstává bez povšimnutí a čtyři členové okamžitě rezignují."]]},"g-vacancies-act":{"t":"Všechno jen pověřeně","x":"„Jedenáct vysokých pozic, všechny obsazené pověřenými úředníky. Zákon stanovuje strop, jak dlouho to smí trvat.“ Sy pokrčí rameny. „Následkem překročení stropu je, že jejich rozhodnutí jsou neplatná. Nikdo se ale nikdy neodvážil žádat soud, aby zneplatnil čtyři roky činnosti úřadu.“","c":[["Řiďte celou vládu pomocí pověřených úředníků.","Náprava, kterou se nikdo neodváží použít, fakticky žádnou nápravou není. Jedenáct úřadů čtyři roky řídí lidé, které Senát nikdy neviděl, a argument o neplatnosti se nikdy neprověří."],["Nechte potvrdit ty čtyři, na kterých záleží. Zbytek nechte pověřeně.","Potvrzená čtyřka vám dá legitimitu, pověřená sedmička rychlost. Je to verze, která přežije skutečné slyšení."],["Navrhněte kandidáty na všech jedenáct pozic. Přijměte boje o potvrzení.","Trvá to čtrnáct měsíců a dva boje prohrajete. Devět kandidátů, kteří to zvládnou, pak už váš nástupce nemůže odvolat jedním telefonátem."],["Jmenujte jednu osobu na všech jedenáct pozic.","Je mimořádně schopná a čtyři měsíce pracuje devatenáct hodin denně, než vám dopisem oznámí, že tohle prostě nikdy nemohlo fungovat."]]},"g-inspector-report":{"t":"Zpráva, kterou nikdo nečte","x":"Soudce rozhodl, že odvolání byla nezákonná, ale odmítl kohokoli vrátit do funkce s odůvodněním, že byste to stejně provedl znovu, jen s řádným oznámením. Miriam: „Bylo shledáno, že jste porušil zákon, pane, a přesto si výsledek podržíte.“","c":[["Citujte rozhodnutí jako své ospravedlnění.","Rozhodnutí proti vám, které nic doopravdy nemění, což je dost blízko výhře na to, aby to nahlas prohlásit fungovalo asi u čtyřiceti procent země."],["Splňte to zpětně. Dejte řádné oznámení. Propusťte je znovu.","Třicet dní papírování přinese naprosto stejný výsledek, tentokrát zcela legálně. Proces nikdy nebyl tou překážkou a teď je to oficiálně zdokumentováno."],["Vraťte je zpátky a nechte je dokončit funkční období.","Jedenáct ze sedmnácti se vrátí. Čtyři z jejich následných zpráv vám mimořádně uškodí, dvě vás ale zachrání před něčím podstatně horším."],["Odvolejte se proti rozhodnutí, které jste už vyhrál.","Vaši vlastní právníci stráví devět týdnů vysvětlováním, že se už nemáte proti čemu odvolávat. Přesto jim to nařídíte a odvolání je za čtyři dny zamítnuto jako bezpředmětné."]]},"g-schedule-numbers":{"t":"Dva miliony jmen","x":"„Nabídka šla na každého federálního zaměstnance. Dva miliony tři sta tisíc lidí. Rezignujte hned, plat vám poteče až do září.“ Deborah má čísla přijetí. „Přijalo to sedmasedmdesát tisíc lidí, pane. A jsou to přesně ti, které jsme si nejméně mohli dovolit ztratit.“","c":[["Zopakujte to. Ve větším. Přidejte ještě něco navrch.","Odejde dalších šedesát tisíc. Lidé, kteří mají kam jít, odcházejí vždy jako první, což znamená, že každé kolo dělá zbývající pracovní sílu menší, slabší a poslušnější."],["Uzavřete nabídku. Nechte si ty, kdo zůstali.","Krvácení se zastaví na sedmasedmdesáti tisících. Úřad pro personální řízení odhaduje náklady na nahrazení na devět miliard dolarů za šest let a ten odhad si nikdo nepřečte."],["Zacilte to. Nabídněte to jen tam, kde chcete snížit počty.","Přesnost místo plošné brokovnice. Dosáhnete stejného snížení stavů přesně tam, kde jste chtěl, a řídící letového provozu vám zůstanou."],["Nabídněte to sám sobě a uvidíte, co se stane.","Formulář nemá kolonku pro vaši pozici. Referentka z personálního oddělení stráví čtyři dny snahou to zpracovat, než to konečně předá právnímu oddělení."]]},"g-doge-cuts":{"t":"Číslo na obrazovce","x":"Vandermeer provozuje na webu živé počítadlo, které tvrdí, že se ušetřilo dvě stě čtrnáct miliard dolarů. Lyle prověřil jedenáct největších položek. „Čtyři jsou započítané dvakrát, tři jsou smlouvy, které už stejně vypršely, a jedna je o tisíc řádů mimo.“","c":[["Nechte počítadlo běžet. Zaokrouhlete nahoru.","Do jara číslo dosáhne tří set miliard. Každý novinář, který si to ověří, najde stejné chyby, a každá oprava se dostane asi ke čtyřicetině původního publika."],["Zveřejněte metodiku. Ať si to všichni ověří.","Ověřená částka činí devatenáct miliard dolarů, opravdu obrovská suma, kterou ale nikdo neocení, protože to není dvě stě čtrnáct miliard."],["Potichu počítadlo sundejte.","Do hodiny ho zarchivují čtyři různé služby, stejně jako všechno ostatní, navždy."],["Přidejte počítadlo peněz utracených za hledání těch úspor.","Druhé počítadlo předežene první během jedenácti týdnů. Vandermeer potichu odstraní obě a zveřejní graf o něčem úplně jiném."]]},"g-final-audit":{"t":"Dlouhé sčítání","x":"Dr. Weirová má součet: sedm set padesát tři samostatných žalob podaných proti vaší administrativě. „Pro srovnání, pane, to je víc než za předchozí čtyři prezidentská období dohromady. Nekomentuji to, jenom počítám.“","c":[["Zarámujte si to. Dokazuje to, kolik jste se toho pokusil udělat.","Číslo dáte na plakát. Je to opravdu důkaz ambicí, a zároveň důkaz všeho, co tvrdí druhá strana, a obě čtení se odvolávají na naprosto stejné číslo."],["Zeptejte se, které jste prohrál a proč.","Ve věci samé jste prohrál čtyřicet jedna procent, drtivá většina kvůli procesním chybám, ne kvůli obsahu. Čtyři zbývající politiky se ten samý měsíc přepíší a všechny čtyři obstojí."],["Řekněte, že to číslo dokazuje politizaci soudů.","Šedesát jedna procent rozhodnutí proti vám napsali soudci, které jmenovala vaše vlastní strana. Dr. Weirová má i tohle číslo, nabídne vám ho, a vy ho odmítnete přijmout."],["Požádejte ji, ať počítá dál i poté, co odejdete.","Počítá dál. Závěrečný svazek má devět set stran, vychází v roce 2044 a je věnován, bez sebemenší zjevné ironie, vám."]]},"h-tariff-boomerang":{"t":"Bumerang","x":"Lyle má seznam odvetných opatření. „Odpověděli nám položku za položkou, pane, a pak přidali bourbon, motorky a jednu konkrétní značku lodí. Všechno se vyrábí ve státech, které jste vyhrál. Musím uznat, že je to nádherně cílené.“","c":[["Zdvojnásobte clo. Nikdo nás nepřetvrdí.","Eskalace nadchne mítink a vyprázdní přístaviště. Obojí je pravda zároveň a základna vidí jen ten mítink."],["Lodě potichu vyjměte z výjimky. Proslov si nechte.","Výjimka se zahrabe v páteční administrativní podání, zatímco tvrdá rétorika zůstává v televizi. Celá práce, odvedená dobře, a nikdo si toho nevšimne."],["Za lodě obviňte minulou administrativu.","Přisoudíte clo na lodě, které jste sám způsobil, prezidentovi, který odešel před lety. Zhruba polovina země to okamžitě přijme za pravdu."],["Prohlaste bourbon strategickou národní zásobou.","Prezidentský dekret prohlásí whisky za záležitost národní bezpečnosti. Čtyři palírny jsou nadšené a jeden čtyřhvězdičkový generál se upřímně ptá, jaká je v tom jeho role."]]},"h-summit-selfie":{"t":"Fotka z podání ruky","x":"Muriel drží dvě fotografie. „Tohle je to podání ruky, pane. Čtyřicet milionů zhlédnutí. A tohle je skutečné komuniké. Zavazuje nás to k pracovní skupině, která se sejde nejdřív na jaře příštího roku. Základna viděla tu první. Senát četl tu druhou.“","c":[["Prodávejte podání ruky. Pracovní skupinu zahrabejte.","Fotka se ve všech praktických ohledech stává politikou samotnou. Nic nebylo dohodnuto a přesto má každý pocit, že se stalo něco obrovského."],["Ať Muriel věcně vysvětlí skutečné podmínky.","Pravda je malá, skutečná a nudná, a takhle se o ní i informuje. Podání ruky navzdory tomu záhadně dál trenduje."],["Oznamte druhý summit, na kterém proberete ten první.","Summit o summitu. Kancelář pro plánování schůzek pláče. Základna se nemůže dočkat."],["Nechte to podání ruky odlít do bronzu pro vstupní halu.","Sochař vyrobí stisk rukou v životní velikosti do haly Západního křídla. Návštěvníci nevědí, jestli si s ním mají potřást. Někteří to udělají."]]},"h-late-call":{"t":"Telefonát ve dvě ráno","x":"Deborah to zachytila v protokolu. „Volal jste vůdci spřátelené země ve dvě ráno jejich času, pane, abyste mu řekl, jak úžasně vypadá nový sál. Spal. Hovor trval devatenáct minut. Většinu z toho jste mluvil vy.“","c":[["Udělejte to zítra znovu. Líbilo se jim to.","Zavedete si noční zvyk nevyžádaných architektonických aktualizací pro spící hlavy států. Dva z nich to začnou přepojovat do hlasové schránky."],["Ať každý hovor jde nejdřív přes Deborah.","Mezi vás a telefon ve tři ráno se instaluje filtr. Je to zdaleka nejcennější personální rozhodnutí celého funkčního období."],["Popřete ten hovor. Sveďte to na časová pásma.","Tvrdíte, že jste se spletl v hodinách. Protokol má ale časové razítko. Slovo „časové razítko“ vám zkazí celé ráno."],["Příští hovor odvysílejte živě.","Dva miliony lidí sledují, jak viditelně vyčerpanému premiérovi popisujete stropní lišty. Je to nějakým způsobem vaše nejsledovanější vysílání roku."]]},"h-parade-itch":{"t":"Svrbění","x":"Generál Tarrant stojí v pohovu, což je u něj forma zděšení. „Ptal jste se mě tento týden třikrát, k čemu vlastně armáda *je*, pane, když ji nikdy nepoužijeme. Chci mít jasno v tom, že tohle není otázka, kterou bych chtěl slyšet od prezidenta v ospalé úterý.“","c":[["Nařiďte přehlídku. Největší v historii. Tento víkend.","Bulvár beztak nebyl stavěný na to, aby po něm jezdily tanky. Fotky jsou nádherné a inspektor mostů sepíše hlášení."],["Nic. Nechte generálovi jeho úterý.","Armádu z nudy nenasadíte. Tarrant viditelně omládne. Je to správné rozhodnutí a nikdo netleská."],["Místo toho přejmenujte vojenskou základnu po sobě.","Ceremonie, nová cedule, levnější druh slávy. Svrbění je poškrábané a nikdo kvůli tomu nemusí být nasazen."],["Zřiďte novou složku armády pro vesmír.","Vznikne nová vojenská složka, jejíž logo do týdne žaluje jedna streamovací franšíza. Rekruti jsou bez výjimky nadšení."]]},"h-upkeep-bill":{"t":"Údržba","x":"Alvin předkládá účetní knihu s péčí muže, který zneškodňuje bombu. „Jen lustry v sále, pane. A horská dráha vyžaduje certifikovanou inspekci každých devadesát dní, což prý platí i pro horskou dráhu na střeše. Vlastně obzvlášť pro horskou dráhu na střeše.“","c":[["Zaplaťte to. Velkolepost není položka v rozpočtu.","Účty jsou zaplaceny v plné výši a včas a budova se leskne. Ministr financí vydá tichý zvuk a opustí místnost."],["Odložte inspekce. Co se může stát.","Zrušíte bezpečnostní certifikaci horské dráhy na střeše. Čtyři úřady si otevřou spisy a jeden stážista se z principu odmítne svézt."],["Zaveďte vstupné do sálu.","Dům lidu se na chvíli stane místem se vstupným. Historička rezignuje faxem, dokumentem, jehož odeslání se musela nejdřív naučit."],["Přidejte suvenýrový obchod. Pak ještě dva.","O tři obchody se suvenýry, vozík s churros a fotokoutek později generuje rezidence měsíční zisk a památková komise dostává infarkt."]]},"h-merch-drop":{"t":"Nová kolekce","x":"Brayden je celý bez sebe. „Zlaté tenisky, pane. Pak parfém. Pak pamětní mince, pak Bible, a pak mince *s motivem* Bible. Každá kolekce se vyprodá během minut. Základna to nekupuje ironicky. Kupují si to tak, jak lidé kupují relikvie.“","c":[["Vypusťte všechno. Nový kousek každý týden.","Relikvie se množí a s nimi i oddanost. Jedna ekonomka to nazve kultem osobnosti s vynikající jednotkovou ekonomikou. Nemýlí se."],["Jeden vkusný kousek. Výtěžek pro veterány.","Zdrženlivost s charitativním přesahem. Tisk je na chvíli laskavý a základna se na chvíli nudí, oba pocity ale do čtvrtka pominou."],["Dejte svou tvář na skutečnou měnu.","Pokusíte se objevit na zákonném platidle. Mincovna vám nejprve jemně, pak rázně vysvětlí několik příslušných zákonů. Tenisky vám zůstanou."],["Spusťte memecoin. $PATRIOT. Dnes večer.","Vystřelí, spadne, do snídaně zase vystřelí. Někdo hodně aktivní na internetu vydělá a ztratí jmění ještě dřív, než začne ranní brífink."]]},"h-injunction":{"t":"Celostátní soudní zákaz","x":"Sy pokládá usnesení na stůl. „Jeden soudce, pane. V jedné soudní síni, ve státě, kde jste prohrál o třicet bodů, zmrazil celou věc na celostátní úrovni. Máte na výběr, buď se slušně odvolat, nebo říct o tom soudci něco, za co se pak měsíc budeme omlouvat.“","c":[["Jmenujte toho soudce. Zpochybňujte ho. Každý večer.","Z okresního soudce uděláte celostátně známé jméno a terč. Soudní systém se semkne tak, jako se tělo semkne kolem třísky."],["Odvolejte se. Přímo, rychle, nudně.","Právníci si tiše a dobře dělají svou právnickou práci. Věc postupuje po žebříčku soudů podle podstaty a základna se nikdy nedozví slovo „odklad“."],["Ignorujte to usnesení. Pokračujte i tak.","Chováte se, jako by soudní příkaz bylo pouhé doporučení. Je to zdaleka nejrychlejší způsob, jak naučit národ, jak vypadá ústavní krize."],["Jmenujte toho soudce na nějakou funkci. Hodně daleko.","Pokusíte se svůj problém povýšit na velvyslanecký post v chladné zemi. Soudce to nádherně, písemně odmítne, a informace unikne na veřejnost."]]},"h-leak-hunt":{"t":"Hon na únik informací","x":"Ředitelka Quistová je vyrovnaná. „Ten detail, co unikl, mohl přijít jen od jednoho z šesti lidí v té místnosti, pane. Všech šest je loajálních. V tom je ten problém: ten únik pramení z loajality. Někdo si myslí, že vás chrání tím, že vás vykreslí jako rozhodného. Není to tak.“","c":[["Podrobte všech šest detektoru lži. Ještě dnes.","Zapojíte své nejbližší poradce do přístroje se spornou spolehlivostí. Nikdo neselže a všichni si to budou pamatovat. Příští únik informací se bude týkat přímo detektorů lži."],["Nechte to být. Únik potichu utěsněte později.","Odmítnete hon na čarodějnice a místo toho opravíte proces. Je to zralé, účinné a naprosto neviditelné, jako všechno, co skutečně funguje."],["Uniknout nechte něco horšího o rivalovi, ať se to přebije.","Zorganizujete protiúnik. Příběh, který jste chtěl pohřbít, přebije jiný příběh, ze kterého se budete zodpovídat za šest týdnů. Vždycky to tak dopadne."],["Nastražte reportérovi falešný detail jako past.","Nastražíte kanárka. Otiskne se to. Právě jste potvrdil existenci úniku tím, že jste jeden sám vyrobil, což i Quistovou filozoficky znepokojuje."]]},"h-loyalty-oath":{"t":"Přísaha věrnosti","x":"Deborah je opatrná. „Ten nápad, co koluje, pane, je podepsaný slib. Osobní loajalita, písemně, nadřazená přísaze, kterou už složili úřadu. Někteří to podepíšou bez váhání. Ti, o které stojí za to usilovat, spíš rezignují, jakmile je o to požádáte.“","c":[["Rozešlete ten slib. Uvidíte, kdo se zarazí.","Schopní odejdou, poslušní zůstanou a průměrné IQ budovy měřitelně klesne. Základna tomu říká vypouštění bažiny."],["Žádný slib. Přísaha úřadu je jediná přísaha.","Odmítnete se v podepsaném dokumentu postavit nad ústavu. Historici o desítky let později to shledají naprosto nezajímavým, což je celý smysl."],["Ať přísahají vlajce. Stejná energie, lepší dojem.","Vlastenecký přebal téhož požadavku. Skvěle se to fotí a znamená to přesně to, co si všichni myslí."],["Ať přísahají na novou pamětní Bibli.","Přísaha věrnosti zároveň slouží jako product placement. Pastor je nadšený, právníci ne, a Bible se dočká dalšího dotisku."]]},"h-bad-poll":{"t":"Špatný průzkum","x":"Nadia to nezabaluje do bavlnky. „Je to skutečný průzkum, pane, se skutečnou metodikou, a to číslo je špatné. Můžete zaútočit na agenturu, což zabere na základnu a jen na základnu, nebo se podívat, proč je to číslo špatné, což tady v budově nikdo nedělá rád.“","c":[["Prohlaste průzkum za podvrh. Odkažte na vlastní, lepší.","Vytvoříte interní průzkum se vzorkem lidí, kteří s vámi už souhlasí. Základna ho okamžitě přijme a realita se ani nehne."],["Prostudujte podrobné výsledky. Změňte jednu politiku.","Necháte data ovlivnit rozhodnutí. Je to ta nejméně dramatická věc, jakou může vůdce udělat, a zároveň jedna z nejvzácnějších, a potichu to posune skutečné číslo."],["Objednejte deset průzkumů, dokud jeden nevyjde dobře.","Kupujete pokusy, dokud jeden nevyjde příznivě, a pak citujete jen ten. Je to drahé, průhledné a naprosto účinné u vlastních příznivců."],["Udělejte průzkum o tom, jestli lidé věří průzkumům.","Průzkum o průzkumech přinese výsledek příliš rekurzivní na to, aby ho kdokoli dokázal vyložit. Dva komentátoři si na té nejednoznačnosti vybudují celou kariéru."]]},"h-deepfake":{"t":"Přesvědčivý podvrh","x":"Kaylee je bledá. „Není to skutečné, pane. To video s vámi je od začátku do konce vyrobené, a je to bezchybné. Problém je druhého řádu: teď, když všichni vědí, že existují takhle dobré podvrhy, můžete cokoli skutečného označit za falešné a cokoli falešného za skutečné. Ztratili jsme schopnost si být čímkoli jistí, a stejně na tom je i každý ostatní.“","c":[["Nazývejte každé nelichotivé video podvrhem, navždy.","Nástroj si osvojíte jako trvalé alibi. Pravda se stane otázkou loajality, což je na chvíli nesmírně výhodné, a pak přestane být."],["Podpořte skutečný standard ověřování. Nudné. Zásadní.","Podpoříte nudný technický rámec pro ověřování záznamů. Je to nejdůležitější věc, kterou za celý rok uděláte, a najde se o ní zmínka na devatenácté straně."],["Vypusťte vlastní podvrh, o rivalovi.","Záměrně eskalujete situaci do světa, kde se nedá věřit ničemu, protože mlha nahrává tomu, kdo je nejhlasitější. Nahrává vám, dokud nepřestane."],["Nasaďte umělou inteligenci, která vaším hlasem vyvrací podvrhy.","Syntetická verze vás sama ověřuje faktickou přesnost jiné syntetické verze vás. Někde jedna filozofická katedra zruší vlastní konferenci, jen aby to mohla sledovat."]]},"h-nobel-itch":{"t":"Cena","x":"Muriel šlape opatrně. „Výbor nepřijímá nominace od samotného nominovaného, pane. A rozhodně nepřijímá sedm nominací, které jste podal sám na sebe. Existuje ale mír, který byste mohl skutečně zprostředkovat a který by si to časem mohl zasloužit. Vyžadovalo by to ale, abyste nechal u pódia stát někoho jiného.“","c":[["Nominujte se znovu. Hlasitěji.","Osmá vlastní nominace se podá spolu s tiskovou zprávou. Výbor, který viděl už úplně všechno, tohle úplně neviděl, a mlčí, nákladně."],["Zprostředkujte to doopravdy. Ať zazáří vyslanec.","Odvedete trpělivou práci skutečné diplomacie, kde se zásluhy sdílejí. Za pár let by za to mohla dokonce být cena, což je přesně důvod, proč je to teď tak těžké udělat."],["Založte si vlastní cenu. Udělte ji sám sobě.","Nová medaile, nový výbor, předem daný výsledek. Základna je dojatá. Starý výbor zůstává, nápadně, dál v Oslu."],["Prohlaste, že jste ji tajně už vyhrál.","Oznámíte utajenou cenu, kterou nelze z důvodu národní bezpečnosti ověřit. Zhruba třetina země si to zařadí do šuplíku „nejspíš pravda“."]]},"i-ukraine-war":{"t":"Čí válka to vlastně je","x":"Muriel rozprostírá mapu. „Rusko dál drtí Ukrajinu, pane, a všichni v té místnosti chtějí vědět, na čí straně stojíte. Základna chce, aby peníze přestaly proudit. Spojenci chtějí, aby proudily dál. Prezident Volkov chce telefonát. Ať řeknete v příští hodině cokoli, stane se to politikou.“","c":[["Podpořte Ukrajinu. Vyzbrojte ji, nahlas.","V přímém přenosu se postavíte za Kyjev. Aliance je nadšená, základna se nudí a faktury jsou obrovské."],["Místo toho ujednejte dohodu s Volkovem.","Vynecháte spojence a zavoláte přímo agresorovi. Dohodne se „rámec“, u kterého nikdo jiný nebyl. Základna miluje silného muže, který zvedne váš telefonát."],["Zprostředkujte mír. Přiberte si zásluhy.","Prohlásíte se za jediného muže, který to dokáže ukončit. Naplánuje se summit. Nic se nepodepíše, ale slovo „Nobelova“ padne nahlas, z vašich úst."],["Odstupte od toho. Není to náš kontinent.","Prohlásíte to za evropský problém a odstoupíte. Základna jásá nad úsporností. Tři hlavní města si potichu začínají domlouvat vlastní ujednání."]]},"i-taiwan":{"t":"Ten ostrov, co má každý na mysli","x":"Generál Tarrant má satelitní záběry. „Předseda Čchen pořádá kolem ostrova zatím největší cvičení, pane. Je to zkouška a chce, abychom věděli, že je to zkouška. Můžeme propluot letadlovou lodí úžinou, nebo si najít něco naléhavého jinde. Obojí si všimnou.“","c":[["Propluje letadlová loď úžinou. Pomalu.","Sto tisíc tun šedé oceli si vybere malebnou trasu skrz úžinu. Nic se nestane, nákladně a záměrně."],["Prodejte Tchaj-wanu úplně všechny zbraně z katalogu.","Vyzbrojíte ostrov až po zuby a naúčtujete mu za tu výsadu. Peking zuří, vaši zbrojní dodavatelé po vás pojmenují křídlo výrobního závodu."],["Ujistěte Čchena, že je to „jedna země“, a zavěste.","Vyřknete frázi, kterou chtěl slyšet, a ukončíte hovor. Obchodní oddělení si oddechne. Tchaj-pej si přepis přečte dvakrát."],["Zveřejněte na sociální síti mapu. Ať si domýšlejí.","Zveřejníte mapu bez jediného popisku. Šest vlád svolá mimořádná zasedání, aby ji vyložily. Nemyslel jste tím vůbec nic. Málokdy tím něco myslíte."]]},"i-iran-enrich":{"t":"Centrifugy","x":"Šéfka tajné služby mluví bez emocí. „Írán je blízko, pane. Naši lidé odhadují dva týdny od prahové hodnoty. Můžeme udeřit na zařízení a zpozdit je o tři roky, můžeme je udusit sankcemi, nebo jim můžeme nabídnout dohodu, kterou nedokázali sjednat poslední tři prezidenti. Každá možnost vám udělá dva přátele a jednoho nepřítele.“","c":[["Udeřte na zařízení. Ještě dnes v noci.","Zařízení je do svítání sutina a region je do poledne sud s prachem. Základna tomu říká síla. Zálivové státy volají svým aerolinkám."],["Sankcemi je uvrhněte zpátky do doby kamenné.","Odříznete je od všeho, co má drát. Jejich ekonomika se hroutí, jejich program ne. Je to pomalé, popíratelné a nekonečné."],["Sjednejte dohodu, kterou nikdo jiný nedokázal.","Podepíšete dohodu, kterou poslední tři prezidenti nedokázali sjednat, a vyzýváte kohokoli, ať ji nazve slabošskou. Polovina z nich to okamžitě udělá."],["Prodejte to potichu oběma stranám.","Nějakým způsobem změní majitele jmění a Teherán i jeho nepřátelé věří, že stojíte při nich. Čtyři etické komise si otevřou spisy přímo během podpisu."]]},"i-nato-dues":{"t":"Pošlete fakturu","x":"Muriel má zasedací pořádek. „Jsou tu všichni, pane, a všichni jsou nervózní, přesně tak, jak je má základna ráda. Můžete znovu potvrdit závazek je bránit, můžete je nechat platit napřed, nebo můžete jen naznačit, jen naznačit, že celé to ujednání je volitelné. Už jen ten náznak hýbe trhy.“","c":[["Znovu potvrďte závazek. Pevně. Nudně.","Řeknete, že smlouva znamená přesně to, co v ní stojí. Spojenci spí klidně, základna zívá, nikdo nesloží píseň o Článku 5."],["„Zaplaťte svůj podíl, pak si promluvíme.“","V přímém přenosu proměníte obrannou dohodu ve fakturu. Dvě vlády náhle oznámí nové výdaje. Základna zbožňuje muže, který donutí přátele platit."],["Naznačte, že celé to ujednání je volitelné.","Nahlas pochybujete, jestli byste se opravdu dostavil. Ten náznak je politikou. Někde nějaká menší země začíná vlastní jaderný program."]]},"i-arctic":{"t":"Vrchol mapy","x":"Lyle má mapu, která je tam, kde bývala bílá, teď hlavně modrá. „Arktida se otevírá, pane. Pod tím ledem je století vzácných zemin a obchodní trasa v hodnotě HDP celé země. Rusko zapíchlo vlajku na mořské dno. Grónsko, ehm, technicky není na prodej. Všichni jsou nesmírně zdvořilí a kupují ledoborce.“","c":[["Předložte Grónsku nabídku, kterou nemůže odmítnout.","Předložíte finanční nabídku za ostrov, který stále tvrdí, že není na prodej. Základna je nadšená. Kartografové zatím nic neaktualizují."],["Zapojte se do závodu s Ruskem o mořské dno. Stavte ledoborce.","Objednáte flotilu, jejímž jediným posláním je drtit led. Je to drahé, pomalé a, upřímně řečeno, skutečná strategie."],["Domluvte si s Volkovem polární rozdělení.","Vy a Volkov si v tichosti rozdělíte oceán, který nepatří ani jednomu z vás. Mapa se překreslí nad večeří. Šest dalších arktických zemí se to dozví až později."]]},"i-coup":{"t":"Muž na balkoně","x":"Šéfka tajné služby má noční hlášení. „Došlo k převratu, pane, v zemi, kterou potřebujeme kvůli naší tamní základně. Nový muž stojí na balkoně, má na sobě spoustu medailí a tvrdí, že je vaším velkým obdivovatelem. Stará vláda se z neznámého místa ptá, jestli ji ještě uznáváme.“","c":[["Uznejte generála. Obdivuje vás.","Jste první, kdo tomu balkonu poblahopřeje. Základna má ráda muže, kterému se líbíte. Tři demokracie potichu sníží úroveň svých velvyslanectví."],["Odsuďte to. Požadujte volby.","Z principu uděláte to správné, nudné rozhodnutí. Základna vás nechá chladnou a posádka na vaší zahraniční základně je nervózní. Historie přikývne a jde dál."],["Neříkejte nic, dokud neuvidíte průzkumy.","Počkáte, kterým směrem se to ustálí, než se zavážete k nějakému názoru. Je to cynické, bezpečné a podle důkazů i typický rukopis tohohle úřadu."]]},"i-trade-bloc":{"t":"Založili klub","x":"Lyle drží tiskovou zprávu, ze které nemá radost. „Vytvořili blok, pane. Tucet zemí, které spolu volně obchodují a nápadně neobchodují s námi. Je to přímá reakce na cla. Můžeme se tam silou vrátit, můžeme si postavit vlastní konkurenční klub, nebo na to celé uvalit cla a uvidíme, kdo zamrká první.“","c":[["Uvalte cla na celý blok najednou.","Vyhlásíte hospodářskou válku dvanácti zemím ještě před obědem. Základna je v extázi. Někde se prostě zastaví kontejnerová loď."],["Postavte konkurenční klub. Náš bude větší.","Sestavíte vlastní obchodní blok, trváte na tom, že je lepší, a obsadíte ho kýmkoli, kdo se dostaví. Dva členové nemají tušení, proč byli pozváni."],["Vraťte se tam silou. Spolkněte hrdost.","Vyjednáte si cestu zpátky do klubu, ze kterého jste byl vyloučen, potichu, u stolu blízko dveří. Ekonomika se zotaví. Základna se nedozví nic."]]},"i-scs-reef":{"t":"Útes s ranvejí","x":"Generál Tarrant má fotky před a po. „Byl to útes, pane. Teď je to přistávací dráha s útesem pod sebou. Čína ji postavila v obchodní trase, kterou si nárokují ještě čtyři další země. Všechny čtyři se ptají, jestli Spojené státy hodlají něco udělat, nebo jen něco říct.“","c":[["Propluje kolem ní. Dvakrát.","Provedete plavbu na obranu svobody plavby dost blízko na to, abyste přečetl místní cedule. Nikdo nestřílí. Všichni to fotí. Smysl, jaký měl mít, je splněn."],["Místo toho vyzbrojte čtyři sousední země.","Ze čtyř nervózních sousedů uděláte čtyři ozbrojené sousedy a necháte zeměpis, ať udělá zbytek. Peking podá stížnost, kterou si zarámujete a pověsíte na zeď."],["Vyměňte útes za výhodnější clo.","Potichu přestanete zmiňovat přistávací dráhu výměnou za něco s dolarovým znakem. Čtyři spojenci si toho mlčení všimnou. Stejně tak útes."]]},"i-nk-missile":{"t":"Narozeninový start","x":"Generál Tarrant je téměř dojatý. „Nejvyšší vůdce vypustil další raketu, pane. Naštěstí do moře, a jak se zdá, přímo o svých narozeninách. Je to vzkaz, a ten vzkaz zní, že by rád, abyste o něm něco řekl. Vždycky to tak chce. Máte jeho číslo.“","c":[["Zavolejte mu. Pochvalte tu raketu.","Zavoláte do poustevnického království a pochválíte řemeslné zpracování. Je nadšený. Oba se shodnete, že jste teď velmi dobří přátelé. Ministerstvo zahraničí si jde lehnout."],["Oheň a zuřivost. Starý klasik.","Ráno pohrozíte totální zkázou a do oběda na to zapomenete. On kvůli pozornosti vypustí další raketu. Je to fungující vztah."],["Naprosto ho ignorujte. Ničí ho to.","Neřeknete vůbec nic, což je jediná věc, kterou nesnese. Příští raketa je větší a ještě jasněji adresovaná vám."]]},"i-hostages":{"t":"Ti, které drží","x":"Muriel je u tohohle opatrná. „Drží naše lidi, pane, tři z nich, na základě obvinění, kterým nikdo nevěří. Chtějí výměnu: svého vězně, hromadu peněz, nebo fotku, jak si podáváte ruku s mužem, kterého jste nazval netvorem. Rodiny budou dnes večer v televizi tak jako tak.“","c":[["Uskutečněte výměnu. Přiveďte je domů.","Zaplatíte výkupné, které nikdo nepřizná jako výkupné, a tři občané přejdou po ranveji přímo před kamery. Je to dobrý den a strašný precedens."],["Odmítněte. My nevyjednáváme.","Z principu se držíte pevně a rodiny svolají tiskovku. Základna respektuje páteř. Vyjednávání pokračuje, neoficiálně, navždy."],["Podejte mu ruku. Ať to má fotka za sebou.","Před kamerami stisknete ruku muže, kterého jste nazval netvorem, a dostanete své lidi zpátky. Fotka přežije celé prezidentské období. Stejně tak i ti občané, což je celý smysl."]]},"i-cyber":{"t":"Ve třech státech zhasla světla","x":"Šéfka tajné služby ani nemrkne. „Někdo vypnul proud ve třech státech na devět hodin, pane. Víme kdo. Umíme si to dokázat sami sobě, ale ne úplně u soudu. Můžeme jim to oplatit hackerským útokem, můžeme je sankcionovat, nebo to udržet v tichosti, aby se trhy nedozvěděly, jak snadné to bylo.“","c":[["Oplaťte jim to hackerským útokem. Tvrději.","Na jejich straně světa něco zhasne a nikdo se k tomu nepřihlásí. Je to popíratelné, je to přiměřené a spouští to hodiny, které nikdo nevidí."],["Sankcionujte je za bílého dne.","Pojmenujete je, zostudíte je a zmrazíte, co je v dosahu. Je to legální varianta a se světly to udělá přibližně nic."],["Zahrabejte to. Trhy se to nesmí dozvědět.","Celou věc udržíte v tichosti a doufáte. Trhy se nikdy nedozví, jak tenký je ten led. Zatím to neví ani nikdo, kdo by to mohl opravit."]]},"i-refugees":{"t":"Kolona u hranice","x":"Duane má noční čísla. „Válka o dvě země dál vyhnala na silnici kolonu lidí, pane, a ta silnice končí na naší hranici. Základna chce zeď s příkopem. Kostely chtějí přivítání. Kamery chtějí záběr, a jeden z těch dvou dostanou, záleží na vás.“","c":[["Zavřete ji. Kamery, zeď, kompletní balík.","V přímém přenosu s maximálním divadlem uzavřete hranici. Základna jásá. Záběr, který kamery natočily, je ten, na který se vás budou ptát navždy."],["Zpracujte je. Potichu, podle předpisů.","Uděláte legální, logistickou, nefotogenickou věc. Funguje to a nezíská vám to nic. Základna slyší jen to, že jste nepostavil ten příkop."],["Pošlete je autobusem do státu rivalského guvernéra.","Naložíte problém do autobusu a pošlete ho člověku, který vás naštval. Je to kruté, je to podfuk, a vede to zprávy přesně tak, jak jste doufal."]]},"i-nobel":{"t":"Telefonát z Osla","x":"Muriel sotva věří tomu, co říká. „Máte tu skutečnou šanci, pane. Dvě vlády, které po sobě deset let střílejí, budou příští týden obě ve stejné budově a obě zvednou váš telefon. Mohlo by to opravdu skončit. Taky by to ale, pokud to přeženete, mohlo zkolabovat přímo před kamerami. A ano, lidé už to slovo pomalu vyslovují.“","c":[["Odveďte tichou diplomacii. Dotáhněte to.","Skloníte hlavu, dva týdny pracujete na telefonech a válka opravdu skončí. Je to nejlepší věc, jakou kdy uděláte, a trenduje to šest hodin."],["Oznamte cenu ještě před mírem.","Vyhlásíte vítězství, a sám sebe laureátem, o několik kritických dní dřív. Jedna delegace odejde kvůli formulaci vašeho příspěvku na sociální síti. Válka se na chvíli obnoví."],["Ať to podepíšou ve vašem hotelu.","Mír vypukne v sále, nad jehož dveřmi visí vaše jméno, a s příplatkem za pokojovou službu. Vydrží. Značka, na tom se všichni shodnou, je to hlavní téma."]]},"p-economy-1":{"t":"Šok z cenovky","x":"Ministr financí položí na stůl účtenku z obchodu, jako by to byla obsílka. Vejce zdražila o šedesát procent a kabelové zpravodajství natáčí reportáže před supermarkety. „Pane prezidente, lidé jsou naštvaní, a naštvaní lidé sledují zprávy.“","c":[["Vyhlásit dekret zmrazující všechny ceny potravin do pátku","Regály se přes víkend vyprázdní, protože obchody prostě přestanou doplňovat zmrazené položky."],["Nechat centrální banku zvednout sazby a přijmout politický zásah","Inflace do jara opadne. Nikdo si nepamatuje, kdo to napravil, jen kdo to dopustil."],["Nařídit statistickému úřadu, ať prostě zveřejní nižší číslo","Skutečné ceny zůstanou stejné. Jediné, co se změní, je to, komu můžete věřit."],["Přejmenovat inflaci na celostátní televizi na „cenu svobody“","Galon mléka teď stojí jedenáct dolarů a špetku vlastenectví navrch."]]},"p-economy-2":{"t":"Poslední píšťalka","x":"Vantage Steel zavírá továrnu v Dunmore, tu samou, před kterou jste v kampani stáli s vyhrnutými rukávy. Tři tisíce pracovních míst, jedna fotka, pryč během jednoho odpoledne. „Přesouvají linku do Guatemaly,“ říká ministryně práce. „Dělníci se to dozvěděli esemeskou.“","c":[["Veřejně to svalit na zahraniční obchodní spiknutí proti Dunmore","Vantage Steel vydá prohlášení. Nezmění to nic, jen to, koho budou v hospodě vinit."],["Prosadit skrz Kongres skutečný program rekvalifikace a přestěhování","Stojí to peníze a trvá roky, ale skutečně to pomůže jedenácti stům rodin. To nikdo nefotí."],["Znárodnit továrnu výnosem a vyzvat soudy, ať vás zastaví","Továrna se otevře pod novým nápisem. Ocel, kterou vyrábí, nemá kam výhodně jít."],["Osobně zavolat řediteli továrny a poprosit ho, ať ji prostě nezavírá","Ředitel je velmi zdvořilý. Továrna zavře přesně podle plánu."]]},"p-economy-3":{"t":"Kobaltová opona","x":"Předseda Wei zakázal veškerý vývoz vzácného kobaltu jako odvetu za loňská cla. Každá továrna na baterie v Rezavém pásu má zásoby asi na šest týdnů. „Celý plán elektromobilů jsme postavili na minerálu, který sami netěžíme,“ přiznává ministr zahraničí.","c":[["Vyhlásit celostátní nerostnou nouzi a zabavit soukromé zásoby","Firmy raději zbylý kobalt schovávají, než aby ho odevzdaly."],["V tichosti sjednat dodávky s přátelštější surovinově bohatou zemí","Funguje to, je to nudné a trvá to osm měsíců neokázalých telefonátů."],["Vyhrožovat invazí do surovinově bohatého spojence, aby se zajistily dodávky","Spojenec svolá nouzový summit. Stejně tak zbytek kontinentu."],["Vyhlásit havarijní program těžby kobaltu ze staré skládky v Ohiu","Skládka vydá kobalt na čtyři baterie a spoustu metanu."]]},"p-economy-4":{"t":"Hod mincí","x":"Token zvaný FreedomCoin, který jste možná pochvalně zmínili na jednom mítinku, přes noc ztratil devadesát jedna procent hodnoty. Šéf centrální banky drží výtisk rozzuřených důchodců z fóra jménem r/rugged. „Pane prezidente, někteří z těchto lidí do toho vložili penzi.“","c":[["Oznámit, že vláda osobně zaručí hodnotu FreedomCoinu","Ministerstvo financí teď ručí za měnu, kterou vymyslel muž jménem Chad."],["Předat burzu regulátorům a nechat ztráty být","Nikdo nedostane peníze zpátky, ale příští podvod bude o trochu menší."],["Svalit propad na centrální banku soupeřící velmoci","Obvinění je nepodložené a nesmírně populární."],["Spustit druhý, stabilnější token jménem FreedomCoin Plus","Také se zhroutí, ale trvá to celých jedenáct dní, což někteří nazývají pokrokem."]]},"p-economy-5":{"t":"Zase moc velká na pád","x":"Continental Trust, šestá největší banka v zemi, je potichu insolventní. Pokud v pondělí otevře bez záchrany, říká ministr financí, „čeká nás run na banku, proti kterému bude ten poslední vypadat jako dobročinný bazar.“","c":[["Zachránit ji přes noc a nechat řediteli jeho bonus","Banka přežije. Bonus se na měsíc stane pravidelnou rubrikou zpráv."],["Prosadit řízený zánik s odvoláním vedení","Je to spravedlivé, uspořádané a přesně nikoho, kdo sleduje svůj penzijní účet, to neuspokojí."],["Zachránit ji a v tichosti obsadit novou správní radu vašimi dárci","Banka je zachráněna. Stejně tak, velkoryse, i pár vašich přátel."],["Promluvit k národu s malou keramickou prasečí pokladničkou v ruce","Trhy se stabilizují. Pokladnička se vyprodá ve třech různých obchodech se suvenýry."]]},"p-economy-6":{"t":"Všichni ven","x":"Železničáři, přístavní dělníci a letečtí mechanici vypochodovali ven ve stejné úterý, což odbory nazývají shodou okolností a ministryně práce „nejsehranější náhodou, jakou jsem kdy viděla“.","c":[["Nařídit Národní gardě, ať vlaky a přístavy řídí sama","Náklad se zase pohybuje, špatně, řízen vojáky, kteří v životě neviděli seřaďovací nádraží."],["Sednout s vedením odborů a vyjednat skutečnou smlouvu","Trvá to jedenáct hodin a hodně mizerné kávy, ale vlaky zase jezdí načas."],["Prohlásit stávku za nezákonnou a vyhrožovat hromadným propouštěním","Polovina zaměstnanců se vrátí vyděšená. Z druhé poloviny se stane lidová píseň."],["Osobně řídit vysokozdvižný vozík v přístavu pro kamery","Přesunete jednu paletu, špatně, a stane se to nejsledovanějším klipem roku."]]},"p-economy-7":{"t":"Podání ruky, které nebylo","x":"Historická obchodní dohoda s Meridií byla dnes ráno podepsána s velkou pompou, třemi vlajkami a plnicím perem ve tvaru orla. Vedoucí kanceláře právě zjistila, že skutečný dokument neobsahuje jediné závazné ustanovení. „Je to fotka,“ říká. „Podepsali jsme fotku.“","c":[["Přesto to nazvat historickým a jít dál, než si to někdo přečte","Analytici si toho nakonec všimnou. Do té doby se zpravodajský cyklus otočil třikrát."],["Přiznat, že šlo o symbolické gesto, a slíbit skutečnou dohodu do konce roku","Nikdo netleská upřímnosti, ale skuteční vyjednavači konečně dostanou opravdový mandát."],["Tvrdit, že Meridia potají couvá, a hrozit novými cly","Meridijský velvyslanec je zmatený. Základnu to i tak nadchne."],["Přerámovat samotné orlí pero na historický úspěch","Pero se v obchodě se suvenýry vyprodá do hodiny."]]},"p-economy-8":{"t":"Clo na brie","x":"Jako odvetu za nesouvisející rybářský spor jste uvalili čtyřsetprocentní clo na dovážený měkký sýr. Ministr financí hlásí, že domácí produkce brie je a vždy byla prakticky nulová. „Pane prezidente, zdaňujeme produkt, který tu neexistuje.“","c":[["Rozšířit clo na všechny měkké sýry, z principu","Sýrové mísy po celé zemi jsou znatelně smutnější a vlastenečtější."],["Potichu clo zrušit, než se zorganizuje lobby restaurací","Brie se vrací do regálů. Rybářský spor zůstává zcela nevyřešen."],["Vyhlásit federální dotaci na rozjezd americké výroby brie","V Nebrasce se otvírá pilotní farma na brie. Odborníci zůstávají hluboce skeptičtí."],["Prohlásit čedar za jediný sýr, který pravý vlastenec potřebuje","Prodej čedaru vzroste o jedenáct procent. Někde si povzdechne francouzský ministr."]]},"p-economy-9":{"t":"Maličkost pro Chada","x":"Nový dotační program na čistou energii poslal, čirou náhodou, devadesát procent prostředků solární firmě vlastněné vaším největším sponzorem, mužem jménem Chad Bellwether. „Vyjde to najevo,“ varuje ministr energetiky. „Tyhle věci vždycky vyjdou najevo.“","c":[["Trvat na tom, že firma prostě měla nejlepší žádost","Novináři do týdne najdou fotky z golfu. Základnu to nezajímá."],["Otevřít dotační program skutečnému konkurenčnímu výběrovému řízení","Bellwetherova firma prohraje nové kolo proti firmě z Nevady se skutečnými inženýry."],["Dát Bellwetherovi druhou, ještě větší zakázku, aby se dokázalo, že se nic neskrývá","Něco se skutečně skrývá. Teď je to dvakrát tak velké."],["Přejmenovat program po fiktivním průměrném Američanovi jménem Chad","Skutečný Chad Bellwether to považuje za skvělý vtip. Nikdo jiný ne."]]},"p-economy-10":{"t":"Bolest u pumpy","x":"Benzin po požáru ropovodu překročil šest dolarů za galon a ministryně energetiky říká, že kamioňáci vyhrožují blokádou dálničního okruhu kolem hlavního města. „Tohle je číslo, které končí prezidentství,“ říká věcně.","c":[["Nařídit úplné vyčerpání strategických rezerv, aby se srazila cena","Ceny na šest týdnů klesnou. Rezervy jsou teď nebezpečně, potichu prázdné."],["Místo toho investovat příjmy z windfall daně do veřejné dopravy","Pomůže to za tři roky. Nepomůže to nikomu, kdo dnes v noci stojí v koloně."],["Bez důkazů svalit požár ropovodu na zahraniční sabotáž","Obvinění ovládne zpravodajský cyklus. Ropovod byl ve skutečnosti prostě starý."],["Osobně natankovat cizímu řidiči na kameru a prohlásit problém za vyřešený","Jeden velmi šťastný řidič dostane benzin zdarma na den. Všichni ostatní pořád platí šest dolarů."]]},"p-economy-11":{"t":"Chybějící čip","x":"Jedna zatopená továrna v Chosanu zastavila globální dodávky polovodičů a automobilky ve třech státech stojí. „Každý vůz, který nepostavíme,“ říká ministr financí, „je titulek, který si nemůžeme dovolit.“","c":[["Zabavit domácí zásoby čipů a přesměrovat je oblíbeným automobilkám","Dva závody se okamžitě znovu rozjedou. Šest dalších do čtvrtka podá žalobu."],["Zrychlit povolení pro nové domácí továrny na výrobu čipů","Výstavba začíná do měsíce. Továrny nevyrobí jediný čip dva roky."],["Vyhlásit úplný zákaz vývozu čipů do zemí soupeřících s Chosanem, jako páku","Nic to nezmění na povodni. Hodně to ale změní na vztazích."],["Navrhnout, že vozy prozatím pojedou bez infotainmentu na obrazovce","Kupující jsou rozzuření. Prodejci s údivem zjišťují, že překvapivé množství lidí obrazovku nechce."]]},"p-economy-12":{"t":"Domeček z karet","x":"Ceny domů v šesti velkých metropolích se za osmnáct měsíců zdvojnásobily a ministr financí drží graf nepříjemně podobný tomu z roku dva tisíce osm. „Pane prezidente, kdo si to může dovolit, kupuje rovnou tři.“","c":[["Vinit stejně hlasitě přistěhovalce i investory","Je to uspokojivé vysvětlení. Většinou to ale není ten skutečný důvod."],["Postupně zpřísnit pravidla pro hypotéky, aby se trh ochladil","Noví kupující vám tiše děkují. Současní majitelé sledující svůj kapitál nikoli."],["Dekretem zakázat všechny firemní nákupy rodinných domů","Každá velká realitní firma do týdne podá žalobu. Základna tenhle souboj miluje."],["Navrhnout mladým lidem, ať si prostě řeknou rodičům o vyšší půjčku","Klip se stane virálním ze všech špatných i pár správných důvodů."]]},"p-economy-13":{"t":"Problém s penzemi","x":"Meziregionálnímu penzijnímu fondu Teamsters chybí devět miliard dolarů a půl milionu důchodců se má dozvědět, že jejich šeky se zmenšují. „Pracovali na tom čtyřicet let,“ říká ministryně práce. „Neudělali nic špatně.“","c":[["Potichu nechat fond snížit dávky a vinit správce fondu","Důchodci dostanou menší šeky. Správci fondu dostanou velmi přísný dopis."],["Prosadit v Kongresu federální záruku, která pokryje schodek","Stojí to daňové poplatníky miliardy a zachrání to půl milionu důchodů. Obojí je pravda."],["Nařídit centrální bance, ať schodek přes noc potichu dotiskne","Šeky přijdou včas. Ekonomové stráví příští rok vysvětlováním, proč je to znepokojivé."],["Uspořádat televizní bingo večer pro důchodce na zvednutí morálky","Morálka je krátce vynikající. Devítimiliardová díra zůstává přesně devítimiliardovou dírou."]]},"p-economy-14":{"t":"Měnová hra nervů","x":"Prezident Volkov nazval dolar ve státní televizi „umírajícím reliktem“ a záměrně znehodnotil rublu podobnou měnu solyanku, aby podrazil americký export. „Snaží se vás vyprovokovat k veřejné reakci,“ varuje ministr financí. „Nenaleťte na to.“","c":[["Odpálit to zpátky na sociálních sítích a nazvat ho zkrachovalým tyranem","Trhy sebou trhnou. Volkov, nadšený, odpoví do hodiny."],["Nechat reagovat pouze ministerstvo financí tichými diplomatickými kanály","Kurz se do týdne stabilizuje. Nikdo netleská tichu, které to zařídilo."],["Nařídit symbolický hromadný výprodej dluhopisů solyanky, aby ho to potrestalo","Ministerstvo financí to stojí víc než Volkova, ale je z toho skvělý titulek."],["Poslat Volkovovi jednu pamětní minci s nápisem „Druhá nejlepší měna světa“","Státní média se o tom nikdy nezmíní. Váš vlastní tiskový úřad nepřestane."]]},"p-economy-15":{"t":"Nekupujte americké","x":"Po vašem posledním projevu o clech se po třech kontinentech rozšířil občanský bojkot amerického zboží a ministr zahraničí hlásí, že oblíbená značka limonády byla v Meridii úplně stažena z regálů. „Jde o tu limonádu, pane prezidente. Bojkotují limonádu.“","c":[["Prohlásit bojkotující země za ekonomické nepřátele Ameriky","Bojkot se rozšiřuje. Zvláštně tak i domácí hrdost na limonádu."],["Nechat ministra zahraničí potichu stáhnout projev o clech","Bojkot za měsíc odezní. Nikdo doma si nevšimne, že vůbec nastal."],["Spustit ze vzdoru protibojkot meridijského dovozu","Meridijský dovoz jsou hlavně banány. Ceny v obchodech mírně stoupnou bez jakéhokoli strategického přínosu."],["Osobně vyslat maskota limonádové firmy na dobrovolnou misi","Maskot je vřele přijat. Limonáda zůstává zakázaná."]]},"p-economy-16":{"t":"Zpráva o zaměstnanosti","x":"Měsíční zpráva o zaměstnanosti poprvé za tři roky ukazuje čistou ztrátu pracovních míst a ministryně práce má tu nezáviděníhodnou úlohu přinést ji do Oválné pracovny. „Vnitřní čísla můžeme zabalit jinak,“ říká opatrně, „ale hlavní číslo je hlavní číslo.“","c":[["Prohlásit zprávu za podvrh a žádat rezignaci šéfa úřadu","Šéf pod tlakem rezignuje. Příští zpráva je horší a teď jí nikdo nevěří tak jako tak."],["Prezentovat skutečná čísla poctivě, s plánem, jak je řešit","Ekonomové si váží upřímnosti. Základna chtěla padoucha, ne tabulku."],["Svalit ztráty úplně na předchozí administrativu","Předchozí administrativa opustila úřad před dvěma lety. Na tom nezáleží."],["Předefinovat částečné úvazky a nezaměstnané jako „jinak zaměstnané“","Nové číslo vypadá skvěle. Fronta u potravinové banky vypadá stejně."]]},"p-economy-17":{"t":"Patnáct a bojujeme","x":"Koalice pracovníků rychlého občerstvení požaduje zvýšení federální minimální mzdy na dvacet dva dolarů a ministryně práce hlásí, že lobby restaurací v reakci hrozí hromadným propouštěním. „Obě strany si myslí, že ta druhá blafuje,“ říká. „Nikdo neblafuje.“","c":[["Hlasitě se postavit na stranu malých podniků a nazvat pracovníky nevděčnými","Lobby restaurací jásá. Pracovníci plánují mnohem větší pochod."],["Vyjednat postupné, mírné zvýšení, které obě strany snesou","Nikdo není nadšený. Obě strany se nerady, ale vrátí do práce."],["Slíbit plných dvacet dva dolarů výnosem už zítra","Nařízení je populární a téměř jistě nezákonné. Žaloby začnou okamžitě."],["Navrhnout pracovníkům, ať si o zvýšení řeknou přímo manažerům","Virální video přesně ukazuje, jak taková konverzace obvykle dopadá."]]},"p-economy-18":{"t":"Nic se nehýbe","x":"Přístavní dělníci v přístavu Harlow zastavili nakládku kvůli mzdovému sporu a ministr financí říká, že čtyřicet procent dováženého zboží teď kotví na lodích u pobřeží. „Každý další den,“ říká, „je za šest týdnů den prázdných regálů.“","c":[["Poslat federální dodavatele, ať lodě naloží sami","Dodavatelé jsou pomalí a nezkušení. Přístavní dělníci jsou teď rozzuření z úplně jiného důvodu."],["Financovat nezávislého mediátora, aby mzdový spor spravedlivě urovnal","Trvá to dva týdny a přinese to férovou smlouvu. Lodě se konečně dají do pohybu."],["Vyvolat mimořádný pracovní zákon, aby se dělníci okamžitě vrátili","Přístav se pod protesty znovu otevírá. Spor se prostě přesune do podzemí."],["Osobně vyjednávat přes hlasitý telefon z Resolute Desk","Hovor trvá čtyři hodiny a hlasitě nedosáhne téměř ničeho."]]},"p-economy-19":{"t":"Přátelský monopol","x":"Regulátoři zahájili antimonopolní šetření proti Halcyon Systems, technologickému gigantu, jehož generální ředitel náhodou štědře přispíval na vaše poslední dvě kampaně. „Důkazy jsou opravdu zdrcující,“ říká ministr financí. „Stejně tak i načasování vašich hovorů s ním.“","c":[["Potichu nechat šetření zaškatulkovat jako profesní laskavost","Šetření zmizí. Jeden velmi vytrvalý novinář nezmizí."],["Nechat regulátory dělat svou práci bez zásahů","Halcyon Systems je vysoce pokutován. Ředitel vám přestane brát hovory."],["Prohlásit šetření za politicky motivované kariérními úředníky","Regulátoři jsou přeloženi. Halcyon Systems posílá velmi štědrý dárek na poděkování."],["Navrhnout Halcyonu, ať se prostě přejmenuje, aby nezněl tak monopolně","Halcyon Systems se stává Halcyon Přátelské Systémy. Podíl na trhu zůstává identický."]]},"p-economy-20":{"t":"Na dně","x":"Váš příspěvek ve tři ráno, který nazval velkou automobilku „hanbou a podvodem“, smazal ze společnosti čtyřicet miliard dolarů za devadesát minut a tisková mluvčí odpovídá na hovory od každého ekonomického oddělení v zemi. „Pane prezidente, chtějí vědět, jestli to bylo úmyslné.“","c":[["Přitvrdit a napsat, že si firma zasloužila ještě víc","Akcie klesnou ještě víc. Vaše základna to nazývá zodpovědností."],["Potichu příspěvek smazat a dál nic neříkat","Akcie se částečně zotaví. Smazání se stává vlastním malým skandálem."],["Tvrdit, že propad na trhu dokazuje, že firma byla vždy zkorumpovaná","Neexistuje žádný důkaz korupce. Existuje teď kongresové vyšetřování vašeho příspěvku."],["Zveřejnit fotku sebe, jak si přesto kupujete auto té značky","Akcie o dvě procenta stoupnou. Nikdo úplně nechápe, proč to zabralo."]]},"p-economy-21":{"t":"Strop","x":"Kongres se zablokoval kolem zvýšení dluhového stropu a ministryně financí říká, že vládě dojdou účetní triky za jedenáct dní. „Pak,“ říká, „budeme vybírat mezi platem vojáků a platbou držitelům dluhopisů.“","c":[["Vyhrožovat ražbou pamětní bilionové mince a vyzvat je, ať protestují","Mince je právně sporná a nesmírně populární. Kongres se v naprosté trapnosti do pár dní vzdá."],["Obvolávat vedení Kongresu kvůli dvoustranické dohodě","Dohoda je nevzhledná, včasná a nikdo mimo Washington si nevšimne, že se to stalo."],["Vinit opoziční stranu, že drží platy vojáků jako rukojmí","Opozice vinu hodí zpátky na vás. Termín se blíží tak jako tak."],["Navrhnout platit držitelům dluhopisů pamětními mincemi místo hotovosti","Držitelé dluhopisů nejsou pobavení. Mince jsou, uznejme, docela pěkné."]]},"p-economy-22":{"t":"Šek pro farmáře","x":"Pěstitelé sóji ve čtyřech státech čelí odvetným clům soupeřící velmoci a úrodě, kterou nemají komu prodat. Ministr zemědělství navrhuje nouzový záchranný šek a pak tiše dodává: „Minule to šlo hlavně velkým podnikům, ne rodinným farmám.“","c":[["Poslat šeky rychle a detaily řešit později","Šeky přijdou do týdne. Stejně tak i příběhy o tom, které farmy dostaly ty největší."],["Navrhnout cílený program, který skutečně upřednostní malé rodinné farmy","Trvá to o tři týdny víc papírování a dostane se k farmářům, kteří to potřebovali nejvíc."],["Vést dodatečné záchranné prostředky přes nadaci velkého sponzora","Sponzorova nadace si účtuje pěkný administrativní poplatek. Farmáři dostanou zbytek."],["Uspořádat fotoop na balíku sena a slíbit, že šeky jsou už na cestě","Balík sena vypadá na fotce skvěle. Šeky ve skutečnosti na cestě nejsou."]]},"p-economy-23":{"t":"Levná ocel","x":"Foundry Nation vyváží dotovanou ocel na americký trh za polovinu domácí ceny a tři další huti hrozí zavřením do zimy. „Je to podle obchodního práva nezákonné,“ říká ministr financí, „a zároveň to pro ně funguje přesně podle plánu.“","c":[["Okamžitě uvalit mimořádná cla na veškerý dovoz oceli","Domácí huti jásají. Každé odvětví, které ocel kupuje na stavbu věcí, potichu sténá."],["Podat formální obchodní stížnost správným mezinárodním kanálem","Je to správný postup. Trvá to také osmnáct měsíců, které žádná huť nemá."],["Vyhlásit úplné obchodní embargo na Foundry Nation kvůli oceli","Foundry Nation do hodiny oplatí odvetou na sóje. O tu vůbec nešlo."],["Uspořádat mítink v huti s helmou na hlavě pro kamery","Helma vypadá na fotce skvěle. Huť o dva měsíce později stejně zavře."]]},"p-economy-24":{"t":"Kupujte americké (platí podmínky)","x":"Nová iniciativa Kupujte americké odstartuje zítra s vlajkami, ohňostrojem a znělkou. Vedoucí kanceláře právě zjistila, že oficiální merch ze startu, čepice vietně, se vyrábí kompletně v zahraničí. „Zásilku ještě můžeme zrušit,“ říká. „Už je ale na lodi.“","c":[["Spustit to stejně a doufat, že si nikdo nevšimne štítků","Někdo si štítků všimne do hodiny. Znělka hraje dál."],["Odložit spuštění a zajistit merch z domácích zdrojů","Spuštění se opozdí o tři týdny, čepice vietně, štítky konečně pravdivé."],["Tvrdit, že zahraniční továrna je tajně vlastněná Američany","Není vlastněná Američany. Na mítinku se to tvrzení stejně opakuje."],["Přejmenovat čepice na „Skoro kupujte americké“","Čepice se vyprodají. Fráze se do večera stane nešťastným memem."]]},"p-money-1":{"t":"Nápadník s národním fondem","x":"Fond z „přátelské zálivové monarchie“ chce koupit golfová letoviska vaší rodiny za trojnásobek tržní ceny. Ministryně financí pořád opakuje „žádné podmínky navíc“, jako by ta fráze podmínky smazala. „Chtějí jen být vašimi partnery,“ říká a posouvá k vám smlouvu.","c":[["Podepsat, poslat hotovost","Peníze dorazí do pátku. Novináři začnou počítat vaše pískové bunkry."],["Vést je přes svěřenský fond bez vlivu","Nudné, legální, a nikdo vám za to neuspořádá přehlídku."],["Vzít si hotovost i práva na pojmenování","Osmnáctá jamka se teď jmenuje Jamka číslo jedna. Nenápadné."],["Trvat na tom, že budete zaplaceni ve zlatých cihlách","Celníci mají k té paletě spoustu otázek."]]},"p-money-2":{"t":"Spuštění memecoinu","x":"Váš syn chce spustit prezidentský memecoin, ještě než dokončíte ranní briefing. „Není to úplatek, tati, je to komunita,“ říká, už oblečený v mikině s logem. Velcí hráči se řadí, aby nakoupili za cenu, kterou už nikdy nikdo jiný neuvidí.","c":[["Nechat ho to spustit, vzít si podíl","Graf jde vertikálně nahoru, pak do strany, pak do skupinového chatu o žalobách."],["Zastavit to, než to začne","Syn se durdí. Etičtí právníci si poprvé po týdnech oddechnou."],["Spustit to a přidat sadu NFT k tomu","Někde si muž zastaví dům kvůli obrázku kresleného orla."],["Přejmenovat to po svém psovi","Psí mince do úterý předčí skutečnou měnu."]]},"p-money-3":{"t":"Výhodný pozemek","x":"Developer vám chce prodat pobřežní pozemek za dolar a pak potichu přeplánovat zbytek pobřeží kolem něj. Váš právník to nazývá „dárkem s výborným načasováním“. Ani nemrkne, když to řekne.","c":[["Koupit pozemek za dolar, schválit přeplánování","Teď vlastníte pláž. Také několik nových nepřátel na stavebním úřadě."],["Zaplatit plnou tržní cenu, vyloučit se z rozhodování","Developer je zmatený. Vaše jmění se sotva pohne."],["Vzít si pozemek a rozprodat celý poloostrov","Poloostrov se teď jmenuje resort. Slovo „pobřeží“ je teď historický pojem."],["Žádat platbu v pobřežních kabinách místo hotovosti","Vlastníte jedenáct kabin a nemáte tušení, co s nimi."]]},"p-money-4":{"t":"Hra na skořápky","x":"Vaše generální prokurátorka potřebuje podpis na formalizaci holdingové společnosti, která na papíře existuje jen kvůli přijímání zahraničních konzultačních poplatků. „Je to formalita,“ říká a poklepává na složku. „Ta formalita jen náhodou pere peníze.“","c":[["Podepsat bez čtení","Papíry zmizí v šuplíku úřadu ve státě, kam nikdo nejezdí."],["Odmítnout a složku skartovat","Prokurátorka vypadá zklamaně, ale dnes nic nezákonného nepodá."],["Podepsat a přidat další dvě skořápky","Teď máte firemní rodokmen, na který se žádný auditor nechce šplhat."],["Pojmenovat skořápkovou firmu po sobě, bez maskování","Nenápadnost nikdy nebyla vaše silná stránka."]]},"p-money-5":{"t":"Etický spis","x":"Úřad pro vládní etiku potichu otevřel spis k vašim financím. Vedoucí kanceláře se ptá, jestli byste to nechtěl „předběhnout“, než to udělá novinář. „Předběhnout“ v té větě dře jako mezek.","c":[["Zamést spis pod koberec, přeřadit vyšetřovatele","Vyšetřovatel je teď náměstek zástupce náměstka někde v mrazu."],["Zveřejnit své finance dobrovolně","Čísla jsou nudná. Nudné je, výjimečně, vítězství."],["Zamést spis pod koberec a místo toho prověřit novináře","Novinářovy daně jsou najednou pro finanční úřad velmi zajímavé."],["Přejmenovat spis na performativní umění","Galerie v Berlíně nabízí vystavit vaše bankovní výpisy."]]},"p-money-6":{"t":"Honorář za přednášku","x":"Obchodní sdružení vám chce zaplatit čtyři sta tisíc dolarů za dvacetiminutovou „hlavní řeč“ týden poté, co podepíšete jejich oblíbenou daňovou výjimku. Vedoucí kanceláře trvá na tom, že „tak to na okruhu prostě chodí“.","c":[["Vzít honorář, přednést řeč","Dvacet minut potlesku, čtyři sta tisíc dolarů, žádné poznámky."],["Odmítnout honorář, podepsat zákon na základě jeho merit","Sdružení je zmatené. Zmatek se, ukazuje se, dá mít zdarma."],["Vzít honorář a přidat knižní smlouvu","Kniha se jmenuje Vítězství a skládá se hlavně z poděkování."],["Žádat, ať je honorář zaplacen formou publicity","Publicita, ukazuje se, není zákonné platidlo, ale i tak si ji vezmete."]]},"p-money-7":{"t":"Licence na věž","x":"Zahraniční developer chce nalepit vaše jméno na napůl postavenou luxusní věž v zemi s pochybnou historií lidských práv. Váš tamní velvyslanec to nazývá „brandingovou příležitostí s výbornou marží“. O zřícení lešení se nezmiňuje.","c":[["Poskytnout licenci na jméno, vybrat poplatek","Věž je do čtvrtka přejmenována. Lešení zůstává nevyřešené."],["Licenci úplně odmítnout","Developer si najde jiné jméno k nalepení. Nějak je to v pořádku."],["Poskytnout licenci a přidat hotelové křídlo","Teď jsou tam dvě budovy s vaším jménem a jeden funkční výtah."],["Trvat na tom, že věž bude mít tvar vaší tváře","Řízení letového provozu žádá o přehodnocení nosu."]]},"p-money-8":{"t":"Skulina v zákoně","x":"Váš tým na financích navrhl daňové ustanovení tak specifické, že se v praxi vztahuje na jediný rodinný trust v Americe. Váš. „Zní to obecně,“ trvá ministryně. „Vztahuje se to na jakoukoli kvalifikující víceoborovou pohostinskou entitu s přesně vašimi vlastnostmi.“","c":[["Propašovat to do zákona, který musí projít","Nikdo si nepřečte stránku čtyři sta dvanáct. Vy si ji přečtete třikrát."],["Ustanovení sám škrtnout","Váš účetní tiše pláče ve vedlejší místnosti."],["Propašovat to a zpětně to rozšířit","Šek s vratkou dorazí dřív, než kdokoli dočte zákon."],["Pojmenovat skulinu po fiktivním voliči","Muž jménem Gary Skulina neexistuje, a přesto tu jsme."]]},"p-money-9":{"t":"Rodinná zakázka","x":"Startup vašeho syna, který nikdy nevydal žádný produkt, právě vyhrál devítimístnou federální zakázku na „modernizaci“ něčeho, co nikdo pořádně nedovede definovat. Novináři začali používat slovo „nepotismus“, jako by to byla nová informace.","c":[["Nechat zakázku platit","Startup najme recepční. Jistý druh pokroku."],["Zrušit ji a otevřít skutečné výběrové řízení","Syn s vámi týden nemluví. Pravděpodobně to stojí za to."],["Nechat ji platit a přidat druhou zakázku","Startup má teď dvě zakázky a pořád žádný produkt."],["Nechat ho se přerebranovat na neziskovku","Neziskovky si, jak se ukazuje, pořád mohou koupit pěknou loď."]]},"p-money-10":{"t":"Darovaná jachta","x":"Lodní magnát vám „daroval“ dvěstěstopovou jachtu a trvá na tom, že je to „jen půjčka, na neurčito, navždy“. Vedoucí kanceláře ji v podkladech k briefingu už přejmenovala, aby se vyhnula vyslovení slova „dar“.","c":[["Přijmout jachtu, potichu ji zakotvit","Jachta je teď technicky muzeum, což technicky není úplatek."],["Odmítnout ji, nabídku nahlásit","Magnát je ohromený. Odmítání darů je zjevně vzácnost."],["Přijmout ji a odpovídající helikoptéru k tomu","Na klimatické summity teď přiletíte helikoptérou. Tým pro image dá výpověď."],["Přejmenovat jachtu na „Prezidentský čas“","„Prezidentský čas“ je za týden spatřen u tří různých pobřeží."]]},"p-money-11":{"t":"Vděčná obálka","x":"Muž, kterého jste na jaře omilostnili, nechal u vašeho osobního asistenta tašku „pro nadaci“. Nikdo se nezeptal pro kterou. Váš právník jemně naznačuje, že tašky hotovosti jsou „přinejmenším otázka image“.","c":[["Nechat si to, mlčet","Taška zmizí v trezoru, který se neobjeví v žádném inventáři."],["Vrátit ji a nahlásit toho, kdo o milost žádal","Muž je zuřivý. Právník, výjimečně, vypadá úlevně."],["Nechat si to a zeptat se, jestli přijde víc","Přijde skutečně víc. A pravidelně, jak se ukáže."],["Darovat to nadaci, kterou jste si právě vymyslel","Nadace má jediného zapsaného zaměstnance, a to jste vy."]]},"p-money-12":{"t":"Blokové rezervace","x":"Zahraniční delegace si právě zarezervovala celý váš hotel na státní návštěvu, za noční sazbu, kterou vlastní personál nazývá „ambiciózní“. Váš poradce pro vnitřní bezpečnost věcně poznamenává, že Ústava k tomuto téma má názor.","c":[["Přijmout rezervaci za plnou sazbu","Lobby voní čerstvými penězi a mírným porušením ústavy."],["Přesměrovat je do konkurenčního hotelu","Váš generální manažer je zdrcený. Ústava méně."],["Přijmout to a nabídnout jim navíc prezidentský apartmán","Apartmán stojí víc než dům většiny lidí. Týdně."],["Pokoj poskytnout zdarma a účtovat jim minibar","Účet za minibar sám o sobě financuje malé velvyslanectví."]]},"p-money-13":{"t":"Národní kryptorezerva","x":"Ministryně financí navrhuje, aby vláda držela „strategickou rezervu“ mince, které náhodou vlastníte velké množství vy osobně. „Je to progresivní krok,“ říká. „Je to taky vaše mince,“ říkáte. Nesouhlasí.","c":[["Oznámit rezervu","Vaše podíly ztrojnásobí hodnotu ve chvíli, kdy tisková zpráva vyjde."],["Nápad úplně zrušit","Trh zívne. Vaše portfolio zívá s ním."],["Oznámit to a nejdřív si přikoupit víc","Načasování, jak se říká, je vše, a to vaše bylo bezchybné."],["Přejmenovat rezervu po budově ministerstva financí","FortKnoxCoin trenduje šest hodin, pak z právních důvodů potichu skončí."]]},"p-money-14":{"t":"Předstih","x":"Váš zpravodajský briefér skoro jistě omylem prozradil detail o přezkumu fúze, který ještě nebyl oznámen. Váš makléř je jednu esemesku od přesné vědomosti, co koupit dřív, než to udělá trh.","c":[["Poslat tu esemesku","Obchod projde. Algoritmus SEC bohužel taky vnímá vzorce."],["Zprávu smazat, nikoho neinformovat","Nic se nestane, což je přesně smyslem toho cvičení."],["Poslat ji a zapojit dva sponzory","Tři portfolia přes noc rozkvetou. Jeden analytik klade příliš mnoho otázek."],["Obchodovat opačným směrem jako klamnou stopu","Klamná stopa prodělá peníze, což je nějak nejpřesvědčivější část."]]},"p-money-15":{"t":"Charitativní gala","x":"Nadace vaší dcery vybrala na včerejším gala jedenáct milionů dolarů. Záznamy ukazují, že dva miliony šly do stipendijního fondu a devět milionů do „provozu“, kategorie, která se skládá hlavně ze samotného gala.","c":[["Nechat účetnictví tak, jak bylo podáno","Stipendijní fond dostane pěknou tabulku. Zbytek dostane ještě lepší párty."],["Nařídit plný nezávislý audit","Audit je nemilosrdný. Tabulka naštěstí přežije."],["Přidat do správní rady další dva příbuzné","Nadace teď zaměstnává víc rodiny než skutečného personálu."],["Přejmenovat ji na Fond prezidentské excelence","Excelence, podle výkazů, stojí docela dost na správu."]]},"p-money-16":{"t":"Aukce členství","x":"Váš golfový klub potichu draží členství lobbistům za absurdní přirážky se šeptaným příslibem „přístupu“. Vedoucí kanceláře žádá váš souhlas s ceníkem před pondělními tee-timy.","c":[["Schválit ceník","Pořadník se zaplní muži, kteří nikdy nedohráli pod devadesát ran."],["Omezit poplatky za členství na tržní úroveň","Klub je náhle mnohem méně ziskový a mnohem méně zajímavý."],["Schválit to a přidat úroveň jen pro lobbisty","Nová úroveň zahrnuje skříňku a zjevně i vaše telefonní číslo."],["Prodávat členství formou tomboly místo toho","Penzionovaná učitelka vyhraje skříňku vedle vojenského dodavatele."]]},"p-press-13":{"t":"Čtyřicet vteřin, které nechtějí zemřít","x":"Čtyřicetivteřinový klip, na kterém třemi různými způsoby v jedné větě špatně vyslovujete slovo „infrastruktura“, má sto milionů zhlédnutí a stále přibývá.","c":[["Trvat na tom, že výslovnost je regionální a správná","Lingvisté zdvořile, ale zeširoka nesouhlasí, v několika komentářích."],["Udělat si z toho vtip na příští tiskovce","Klip dostává druhý život: vy se mu smějete. Mírně sympatické."],["Zakázat slovo „infrastruktura“ v oficiálních prohlášeních","Zákony teď popisují silnice jako „ty dlouhé rovné tvrdé věci“."],["Vydat remixový singl toho klipu","Umístí se v žebříčcích. Jste teď, technicky vzato, hudební umělec."]]},"p-press-14":{"t":"Titulek, který nepřestává počítat","x":"Zpravodajská stanice teď vysílá živý, trvalý spodní pruh počítající vaše nepravdivá tvrzení. Dnes ráno, během reportáže o počasí, překročil čtyři tisíce.","c":[["Nazvat počítadlo samotné čtyřtisícátou lží","Metalži jsou zjevně pořád lži. Počítadlo je to jedno."],["Začít být opravdu opatrnější se svými tvrzeními","Tempo růstu počítadla se zpomaluje. Někde se nudou rozplakal fact-checker."],["Žádat, aby stanice nainstalovala stejné počítadlo i pro vaše soupeře","Jejich počítadlo začíná na nule a zůstává otravně nízké."],["Nechat přesné číslo počítadla prohlásit za utajované","Počítadlo teď ukazuje jen UTAJENO, což je nějak ještě horší."]]},"p-press-15":{"t":"Váš nekrolog už je napsaný","x":"Redakce jednoho velkého deníku píše nekrology pro úřadující vůdce dopředu, pro případ náhlé události. Ten váš unikl. Poradci poznamenávají, že je „překvapivě férový“.","c":[["Žádat propuštění autora nekrologu za morbiditu","Každý autor nekrologů v zemi teď pracuje z utajeného místa."],["Požádat o revizi jen kvůli faktické přesnosti","Opravíte si rodiště. Zbytek zůstává beze změny."],["Vydat vlastní, mnohem lichotivější nekrolog předem","Teď kolují dva nekrology. Ani jeden neuklidňuje."],["Zúčastnit se vlastního fingovaného pohřbu kvůli publicitě","Účast je hojná. Smuteční řeči jsou trefné."]]},"p-press-16":{"t":"Mikrofon byl zapnutý, a jak","x":"Mezi segmenty zachytí nezavřený mikrofon, jak říkáte asistentovi, že navštěvující delegace „smrdí jako auto z půjčovny“. Delegace písemně žádá vysvětlení.","c":[["Tvrdit, že to byl kompliment v jiném jazyce","Takový jazyk neexistuje. Tvrzení to vůbec nezpomalí."],["Zavolat velvyslanci a osobně se omluvit","Velvyslanec omluvu velkoryse přijme a nikdy vám to úplně nezapomene."],["Popírat, že by se kdy nějaký mikrofon k vám přiblížil","Zvukaři po celé zemi se dávají na těžké pití."],["Poslat delegaci bednu osvěžovačů vzduchu jako dárek","Delegace si není jistá, jestli je to omluva, nebo eskalace."]]},"p-press-17":{"t":"Válka o akreditace","x":"Zrušili jste akreditaci novináři za to, že kladl „příliš mnoho doplňujících otázek“. Soudce z toho, co se týče prvního dodatku, evidentně nadšený není.","c":[["Pro jistotu zrušit akreditaci ještě pěti dalším","Tisková místnost je teď hlavně prázdné židle a jeden velmi tvrdohlavý stážista."],["Vrátit akreditaci a potichu se omluvit","Novinářka to přijme. Její doplňující otázky jsou pak ze vzdoru ještě ostřejší."],["Odvolat se proti soudcovu rozhodnutí až na nejvyšší instanci","Prohráváte na každé úrovni, což se nějak samo stává novinovou senzací."],["Vytvořit novou kategorii akreditací s názvem „Opravdu dobří novináři“","Nikdo se nepřihlásí. Zůstáváte jediným členem této kategorie."]]},"p-press-18":{"t":"Váš soupeř má názory, písemně, s poznámkami pod čarou","x":"Váš hlavní politický soupeř publikuje ostrý komentář nazvaný „Skromný návrh na kompetenci“. Má poznámky pod čarou. Několik poradců soukromě přiznává, že je dobře argumentovaný.","c":[["Napsat zuřivou odpověď a nazvat ho zrádcem","Odpověď nemá jedinou poznámku pod čarou a pár překlepů."],["Věcně reagovat v klidném veřejném prohlášení","Uznáte jeden bod. Je to jako operace bez anestezie."],["Žádat, aby noviny denně tiskly stejně dlouhou odpověď","Noviny souhlasí a pak váš text zahrabou vedle křížovky."],["Vyzvat soupeře na veřejnou soutěž v psaní poznámek pod čarou","Nikdo nechápe pravidla. Všichni se přesto dívají."]]},"p-press-19":{"t":"Spis, o který nikdo nežádal","x":"Kariérní státní úředník podává formální oznámení, že jste Situační místnost použil ke sledování finále telenovely. Oznámení obsahuje i hodnocení: „poutavá televize, sporná státnická moudrost“.","c":[["Zdiskreditovat oznamovatele jako zahořklého fanouška konkurenčního seriálu","Sledovanost konkurenčního seriálu vzroste. Té vaší telenovely méně."],["Plně spolupracovat s prošetřením","Šetření vás zprošťuje viny a potvrzuje, že jste finále skutečně viděl."],["Prohlásit celé oznámení za věc národní bezpečnosti","Kongres teď chce vědět, co je na telenovele tak tajného."],["Pozvat oznamovatele, aby se s vámi podíval na příští finále","Přijme pozvání. Prý je to milý večer."]]},"p-press-20":{"t":"Každý má prý svou cenu","x":"Asistent hlásí, že středně známý novinář proslulý tvrdým zpravodajstvím je „koupitelný“ za místo blízko vlády a pěknou kancelář. Právně vzato je to krajně nevhodné.","c":[["Udělat to potichu a v případě dotazů navždy vše popírat","Přijme místo. Bývalí kolegové mu, ani vám, už nikdy úplně nedůvěřují."],["Odmítnout a nabídku nahlásit jako nevhodnou","Nic se nestane, kromě toho, že vaše integrita je, na chvíli, neporušená."],["Nabídnout to místo veřejně jen abyste viděl, kdo se chytí","Přihlásí se čtrnáct novinářů. Žádný z nich nebyl ten tvrdý."],["Přijmout ho a hned přeřadit na počasí","Jeho předpovědi teď procházejí přísnější kontrolou faktů než celá vaše vláda."]]},"p-press-21":{"t":"Parodie, co nechce skončit","x":"Komikova imitace vás, samý přimhouřený pohled a mumlání, je teď rozpoznatelnější než vy sám. Malé děti ji prý dělají lépe než komik.","c":[["Žalovat komika za krádež vaší osobnosti","Právníci poznamenávají, že osobnost se přesně vzato ukrást nedá. Žaloba je zamítnuta s viditelným pobavením."],["Na veřejné akci zahrát imitaci sám na sebe, s nadhledem","Sklidí největší smích týdne, na váš vlastní účet, což je vzácné a cenné."],["Zakázat komikovi vstup na všechny budoucí tiskové akce","Komik pak dělá imitaci jen zvenku za zábranami, hlasitěji."],["Najmout komika jako svého nového spisovatele projevů","Vaše projevy jsou najednou mnohem vtipnější a citelně méně srozumitelné."]]},"p-press-22":{"t":"Internet vyhlašuje soutěž o nejlepší popisek","x":"Fotka, na které mžouráte na desky s nápisem NALÉHAVÉ, držíte je vzhůru nohama, spustila celostátní soutěž o popisek. Aktuálně vede: „Muž zjišťuje, že gravitace platí i na papír“.","c":[["Žádat, aby platforma smazala každý příspěvek","Samotné smazání vyhrává soutěž o popisek pro svou ironii."],["Vybrat si oblíbený příspěvek a sám ho sdílet","Na jedno odpoledne jste v obraze. Sklízí to překvapivě dobrý ohlas."],["Žalovat platformu za emoční újmu","Soudkyně by se prý sama nejraději do soutěže přihlásila."],["Vyhlásit peněžní odměnu za vítězný popisek","Počet příspěvků vzroste o čtyři sta procent. Kvalita ne."]]},"p-war-1":{"t":"Signál z Volkovie","x":"Radarová stanice u hranice v úterý večer něco zachytila. Výbuch, test rakety, nebo ohňostroj k narozeninám generála Oseie, nikdo si není jistý. Náčelníci štábů chtějí rozhodnutí, než jim vychladne káva.","c":[["Nazvat to válečným aktem a mobilizovat flotilu","Flotila vyplouvá. Důkazy nikoli."],["Nařídit skutečné vyšetření, než cokoli oznámíte","Nic se nestalo. Všichni jsou naštvaní, že to trvalo tak dlouho zjistit."],["Uniknout informaci, že šlo jistojistě o útok, fakta se doplní později","Únik se stává příběhem. Příběh se stává válkou."],["Svalit to na zbloudilý meteorologický balon a žádat, aby se národu omluvil úřad ČHMÚ","Úřad se omluví. Meteorologové si potichu aktualizují životopisy."]]},"p-war-2":{"t":"Generál chce přehlídku","x":"Generál Halbrook chce tanky na hlavní třídě, „aby svět připomněl, že tanky ještě máme“. Ministerstvo obrany odhaduje, že přehlídka bude dražší než několik malých válek.","c":[["Schválit celou přehlídku, tanky a vše ostatní","Tanky dorazí. Stejně tak účet za výtluky."],["Nařídit místo toho jen skromný přelet, ušetřit peníze","Proletí tři letadla. Nikdo netleská."],["Přehlídku zdvojnásobit, přidat raketu ve tvaru vaší tváře","Vůz s raketou zabodoval přesně u jedné cílové skupiny: u vás."],["Nechat generála Halbrooka jet na koni místo v tanku","Kůň krade titulky. Generál Halbrook žádá pro koně povýšení."]]},"p-war-3":{"t":"Dron čeká","x":"Dron má na mušce cíl někde poblíž hranice Osei-Volkov. Rozvědka je „docela přesvědčená“, že jde o konvoj se zbraněmi, a „o něco méně přesvědčená“, že nejde o svatbu.","c":[["Dát rozkaz, lepší to jistit","Konvoj je zničen. Prý i dort."],["Počkat se střelbou, dokud si rozvědka nebude jistá","Konvoj se ukáže jako svatba. Nevěsta posílá ostře formulovaný dopis."],["Udeřit hned a udeřit znovu pro jistotu","Dva útoky, jeden konvoj, žádné zbraně nakonec nenalezeny."],["Rozhodnutí přenechat hodu mincí, vysílanému živě","Mince padne na hlavu. Váleční etici hromadně podávají výpověď."]]},"p-war-4":{"t":"Úterní puč generála Oseie","x":"Generál Osei obsadil palác ve spřátelené zemi, odvolává se na „vibrace“ a přeje si být oslovován Nejvyšší velitel. Washington musí rozhodnout, jestli ho uzná.","c":[["Ihned Oseie uznat, působí schopně","Osei posílá dárkový koš s ovocem. Demokracie posílá své politování."],["Odsoudit puč, podpořit svrženou vládu","Prohlášení je vydáno. Oseie to nechává klidným a upřímně stále u moci."],["Potichu Oseie vyzbrojit výměnou za přístup k základně","Získáte základnu. Osei získá soukromou armádu. Dějiny získají poznámku pod čarou."],["Pozvat Oseie do Camp Davidu probrat to při golfu","Osei podvádí v golfu a vy se oba nějak shodnete, že to je v pořádku."]]},"p-war-5":{"t":"Šest turistů a jedna stížnost","x":"Šest amerických turistů zajala v horách milice, která tvrdí, že jí osobně dlužíte omluvu za něco, co váš dědeček možná řekl v roce 1961.","c":[["Poslat speciální jednotky, žádná vyjednávání","Turisté jsou zachráněni. Dvě kozy nikoli."],["Tiše vyjednávat přes zadní kanály","Turisté se vrátí domů. Nikdo neuvidí ty skvělé záběry ze záchrany."],["Veřejně vyhrožovat celé zemi milice","Milice se zakope. Velvyslanec té země si vyhrabe právníka."],["Omluvit se jejich jménem za cokoli, co dědeček řekl","Ani oni nevědí, co řekl. Omluva se přesto vysílá."]]},"p-war-6":{"t":"Nejvyšší vůdce chce koupit stíhačky","x":"Nejvyšší vůdce země pod šesti různými sankčními režimy chce koupit stíhačky, hotově předem, žádné otázky, „na obranné pozorování ptáků“.","c":[["Schválit prodej, hotovost je hotovost","Stíhačky odlétají. Tvrzení o pozorování ptáků neobstojí ani týden."],["Zablokovat prodej a předat věc sankčnímu úřadu","Prodej je zablokován. Nejvyšší vůdce najde jiného dodavatele do čtvrtka."],["Prodat stíhačky a přidat výcvikový balíček","Výcvikový balíček obsahuje věci, které nikdo nechtěl mít písemně."],["Prodat mu vyřazené dvouplošníky a nazvat to slevou","Nejvyšší vůdce zuří. Dvouplošníky jsou, technicky vzato, dodány."]]},"p-war-7":{"t":"Výstřely u plotu","x":"Vojáci na obou stranách sporné hranice si přes noc vyměnili palbu kvůli něčemu, co zpráva popisuje jen jako „nedorozumění kolem kozy“.","c":[["Posílit hranici o tři další divize","Hranice je zajištěna. Osud kozy zůstává neznámý."],["Otevřít horkou linku s druhou stranou k uklidnění situace","Linka funguje. Obě strany se shodnou, že to začala koza."],["Nařídit symbolickou demonstraci síly, tanky k plotu","Tanky dorazí. Koza, nerušeně, se dál pase mezi nimi."],["Nabídnout se, že spor o kozu osobně zprostředkujete","Zprostředkujete. Koza dostane společnou péči."]]},"p-war-8":{"t":"Síť zablikala","x":"Polovina elektrické sítě ve třech státech byla jedenáct minut ve tmě. Kybernetická bezpečnost tvrdí, že to může být Volkovia, může to být teenager ve sklepě, může to být obojí.","c":[["Veřejně obvinit Volkovii a připravit odvetné údery","Volkovia vše popírá. Teenager drží nízký profil."],["Zahájit forenzní vyšetřování, než kohokoli obviníte","Teenager je nalezen. Dostane zaracha, ne vydání."],["Odvetit vlastním kybernetickým útokem, bez potřeby důkazů","Protiúder zasáhne špatnou síť. V Ohiu."],["Oznámit, že výpadek byl od začátku plánované cvičení","Nikdo tomu nevěří. Lež přesto nějak působí uklidňujícím dojmem."]]},"p-war-9":{"t":"Volkov testuje raketu, špatně","x":"Prezident Volkov testoval novou raketu, která podle satelitních záběrů zavrávorala, dvakrát se zatočila a dopadla na pšeničné pole ve vlastní zemi. Státní média to nazývají triumfem.","c":[["Odpovědět ještě větším testem, ten samý týden","Vaše raketa se taky zavrtí. Nikdo o tom neinformuje."],["Tiše selhání zaznamenat a nic nedělat","Výnos pšenice na Volkovově poli stoupá o devět procent díky hnojivu."],["Volkova veřejně zesměšnit a hrozit preventivním úderem","Ponížený Volkov slibuje druhý test. Ještě větší pšeničné pole."],["Poslat Volkovovi kondolenční kartu kvůli pšeničnému poli","Volkov není pobavený. Karta získá víc pozornosti než samotná raketa."]]},"p-war-10":{"t":"Mírová dohoda, kterou nikdo nechtěl pokazit","x":"Vaši vyjednavači potichu dokončili mírovou dohodu, která ukončuje desetiletý konflikt. Bohužel je to nudná televize.","c":[["Oznámit, že živě v éteru přidáte „tvrdší“ podmínky, ať se dohoda sesype","Dohoda se na živém vysílání zhroutí. Sledovanost je, uznejme, silná."],["Nechat vyjednavače dohodu potichu podepsat a slavit výhru","Válka končí. Přenos sleduje devět diváků, všichni s úlevou."],["Podpis zadržet, dokud tam nepřidají vaše jméno","Dohoda je po vás přejmenována. Druhá strana všechno znovu zvažuje."],["Proměnit podpisový ceremoniál v soutěžní show","Rebelové vyhrají topinkovač. Mír, nějak, ze vzdoru vydrží."]]},"p-war-11":{"t":"Přeběhlík žádá o azyl","x":"Vysoký úředník z vlády Nejvyššího vůdce se objevil na velvyslanectví s flash diskem a žádostí o pěkný dům na Floridě.","c":[["Udělit azyl a ihned ho předvést v televizi","Nejvyšší vůdce zuří. Přeběhlík si tu pozornost náramně užívá."],["Nejdřív ho v klidu vyslechnout řádnými kanály","Flash disk obsahuje hlavně dovolenkové fotky a jednu užitečnou mapu."],["Prozradit jeho totožnost, aby to zatlačilo na jeho starou vládu","Tlak funguje. Stejně tak skoro i pokus o atentát."],["Vyměnit ho za dvě pandy, bez otázek","Pandy dorazí. Přeběhlík je hluboce uražen tímto směnným kurzem."]]},"p-war-12":{"t":"Lodě v úžině","x":"Volkovský torpédoborec a americká letadlová skupina jsou v úžině dost blízko na to, aby si vyměnily ostře formulované vlajkové signály. Ani jedna strana nechce mrknout první.","c":[["Nařídit letadlové skupině držet pozici, se zbraněmi připravenými","Nikdo nemrkne. Všem alarmujícím tempem klesá stav paliva."],["Přesměrovat letadlovou skupinu, aby se konfrontaci vyhnula","Lodě proplují bezpečně. Admirál je potichu zklamaný."],["Nařídit ostrostřeleckou přehlídku přímo tam, pro zdůraznění","Přehlídka je velmi hlasitá a velmi blízko. Volkov posílá formální stížnost, ještě hlasitější."],["Vyzvat volkovského kapitána na partii šachů po rádiu","Vyhrajete. Kapitán tvrdí, že mu dámu zablokoval radar."]]},"p-war-13":{"t":"Povstání potřebuje kapesné","x":"Povstalecká koalice bojující proti vládě Nejvyššího vůdce chce zbraně, hotovost a „morální podporu“, v tomto pořadí.","c":[["Financovat je naplno, tajně, bez dohledu","Povstání postupuje. Stejně tak papírová stopa."],["Nabídnout jen humanitární pomoc, žádné zbraně","Povstalci jsou vděční za deky a nepříliš nadšení strategií."],["Financovat je i obě jejich rivalské povstalecké frakce, pro jistotu","Tři frakce teď tráví víc času bojem mezi sebou než proti vládě."],["Financovat je pomocí televizního sbírkového maratonu","Maraton vybere miliony. Celebritní moderátor se teď prohlašuje za experta na zahraniční politiku."]]},"p-war-14":{"t":"Skromný návrh ze sklepa","x":"Poradce, velmi potichu, se zavřenými dveřmi, navrhuje, že by se dal zařídit „menší incident“, který by ospravedlnil válku, kterou už stejně všichni chtějí.","c":[["Schválit to, s odepíratelností, mimo záznam","Incident se stane. Nakonec i vyšetřování."],["Poradce vyhodit a návrh nahlásit","Poradce je pryč. Válka, prozatím, čeká na skutečný důvod."],["Schválit to a rozšířit plán na dva incidenty, pro jistotu","Redundance dosažena. Stejně tak nakonec i federální vyšetřování."],["Nafingovat incident pomocí herců a pronajatého tanku","Herci jsou přesvědčiví. Půjčovna chce tank zpátky."]]},"p-war-15":{"t":"Summit, který byste raději vynechal","x":"Výroční summit aliance je tento víkend. Účast znamená společné fotky a sdílená komuniké. Vynechání znamená, že o vás všichni mluví stejně, jen míň zdvořile.","c":[["Vynechat ho a uspořádat místo toho shromáždění, větší dav","Aliance si toho všimne. Dav na shromáždění je to jedno."],["Zúčastnit se, podepsat komuniké, usmát se na fotku","Fotka je nevýrazná. Aliance drží, sotva si vás všimne."],["Zúčastnit se a odmítnout cokoli podepsat, z principu, nespecifikovaného","Fotka je trapná. Princip nikdy nikdo nepojmenuje."],["Poslat na vaše místo lepenkovou figurínu","S figurínou zachází diplomacie s větším respektem, než se čekalo."]]},"p-war-16":{"t":"Vesmírné síly chtějí vlajku na Měsíci","x":"Nově zřízené Vesmírné síly chtějí na povrch Měsíce zapíchnout vlajku s vaší tváří, „kvůli odstrašení“.","c":[["Financovat misi naplno, start příští čtvrtletí","Vlajka dosáhne oběžné dráhy. Tvář je podle NASA „rozpoznatelná jen z nízké oběžné dráhy“."],["Přesměrovat rozpočet na skutečnou výzkumnou misi","Výzkumná mise tiše odstartuje. Vaši tvář nikde nikdo nevidí."],["Přidat i laser, odstrašení potřebuje laser","Laser funguje bez problémů. Sedmnáct zemí přesto podá formální protest."],["Financovat misi s vlajkou crowdfundingem","Crowdfunding se povede. Přispěvatelé dostanou certifikát a mírnou lítost."]]},"p-war-17":{"t":"Práva na pojmenování","x":"Váš tiskový tým navrhuje probíhající zahraniční konflikt oficiálně přejmenovat po vás, „kvůli odkazu“.","c":[["Přejmenování ihned schválit, s plnou ceremonií","Válka teď nese vaše jméno. Stejně tak každá zpráva o obětech."],["Odmítnout, války by neměly nést vaše jméno","Válka si podrží staré, nudné jméno. Dějiny zůstávají stejně nedotčené."],["Přejmenovat ji a nechat razit pamětní minci","Mince je vyražena. Válka pokračuje, teď s merchem."],["Nechat o jméně hlasovat veřejnost","Veřejnost hlasuje pro něco netisknutelného. Potichu se to zamítne."]]},"p-war-18":{"t":"Ten velmi velký tlačítko","x":"Asistenti nainstalovali na váš stůl velké červené tlačítko, „kvůli morálce“, jak tvrdí, ačkoli je napojené na něco, co dřív vyžadovalo tři klíče a generálův podpis.","c":[["Vyhrožovat, že ho v televizi stisknete, ať se uvidí, co se stane","Nikdo nic nestiskne. Všem se spí trochu hůř."],["Nechat tlačítko odstranit a obnovit původní protokol","Tlačítko je pryč. Stůl vypadá podivně prázdný."],["Stisknout ho napůl, „jen na zkoušku“, před novináři","Naštěstí bylo odpojené. Záběry nikoho neuklidňují."],["Nahradit ho tlačítkem, které jen objedná pizzu","Pizza dorazí. Morálka, proti všem očekáváním, opravdu stoupne."]]},"p-war-19":{"t":"Muž v moc pěkném obleku","x":"Soukromý vojenský dodavatel nabízí, že vyřeší „celou tu situaci s Volkovem“ za paušální poplatek, bez dohledu Kongresu, bez papírování, bez otázek.","c":[["Najmout dodavatele, hotově předem, potichu","Situace je vyřešena. Nikdo přesně neví jak."],["Odmítnout a věc předat ministerstvu obrany","Ministerstvo postupuje pomalu. Muž v obleku odejde jinam se svým podnikáním."],["Najmout dodavatele a dát mu ještě druhou, nesouvisející zakázku","Obě zakázky jsou vyřízeny. Ani jedna se neobjeví v žádném rozpočtu."],["Vyjednat mu nižší odměnu jeho vlastními taktikami","Respektuje váš um. Příště si taky zdvojnásobí sazbu."]]},"p-war-20":{"t":"Ostrov na prodej","x":"Malý tichomořský stát je ochotný prodat strategicky umístěný ostrov pro námořní základnu, pokud bude cena správná a papíry zůstanou vágní.","c":[["Koupit ho rovnou, oznámit novou základnu do pátku","Základna je postavena. Místní obyvatelé nejsou, jak se ukazuje, konzultováni."],["Vyjednat pronájem místo přímé koupě","Nájemní smlouva je podepsána. Všichni uznávají, že jde o tu nudnou správnou volbu."],["Koupit ho i tři sousední ostrovy, pro jistotu","Teď vlastníte čtyři ostrovy a rychle se zhoršující vztahy s celým regionem."],["Zkusit ho vyměnit za přebytečný trajekt z Guamu","Nabídka je odmítnuta. Kapitán trajektu si oddechne."]]},"p-war-21":{"t":"Ponorka přestala volat","x":"Americká ponorka poblíž volkovských vod zmeškala poslední dvě plánovaná hlášení. Může jít o poruchu spojení. Může jít o něco horšího. Nikdo to nechce vyslovit nahlas.","c":[["Mobilizovat flotilu a okamžitě žádat od Volkova odpovědi","Flotila se mobilizuje. Ponorka měla, jak se ukáže, jen mrtvou vysílačku."],["Potichu vyslat záchranné plavidlo a počkat","Ponorka se vynoří podle plánu o tři hodiny později. Tisk se to nedozví."],["Veřejně oznámit, že americká ponorka možná zmizela, pravděpodobně vyprovokována","Světové trhy panikaří šest hodin. Vysílačka byla, znovu, prostě mrtvá."],["Poslat ponorce ostře formulovaný fax","Ponorky nemají faxy. Toto se teď stává obecně známým faktem."]]},"p-war-22":{"t":"Generál nahlas odstupuje","x":"Generál Halbrook rezignoval na protest proti „směřování zahraniční politiky této vlády“ a dává o tom rozhovory, což je novinka.","c":[["Veřejně napadnout Halbrookovu povahu v televizi","Halbrook odpoví smlouvou na knihu. Smlouva odpoví prodejností."],["Rezignaci přijmout s grácií, popřát mu vše dobré","Halbrook odchází potichu. Novináři ho zklamaně shledávají také velkorysým."],["Ze vzteku ho připravit o penzi","Penze je pryč. Stejně tak jakákoli zbývající přízeň celého sboru důstojníků."],["Nabídnout Halbrookovi talk show, aby měl co dělat","Halbrook přijme. Jeho sledovanost, k vzteku, poráží tu vaši."]]},"p-street-1":{"t":"Tábor Ústava","x":"Protestující obsadili náměstí Svobody v centru Columbusu už šest dní, přejmenovali ho na Tábor Ústava a jmenovali čestným starostou mývala Steva. Steve má lepší preference než skutečný starosta.","c":[["Poslat tam zásahovku","Tábor je vyklizen do svítání. Steve je propuštěn bez obvinění, což je víc, než se dá říct o všech ostatních."],["Rozumný krok","Místo štítů pošlete přenosné toalety a příběh se najednou točí kolem vaší překvapivé slušnosti."],["Horší nápad","Náměstí necháte srovnat buldozery ve tři ráno. Tábor Ústava se o dva bloky dál znovu otevírá jako Tábor Ústava Dva."],["Rovnou náměstí odkoupit","Koupíte náměstí Svobody za jedenáct milionů dolarů a přejmenujete ho na Národní muzeum hraček. Návštěvnost zklamává."]]},"p-street-2":{"t":"Všichni jsou venku","x":"Dvanáct odborů vyhlašuje koordinovanou generální stávku. Hromadí se odpadky, vlaky stojí a barista z Toleda se přes noc stává lidovým hrdinou za odmítnutí uvařit vaší tiskové mluvčí ovesné latté.","c":[["Prohlásit stávku za nezákonnou","Organizátoři jsou zatčeni do večera. Odpadky zůstávají přesně tam, kde byly."],["Rozumný krok","Zahájíte vyjednávání a nabídnete skromné ústupky. Vlaky, neochotně, znovu jezdí."],["Přivézt autobusy se stávkokazy","Stávkokazi nemohou najít depo, pak se nemohou najít mezi sebou, pak jdou domů."],["Vyhlásit náhle celostátní svátek","Oznámíte Den uznání pracujících, s okamžitou platností, takže stávka teď vypadá, jako by si všichni prostě vzali volno."]]},"p-street-3":{"t":"Incident s bazénkem","x":"Záznam z tělové kamery, na kterém policista se značnou silou zabavuje dítěti nafukovací bazének za „blokování hydrantu“, má čtyřicet milionů zhlédnutí ještě před vaším ranním briefingem.","c":[["Postavit se za policistu","Kritiky nazvete změkčilými vůči zločinu. Bazének zůstává nekonečně dlouho v úschově důkazů."],["Rozumný krok","Nařídíte nezávislé prošetření a veřejnou omluvu. Dítě dostane bazének zpátky, lehce vyfouknutý."],["Povýšit policistu naživo v televizi","Ceremonie má hojnou účast, přesně toho publika, které jste pro obrázky nechtěl."],["Poslat dítěti podepsaný bazének","Pošlete podepsaný nafukovací bazének s lístkem „bez zášti“. Internet se neuklidní."]]},"p-street-4":{"t":"Shromáždění na vaši počest","x":"Milice nazvaná Minutemen Redux plánuje pochod s pochodněmi „na podporu prezidenta“, s maskáčovým oblečením, energetickými nápoji a nafukovacím hradem ve tvaru orla.","c":[["Nechat je pochodovat, bez omezení","Nafukovací orel uprostřed akce splaskne. Fotky z jeho pádu přežijí samotné shromáždění."],["Rozumný krok","Potichu je požádáte, ať to zruší, a poděkujete jim za podporu jinak. Většina uposlechne, s mumláním."],["Poslat oficiální čestnou stráž","Fotky vojáků vedle nadšenců v maskáčích běží ráno na každé titulní straně."],["Poslat podepsaný chladicí box energetických nápojů","Dar je vřele přijat. Několik účastníků tři dny nespí."]]},"p-street-5":{"t":"Generál padá","x":"Dav strhne sochu dávno zesnulého generála před starou soudní budovou, odtáhne ji čtyři bloky a hodí do fontány, kde teď vypadá, jako by plavala.","c":[["Zatknout každého na záznamu","Čtyřicet zatčení. Socha zůstává ve fontáně a plave si znak."],["Rozumný krok","Potichu souhlasíte, že socha může být přemístěna do muzea. Fontána je vypuštěna a vyčištěna."],["Nařídit ji postavit dvakrát větší","Nová socha je o půlnoci dovezena jeřábem pod ozbrojenou stráží. Do týdne je znovu stržena."],["Prohlásit fontánu za historickou plaveckou expozici","Turisté teď platí pět dolarů, aby viděli generála uprostřed kraulu. On nic nenamítá."]]},"p-street-6":{"t":"Volání po zákazu vycházení","x":"Starostka Delgado chce po třech nocích nepokojů celoměstský zákaz vycházení. Vaši poradci jsou rozdělení mezi „ano, zjevně“ a „přesně takhle vznikne mnohem větší protest“.","c":[["Zavést zákaz vycházení, tvrdě","Zákaz vydrží jednu noc, než deset tisíc lidí usoudí, že devátá hodina je jen doporučení."],["Rozumný krok","Zákaz odmítnete a necháte město, ať si poradí samo. Většinou se to podaří."],["Zákaz plus kontrolní stanoviště na každém bloku","Doprava se celoměstsky zastaví. Stejně tak i jakékoli sympatie k vám."],["Zákaz vycházení, ale jen pro holuby","Vyhláška o zákazu vycházení holubů je podle právníků naprosto nevymahatelná a hlavně vtip, který zabírá."]]},"p-street-7":{"t":"Doklady, prosím","x":"Noční razie cílí na nedokumentované pracovníky ve skladu zeleniny a zajmou i několik skutečných občanů, kteří si prostě zapomněli peněženku, včetně jednoho bývalého soudce.","c":[["Rozšířit razie","Bývalý soudce je propuštěn s omluvným dopisem. Sklad už nikdy neotevře."],["Rozumný krok","Razie pozastavíte do prošetření. Zelenina, bohužel, dál plánovaně shnívá."],["Provést razii i v soudní budově, pro jistotu","Několik soudců je čtyři hodiny zadrženo, než někdo zkontroluje jejich odznaky."],["Nabídnout soudci formální omluvný koš od státu","Koš obsahuje ovoce pocházející přímo z toho vyplundrovaného skladu."]]},"p-street-8":{"t":"Kleknout, nebo se postavit","x":"Půlka stadionu kleká při hymně na mistrovském zápase, zatímco druhá půlka bučí tak hlasitě, že je to slyšet v přenosu. Váš kancléř chce prohlášení ještě před poločasem.","c":[["Žádat, aby liga viníky potrestala","Liga odmítá s odkazem na smlouvu, kterou jste nečetl. Dohledáte si ji, je neprůstřelná."],["Rozumný krok","Neřeknete vůbec nic, což se ukáže jako nejméně mediálně zajímavá možnost ze všech."],["Vyhrožovat vysílacím právům ligy","Tři televizní sítě potichu zvažují přesun budoucích zápasů do zahraničí."],["Zúčastnit se příštího zápasu a ironicky si sám kleknout","Nikdo se neshodne, co vaše klečení znamenalo, včetně vás."]]},"p-street-9":{"t":"Karavana, která nebyla","x":"Kabelová televize hlásí „masivní karavanu“ blížící se k jižní hranici. Po bližším ohledání jde o mikrobus mládežnické skupiny z kostela na výletě, ale panika už je na vzestupu.","c":[["Okamžitě nasadit na hranici vojáky","Tři tisíce vojáků vítají kostelní mikrobus a velmi zmateného mládežnického faráře."],["Rozumný krok","Veřejně uvedete fakta na pravou míru. Panika splaskne, stejně jako celý mediální cyklus."],["Přesto vyhlásit formální hraniční mimořádný stav","Nouzový stav přežije mikrobus o několik měsíců."],["Pozvat mládežnickou skupinu do Bílého domu","Sedmnáct teenagerů prohlídne Růžovou zahradu. Dva z nich kladou překvapivě dobré otázky."]]},"p-street-10":{"t":"Kampus nechce ustoupit","x":"Studenti na třech velkých univerzitách obsazují budovy vedení a vydávají seznam požadavků, který kromě reformy školného obsahuje i „lepší svačiny v automatech“.","c":[["Poslat federální agenty na vyklizení kampusů","Okupace končí. Do semestru s ní končí i většina darů od absolventů."],["Rozumný krok","Necháte to na univerzitách a potichu poznamenáte, že požadavek na automaty má opravdu něco do sebe."],["Vyhrožovat odebráním veškerého federálního výzkumného financování","Několik děkanů zpanikaří po telefonu. Několik dalších volá, že už stejně rezignovali."],["Doplnit automaty sám","Svačiny jsou výborné. Ostatní požadavky zůstávají neřešeny."]]},"p-street-11":{"t":"Osmnáct kol vzteku","x":"Kamioňáci blokují dálnici ve třech státech na protest proti nové palivové dani, parkují, troubí a na krajnici grilují ohromné množství klobás.","c":[["Nařídit dálnici vyklidit silou","Odtahovky přijíždí odtahovat odtahovky. Klobásy jsou zabaveny jako důkaz."],["Rozumný krok","Palivovou daň pozastavíte do přezkoumání. Dálnice se do večera otevře, provoněná klobásami."],["Pověřit státní policii, ať zabaví soupravy","Zabavit čtyři sta kamionů vyžaduje odstavnou plochu, na které je momentálně čtyři sta kamionů."],["Poslat jako mírové gesto bednu hořčice","Kamioňáci hořčici přijmou a z principu zůstanou zaparkovaní dál."]]},"p-street-12":{"t":"Pomník sám sobě","x":"Chcete na National Mall dvě stě stop vysokou sochu sebe sama. Inženýři říkají, že je to konstrukčně možné. Všichni ostatní říkají, že je to hrozný nápad.","c":[["Urychlit výstavbu, ignorovat námitky","Socha vyroste podle plánu. Holubi si nárokují hlavu do týdne."],["Rozumný krok","Potichu nápad odložíte a necháte ho zemřít ve výboru, kam tyhle věci patří."],["Udělat ji tři sta stop vysokou, ze zlata","Zlaté obložení je odcizeno šrotovníky ještě před slavnostním přestřižením pásky."],["Postavit ji, ale nechat občany hlasovat o póze","Vítězná póza, zvolená veřejným hlasováním, je vy na losovi. Výstavba pokračuje."]]},"p-street-13":{"t":"Povolání Národní gardy","x":"Nepokoje ve čtyřech městech vedou vaše generály k doporučení plného povolání Národní gardy. Je to typ rozhodnutí, které skvěle vypadá na briefingu a hrozně na titulní straně.","c":[["Plné povolání, do všech čtyř měst","Nasadí se dvanáct tisíc vojáků. Fotky vojáků na hlavních třídách běží celý týden."],["Rozumný krok","Spolehnete se na místní policii a komunitní vůdce. Je to pomalejší, ale funguje to."],["Povolat gardu a zároveň zfederalizovat místní policii","Místní šéfové nesou převzetí pravomocí těžce. Dva rezignují veřejně a zdlouhavě, přímo před kamerou."],["Nasadit gardu, ale jen na úklid","Vojáci týden sbírají odpadky. Podivně to všechny uklidní."]]},"p-street-14":{"t":"Když protiprotest protestuje proti protiprotestu","x":"Shromáždění, které jste sám zorganizoval na svou podporu, přitáhne protiprotest, ten přitáhne proti-protiprotest, a teď si nikdo na místě nepamatuje, na které straně vlastně začal.","c":[["Poslat policii chránit jen vaše příznivce","Optika jednostranné ochrany přežije shromáždění o celé týdny v každém zpravodajském cyklu."],["Rozumný krok","Vyzvete ke klidu na všech stranách a myslíte to vážně, což naprosto všechny zmate."],["Poslat policii zatknout jen protiprotestující","Vazební příjem třídí lidi podle toho, jakou drželi ceduli, což prostě není zákonná kategorie."],["Shromáždění zrušit, svalit to na kolizi termínů","Všichni jdou domů zmatení, ale, důležité, nikdo se nepere."]]},"p-street-15":{"t":"Starostka Delgado říká ne","x":"Starostka Delgado veřejně odmítá vymáhat váš nejnovější pouliční příkaz, stojí na schodech soudní budovy a čte megafonem nahlas Ústavu velmi zaujatému davu.","c":[["Odvolat ji z funkce federálním nařízením","Odvolávací příkaz spustí soudní spor, který přežije celé vaše funkční období, možná i vás samotného."],["Rozumný krok","Příkaz potichu zrušíte, než abyste bojoval se starostkou vyzbrojenou megafonem a Ústavou."],["Odříznout jejímu městu veškeré federální financování","Silnice ve městě zůstávají neopravené. Preference starostky Delgado nikoli."],["Vyzvat ji na veřejnou debatu na schodech soudní budovy","Okamžitě souhlasí a přinese si kartičky s poznámkami. Vy jste si kartičky nepřinesl."]]},"p-street-16":{"t":"Žena s cedulí","x":"Jedna žena tiše stojící u trasy vaší kolony s ručně psanou cedulí se stává nejsdílenějším obrázkem měsíce, nějak virálnější než cokoli, co vyprodukoval váš tým.","c":[["Nechat ji z trasy odstranit","Odstranění jedné tiché ženy s cedulí jí zajistí zhruba čtyřicetkrát větší publikum, než měla původně."],["Rozumný krok","Cestou kolem ní zamáváte. Je to malé gesto a poněkud funguje."],["Nechat tým vyprodukovat konkurenční virální moment","Konkurenční moment je široce zesměšněn jako nastrojený, protože skutečně nastrojený byl."],["Pozvat ji na kávu","Přijme, cedulí se po celou dobu nevzdá, a stává se druhým nejsdílenějším obrázkem měsíce."]]},"p-street-17":{"t":"Pochod místních","x":"Odborový pochod se vine hlavním městem a žádá vyšší mzdy, lepší pracovní dobu a nevysvětlitelně také státní svátek na jarní rovnodennost.","c":[["Nařídit pochod rozehnat","Pochod se přeskupí o dva bloky dál, teď s novou stížností a větším davem."],["Rozumný krok","Setkáte se s odborovými vůdci a nabídnete skutečné ústupky. Svátek rovnodennosti zůstává na seznamu přání."],["Nařídit pochod rozehnat jízdní policií","Koně a pochodující se moc nesnesou. Ani záznam z toho nakonec nevyšel dobře."],["Udělit svátek rovnodennosti, nic víc","Zaměstnanci dostanou jarní svátek a žádné přidání. Výměnu si všimnou okamžitě."]]},"p-street-18":{"t":"Zatrub, pokud miluješ pořádek","x":"„Vlastenecká kolona“ pickupů a vlajek objíždí hlavní město už třetí den v kuse, blokuje dopravu na vaši podporu a čím dál víc i vám samotnému v cestě.","c":[["Nechat je policejně doprovázet donekonečna","Rozpočet na doprovod nabobtná. Kolona nejeví žádné známky konce ani odjezdu."],["Rozumný krok","Veřejně jim poděkujete a požádáte je, ať se vrátí domů. Většina to nakonec udělá."],["Nařídit koloně eskalovat směrem do centra","Zácpa v centru dosahuje nového osobního rekordu. Doručovatelé zuří, na kameru."],["Udělit koloně ceremoniální povolení k pochodu","Povolení dělá zácpu oficiální a nějak i legální."]]},"p-street-19":{"t":"Guvernérka Frostová říká rozhodně ne","x":"Guvernérka Frostová odmítá váš příkaz přijmout ve svém státě federální jednotky, odvolává se na svrchovanost státu, několik soudních precedentů a tón, který napovídá, že na tenhle spor čekala.","c":[["Nasadit jednotky navzdory jejím námitkám","Nasazení okamžitě spustí soudní spor a velmi citovatelnou tiskovou konferenci od Frostové."],["Rozumný krok","Ustoupíte a necháte to na státu. Frostová vám nečekaně veřejně poděkuje."],["Vyhrožovat odříznutím veškerého federálního financování jejímu státu","Frostová vaše vydírání veřejně v televizi zavolá. Bylo to, fakticky, hlavně blaf."],["Vyzvat Frostovou, ať to vyřeší při večeři se steakem","Večeře probíhá zdvořile. Otázka jednotek zůstává i po dezertu nevyřešena."]]},"p-street-20":{"t":"Sezení u bran","x":"Koalice duchovních usedne před palácovou bránu, na směny zpívá hymny a odmítá odejít, dokud se s nimi nesejdete kvůli bytovému zákonu, který jste měsíce ignoroval.","c":[["Nechat je odstranit silou","Záběry duchovních odnášených uprostřed hymnu jsou, taktikou, přesně tak zlé, jak to zní."],["Rozumný krok","Setkáte se s nimi do hodiny. Bytový zákon se konečně pohne z výboru."],["Nechat je zatknout za vniknutí na cizí pozemek","Kauci během chvíle složí konkurenční kongregace, čistě ze vzdoru vůči vaší vládě."],["Poslat jim skládací židle a limonádu","Sezení se stává citelně pohodlnějším a podstatně delším."]]},"p-street-21":{"t":"Popel na schodech","x":"Veterán pálí vlajku na schodech kapitolu na protest proti škrtům v dávkách, čímž vyvolá pobouření u někoho, potlesk u jiných a záplavu kamer od naprosto všech.","c":[["Tlačit na okamžité stíhání","Stíhání znovu otevírá desítky let starý spor o svobodu projevu, který nikdo tento týden nechtěl znovu otevírat."],["Rozumný krok","Veřejně obnovíte škrtnuté dávky a necháte právní otázku ležet. Funguje to."],["Prosazovat ústavní dodatek zakazující pálení vlajky","Snaha o dodatek uvázne ve výboru, jak se takovým snahám spolehlivě děje už desítky let."],["Poslat veteránovi náhradní vlajku, zabalenou jako dárek","Vlajku vděčně přijme a týden nato ji z principu znovu spálí."]]},"p-street-22":{"t":"Balada o Cooperu Vanceovi","x":"Folkový zpěvák Cooper Vance je zatčen za neautorizované provedení protestní písně před federální budovou a píseň kvůli tomu okamžitě ztrojnásobí popularitu.","c":[["Prosadit plné obvinění, dát příklad","Soud dá písni druhý refrén a Vanceovi smlouvu s nahrávací společností."],["Rozumný krok","Obvinění se potichu stáhne. Píseň, když už řekla své, podle plánu vypadne z žebříčků."],["Zakázat mu vystupovat kdekoli na federální půdě","Vance vystupuje z veslice těsně mimo federální jurisdikci, před velmi početným davem."],["Pozvat Coopera Vance, ať headlinuje vaše shromáždění","Přijme, a pak na vašem shromáždění zahraje přesně tu protestní píseň, slovo od slova."]]},"p-congress-1":{"t":"Zaujměte postoj (jakýkoli postoj)","x":"Předseda Sněmovny Grimsby potřebuje váš postoj k Zákonu o modernizaci zemědělství hodinu před hlasováním v plénu. Nečetl jste ho. Nikdo ho nečetl. Termínu to zjevně nevadí.","c":[["Prohlásit, že jste zákon napsal osobně, ručně, brkem","Tvrzení o brku špatně stárne, jakmile někdo najde pod textem font psacího stroje."],["Požádat o čtyřicet osm hodin, abyste to skutečně přečetl","Kongres respektuje řádnou obezřetnost. Vaše základna nerespektuje z tohohle vůbec nic."],["Veřejně se zavázat k postoji, který zrovna vede ve večerních průzkumech","Váš oficiální postoj se čtyřikrát změní ještě před samotným otevřením hlasování."],["Prohlásit zákon za „duchovně správný“ a detaily nechat na štábu","„Duchovně správné“ se stává trvalou kategorií ve vašich tiskových briefinzích."]]},"p-congress-2":{"t":"Zaslechnuté řeči o impeachmentu","x":"Poslankyně Vandersloot potichu sbírá podpisy pro vyšetřování impeachmentu. Potichu ve smyslu, že to řekla šesti novinářům a jedné velmi upovídané baristce.","c":[["Vyhrožovat, že proti každému signatáři postavíte vlastního vybraného protikandidáta","Tři signatáři okamžitě uhnou. Tři další svolají kvůli té hrozbě tiskovou konferenci."],["Plně spolupracovat a vydat každý požadovaný dokument","Vyšetřování vyhasne kvůli nedostatku skandálu, což se samo stává malým skandálem."],["Uniknout falešné dokumenty naznačující, že skutečnou zločinkyní je Vandersloot","Únik je vystopován rovnou do vaší kanceláře, k tiskárně, i s cartridge."],["Pozvat Vandersloot na celostátně vysílaný „přátelský summit“","Přijme. Vysílá se přesně proti finále mistrovství světa."]]},"p-congress-3":{"t":"Světla se za chvíli zhasnou","x":"Ministryně financí Boonová vás informuje, že financování vlády o půlnoci vyprší, pokud Kongres do té doby něco, cokoli, neschválí.","c":[["Nařídit úřadům, ať zůstanou otevřené stejně, a účtovat to na „vibrace“","Úřad pro odpovědnost vlády napíše ostře formulovanou zprávu. Necháte si ji zarámovat."],["Podepsat ošklivý dvoustranický nouzový zákon, kompromisy a vše","Nouzový zákon nikoho nenadchne. Nikoho ale ani nepošlou domů bez výplaty."],["Nechat vládu záměrně padnout do výluky a viníka jmenovat: předsedu Sněmovny","Federální zaměstnanci přijdou o výplatu. Vaše preference nějak ne."],["Platit „nezbytný“ personál z pokladny suvenýrového obchodu Bílého domu","V pokladně je čtyřicet jedna dolarů. Na moc dlouho to nevystačí."]]},"p-congress-4":{"t":"Trocha navíc pro prezidentovu položku","x":"V návrhu rozpočtu je, jak říká ministryně Boonová, místo přesně na jednu nestydatou položku navíc. Nějakou dobu už přemýšlíte o fontánách.","c":[["Nařídit vložení položky s fontánou a vyzvat kohokoli, ať se ji odváží škrtnout","Fontány se postaví. Novináři jim navždy říkají Marnivostní bazény."],["Škrtnout svůj oblíbený projekt a nechat peníze jít na skutečnou infrastrukturu","Opraví se pár mostů. Nikdo vám za to samozřejmě nepoděkuje."],["Vložit potichu ještě tři další položky, dokud jsou všichni rozptýlení tou první","Auditoři nakonec najdou všechny čtyři. O každé vyjde samostatná analýza."],["Přejmenovat položku s fontánou na „Vodní iniciativu pro veterány“","Žádný veterán o to nežádal. Několik veteránů je teď zcela oprávněně naštvaných."]]},"p-congress-5":{"t":"Senátor Fitch má na mysli číslo","x":"Senátor Fitch dodá rozhodující hlas pro novou přehradu ve svém státě výměnou za sochu sebe sama a skromné místo v kabinetu pro svého synovce.","c":[["Dát mu jen přehradu, bez sochy a synovce, a hrozit odebráním místa ve výboru","Fitch hlasuje ano, zuřivě, a od té doby vám v rozhovorech říká „ten pronajímatel“."],["Odmítnout celou dohodu a hlas získat poctivě","Zabere to o šest dní déle. Zákon nakonec projde bez úprav."],["Dát mu vše, včetně synovcova místa v kabinetu","Synovci je dvacet dva let a teď nějak dohlíží na jadernou regulaci."],["Nabídnout výměnou lamu místo sochy","Fitch lamu přijme. Nikdo zúčastněný na tomhle vyjednávání není hrdý."]]},"p-congress-6":{"t":"Senátor Alcott objevuje telefonní seznam","x":"Senátor Alcott už šest hodin nahlas čte na půdě Senátu telefonní seznam Delaware, aby zablokoval váš zákon. Momentálně je někde u písmene L.","c":[["Změnit pravidla sněmovny uprostřed obstrukce, ať zmlkne","Funguje to okamžitě. Také se to stává přesně tím pravidlem, které příště použijí proti vám."],["Nechat ho domluvit a hlasování vyhrát čistě, na základě obsahu","Domluví ve tři ráno. Zákon projde o čtyři minuty později."],["Poslat rivalizujícího senátora, ať obstruuje tu obstrukci","V sále teď dva dospělí muži zároveň nahlas čtou telefonní seznamy."],["Objednat pizzu pro celý sál, „pro udržení morálky“","Alcott sní pizzu a klidně čte dál. Špatně mířený úplatek."]]},"p-congress-7":{"t":"Chtějí zástupkyni šéfa štábu Pruettovou","x":"Sněmovní výbor předvolal vaší zástupkyni šéfa štábu, paní Pruettovou, která náhodou ví, kde jsou pohřbená mrtvá těla, finanční i jiná.","c":[["Uplatnit exekutivní výsadu a odvážit se je vyzvat, ať ji vymáhají","Vaši právníci ten argument milují. Hlasování o pohrdání Kongresem se přesto koná okamžitě."],["Nechat Pruettovou vypovídat a poctivě ji připravit","Vypovídá dobře. Je to nudná televize, což je přesně ten nejlepší možný výsledek."],["Poslat vypovídat místo Pruettové dvojnici","Dvojnice je odhalena během devíti minut kvůli vlastní zapomenuté jmenovce."],["Nechat Pruettovou předstírat náhlou, dramatickou, kariéru zachraňující ztrátu hlasu","Čtyřicetkrát zašeptá „bez komentáře“. Nějak horší, než kdyby mluvila."]]},"p-congress-8":{"t":"Soudkyně Kesslingová má minulost","x":"Vaše kandidátka na odvolací soud, soudkyně Kesslingová, kdysi ve vysokoškolských novinách napsala sloupek „Proč by úterky měly být nezákonné“. Senátoři jsou tím bohužel nesmírně zaujatí.","c":[["Protlačit nominaci výborem dřív, než si to kdokoli přečte dál","Kesslingová je potvrzena. Sloupek o úterku se na týdny stane titulkem kabelových zpráv."],["Nominaci stáhnout a vybrat místo ní někoho gloriózně nudného","Nový kandidát nikdy neměl názor na pracovní dny. Potvrzen jednomyslně."],["Nechat Kesslingovou veřejně obhajovat sloupek jako „vizionářský“","„Vizionářský“ je velkorysé slovo. Potvrzena přesto, ale těsně a hořce."],["Nominovat druhého, odváděcího soudce, aby se pobouření rozdělilo napůl","Kongres teď nemá rád dva soudce stejně silně. Svým způsobem efektivní."]]},"p-congress-9":{"t":"Přílepek, ke kterému se nikdo nehlásí","x":"Váš nezbytný zákon o infrastruktuře má na sobě přílepek rušící cla na dovoz lam, vložený neznámou osobou. Teď je to nějak problém úplně všech.","c":[["Prosadit celý zákon i s přílepkem a viníka svalit na lamí lobby","Zákon projde. Lamí dovozní lobby, jak se ukáže, skutečně existuje a je pořádně naštvaná."],["Přílepek vyškrtnout a schválit čistý infrastrukturní zákon","Silnice se opraví. Záhada lamího přílepku zůstane navždy nevyřešena."],["Přidat druhý přílepek, aby to odvedlo pozornost od prvního","Teď jsou tam dva záhadné přílepky a nula odpovědí o kterémkoli z nich."],["Veřejně oznámit, že jste vždy osobně miloval lamy","Tohle neuspokojí naprosto nikoho a zmate skoro každého."]]},"p-congress-10":{"t":"Incident kolem pošty Sylvie P. Renwickové","x":"Rutinní zákon přejmenovávající malou poštu po oblíbené místní knihovnici se nějak proměnil ve tříwelký boj v plénu kvůli nesouvisejícím, desítky let starým zášti.","c":[["Vynutit hlasování a veřejně zostudit každé „ne“ jako protiknihovnické","Zákon projde. Několik poslanců zůstává hluboce dotčeno tím, že je nazvali protiknihovnickými."],["Zprostředkovat tichou dohodu, aby to prošlo bez dalšího dramatu","Pošta dostane své jméno. Nikdo si toho nevšimne, což je přesně ta výhra."],["Připojit vlastní jméno k budově jako spolupočestněného","Teď je to Pošta Renwickové-a-Vás. Renwickova rodina zuří."],["Navrhnout přejmenování po vašem psovi místo toho","Pes má napříč politickým spektrem lepší preference než vy. Mírně znepokojivé."]]},"p-congress-11":{"t":"Senátorka Duchampová si najde svou chvíli","x":"Senátorka Duchampová přednese dvouhodinový projev v plénu, katalogizující každé vaše selhání, dokonale načasovaný na hlavní vysílací čas, i s plakáty na stojanech.","c":[["Vypnout jí uprostřed projevu mikrofon kvůli formalitě","Klip s umírajícím mikrofonem získá desetkrát víc zhlédnutí, než kolik by kdy získal samotný projev."],["Nechat ji domluvit a klidně reagovat fakty druhý den","Vaše odpověď je přesná a tragicky ji sleduje skoro nikdo."],["Naplánovat vlastní konkurenční projev přesně ve stejnou dobu","Celý večer se vysílá rozdělená obrazovka. Oba projevy prohrávají v souboji o sledovanost."],["Poslat jí koš ovoce „v duchu obousměrné spolupráce“","Zvedne koš ovoce v plénu jako Důkaz A něčeho."]]},"p-congress-12":{"t":"Poslankyně Okaforová mění tým","x":"Dosud spolehlivá spojenkyně, poslankyně Okaforová, oznamuje přechod na druhou stranu, s odkazem na „svědomí“, což pro nikoho zúčastněného není dobré znamení.","c":[["Veřejně jí sebrat výborová místa ještě před koncem tiskovky","Tiskovku přesto dokončí, teď s další stížností, kterou může citovat."],["Veřejně jí poděkovat za službu a popřát vše dobré","Elegantní a naprosto neúčinné v zabránění tomu, aby ji následovali další dva."],["Uniknout starý memoranda naznačující, že vždy byla tajně neloajální","Memorandum je pravé, a datované ještě před tím, než jste vůbec nastoupil do úřadu."],["Nabídnout její staré křeslo tomu, kdo proti ní povede nejtvrdší primárku","Teď máte místo tiché spojenkyně velmi hlasitého a velmi neprověřeného spojence."]]},"p-congress-13":{"t":"Předsedovi Tolliverovi naroste páteř","x":"Předseda výboru Tolliver, dřív spolehlivý jako nábytek, odmítá posunout váš zákon dál bez úprav. Zjevně si ho přečetl. Celý.","c":[["Vyhrožovat, že mu před celým výborem seberete kladívko","Okamžitě couvne. Také už vám nikdy nebude věřit a všem to řekne, proč."],["Přijmout jeho pozměňovací návrhy, protože byly stejně rozumné","Zákon je díky tomu lepší. Bolestně, trapně lepší."],["Obejít ho a protlačit zákon jiným výborem","Tolliver to v kabelových zprávách nazve pučem. Ne zcela se mýlí."],["Pozvat Tollivera do Camp Davidu „to probrat“ o víkendu","Vrátí se s dalšími pozměňovacími návrhy, ne méně. Camp David se pořádně vymstil."]]},"p-congress-14":{"t":"Velmi konkrétní most nikam konkrétně","x":"Významný dárce chce účelovou dotaci na most spojující jeho dvě soukromé nemovitosti. Poblíž není žádné město. Není tam žádná řeka. Je tam cesta pro golfový vozík.","c":[["Nařídit vložení a vyzvat auditora, ať to vůbec někdy najde","Auditor to najde asi za čtyři minuty. Na plánech je i jeho jméno."],["Dárci říct ne a přesměrovat peníze na skutečný most","Dárce je na dalším fundraiseru k vám chladný. Postaví se skutečný most."],["Schválit to a přidat druhý most pro jeho druhou cestu na golfový vozík","Teď existují dva mosty nikam. Místní zprávy tomu říkají „ten rozliv“."],["Přejmenovat to na „koridor odolnosti“ a doufat, že si toho nikdo nevšimne","Někdo si toho všimne okamžitě. Zůstává to nezaměnitelně cestou pro golfový vozík."]]},"p-congress-15":{"t":"Slyšení má špatné osvětlení a ještě horší otázky","x":"Jste předvolán svědčit před dozorčí výbor, podle toho, koho se zeptáte, ohledně naprosto všeho, co jste kdy udělal.","c":[["Na každou otázku odpovědět „to je utajené“, ať je to pravda, nebo ne","Polovina toho nikdy utajovaná nebyla. Teď je to titulek o lhaní pod přísahou."],["Odpovídat na vše upřímně a nechat věci dopadnout, jak dopadnou","Je to náročné odpoledne. Naštěstí je do večeře u konce."],["Přinést si připravený „gotcha“ moment na zesměšnění tazatelky","Gotcha moment se obrátí proti vám, když předloží stejný dokument, s dřívějším datem."],["Na každou otázku odpovědět lidovou historkou o dědečkově farmě","Nikdo se nedozví jediný fakt. Sledovanost, nepochopitelně, přesto stoupá."]]},"p-congress-16":{"t":"Malý dodatek o věčnosti","x":"Skupina spojenců potichu navrhuje zrušení funkčních limitů, jemně nazvané „modernizace kontinuity vedení“. Míní tím, že zůstanete, natrvalo.","c":[["Tvrdě přesvědčit hlasy a protlačit to výborem hned tento týden","Projde výborem. Fráze „věčný prezident“ se stane trendem a už nikdy nevymizí."],["Veřejně nápad odmítnout a požádat je, ať ho zcela stáhnou","Republika si tiše oddechne. Vaše základna si oddechne mnohem hlasitěji."],["Nechat to potichu postupovat, přitom vždy popírat, že jste o to žádal","Popření nevěří nikdo ani na vteřinu. Zákon přesto postupuje dál."],["Navrhnout „kompromis“ jen jednoho dalšího období, jako laskavost","Jedno další období se okamžitě stává novým základním požadavkem pro příští cyklus."]]},"p-congress-17":{"t":"Národní den uznání prezidenta","x":"Mladý kongresman, dychtivý po pozornosti, předkládá rezoluci vytvářející federální svátek na vaši počest. Alarmujícím způsobem už má i znělku.","c":[["Nahlas ho podpořit a tlačit na vedení, ať ho urychlí","Projde. Znělka hraje v každé federální budově dalších deset let."],["Požádat ho, ať to laskavě stáhne, tohle je trochu přehnané","Stáhne to, viditelně zklamaný. Znělka naštěstí umírá s ním."],["Navrhnout, aby svátek zahrnoval i povinné přehlídky","Účast na povinných přehlídkách je, mírně řečeno, řídká."],["Navrhnout přejmenování svátku na počest založení země, ale znělku si nechat","Technicky už to není svátek na vaši počest. Znělka nepochopitelně zůstává o vás."]]},"p-congress-18":{"t":"Ostře formulovaný kus papíru","x":"Opozice předkládá návrh na pokárání, převážně symbolický a naprosto ponižující, kvůli komentáři, který jste pronesl o účesu zahraničního vůdce.","c":[["Přesvědčit vlastní poslance, ať to jednomyslně zamítnou","Čistě neprojde na straně stran, což se samo stává vlastním typem titulku."],["Vydat upřímnou omluvu a nechat celý návrh potichu vyprchat","Omluva zabere. Komentář o účesu je do týdne zapomenut."],["Ještě přitvrdit komentář o účesu během rozpravy v plénu","Zahraniční vůdce veřejně odpoví komentářem o vaší vysoké čelo."],["Poslat zahraničnímu vůdci poukaz do kadeřnictví jako mírové gesto","Nějak je to přijato jako ještě těžší urážka, než ten původní komentář."]]},"p-congress-19":{"t":"Opozice opouští budovu","x":"Rozzuřena kvůli manipulaci s harmonogramem, opozice úplně opustí sál, čímž zabrání usnášeníschopnosti, a co hůř, odnese si i většinu kávy.","c":[["Poslat pořádkovou stráž, ať je fyzicky přivede zpět","Přivedou je. Okamžitě také kvůli tomu podávají žalobu."],["Hlasování odložit a poctivě vyjednat jejich návrat","Vrátí se za dva dny. Hlasování nakonec proběhne, čistě a se záznamem."],["Hlasovat i tak a tvrdit usnášeníschopnost kreativním počítáním","Kreativní počítání nepřežije ani první soudní podání."],["Objednat do sálu pizzu a živě streamovat, jak sám čekáte a jíte","Stream je podivně poutavý. Legislativně tím nevyřešíte vůbec nic."]]},"p-congress-20":{"t":"Devět set stran, nula čtenářů","x":"Souhrnný zákon má devět set stran, hlasování o něm je za tři hodiny, a jediný člověk, který ho celý přečetl, je prý stážista jménem Diaz.","c":[["Hlasování prosadit i tak, Diaz může v případě potřeby odpovídat na otázky","Přijde to na přetřes. Diaz se na chvíli stává nejmocnějším člověkem v budově."],["Hlasování odložit, dokud si to poslanci skutečně nepřečtou","Odklad je nudný. Zákon, který nakonec projde, je mnohem méně trapný."],["Přidat dalších dvě stě stran, dokud se nikdo nedívá","Diaz si žádá přidat plat. Diaz si ho, upřímně, zaslouží."],["Nechat štáb udělat z toho jeden přátelský infografický přehled","Infografika zcela záměrně vynechává několik důležitých škrtů ve financování."]]},"p-congress-21":{"t":"Hlasování v hodinu, kdy by nikdo hlasovat neměl","x":"Vedení naplánuje závěrečné hlasování na druhou hodinu ranní, sázeje na to, že polovina Kongresu bude příliš unavená, nebo příliš zaneprázdněná něčím jiným, na to, aby řádně protestovala.","c":[["Nechat termín druhé ráno a hlasy protlačit i přes únavu","Projde. Několik poslanců později tvrdí, že si vůbec nepamatují, že hlasovali."],["Přesunout hlasování na rozumnou denní hodinu","Hlasování proběhne transparentně, ve dne, jako u funkční vlády."],["Přesunout hlasování ještě později, na čtvrtou ráno, pro jistotu","Dva senátoři to celé prospí. Jejich hlasy zůstávají měsíc sporné."],["Zásobit sál neomezenou kávou, „aby to bylo férové“","Káva to férovým nedělá. Jen tím udrží všechny vzhůru, ať si mohou stěžovat."]]},"p-congress-22":{"t":"Teambuilding v nejhorší možnou chvíli","x":"Výjezdní zasedání vaší strany, které mělo posílit jednotu před klíčovým hlasováním, se zvrhlo v tříwelkou hádku kvůli nehodě na kánoi a karaoke automatu.","c":[["Zasedání zrušit a nařídit všem okamžitý návrat do Kapitolu","Vrátí se sjednoceni přesně v jedné věci: v osobní nevraživosti vůči vám."],["Nechat je to dořešit, vydiskutovat a vrátit se soudržní","Vrátí se o dva dny později, upřímně bližší než předtím. Upřímně řečeno, ohromující."],["Připojit se k zasedání osobně, „obnovit morálku“ sám","Váš výběr karaoke písně se stává nejpamátnější, a nejhorší, částí celého výjezdu."],["Poslat místo sebe motivační zpívaný telegram","Zpívaný telegram si od výjezdního sboru vyslouží víc respektu, než byste si vysloužil vy sám."]]},"p-base-1":{"t":"Pojmenujte nepřítele","x":"Interní průzkumy ukazují, že vaše základna nechce politiku, chce padoucha. Váš odborník na průzkumy drží krátký seznam jmen, který vaši spisovatelé projevů zjevně napsali po půlnoci.","c":[["Přečíst jméno z kartičky, pomalu, pro kamery","Padouch, vyděšená úřednice na radnici, dostane do oběda tři výhrůžky smrtí."],["Říct, že skutečné problémy jsou složité a nikdo jednotlivý za ně nemůže","Dav bučí přesně tím způsobem, jakým davy bučí na domácí úkol."],["Jmenovat úřednici, jejího manžela a jejich zlatého retrívra","Wikipedie retrívra je do hodiny vandalizována."],["Svalit vinu na oblak ve tvaru vašeho předchůdce","Meteorologové jsou teď považováni za součást spiknutí."]]},"p-base-2":{"t":"Zakázaný medvěd","x":"Dětskou obrázkovou knížku o medvědovi, který se dělí o med se zvířátky z lesa různého původu, označily tři facebookové skupiny za, cituji, propagandu grooming. Váš ředitel sociálních sítí chce prohlášení ještě před obědem.","c":[["Žádat stažení medvěda ze všech knihoven v zemi","Autor medvěda dostane knižní smlouvu třikrát vyšší, než byla jeho záloha."],["Říct, že je to jen kniha o medvědovi, co se dělí o med, a nechat to být","Kabelový komentátor vás obviní z toho, že jste vůči medvědům měkký."],["Žádat stažení medvěda, vyšetření autora a přejmenování medu","Prodej medu ve vašich nejsilnějších okresech se ze vzdoru ztrojnásobí."],["Oznámit, že medvěd byl tajně vyznamenaný válečný hrdina, a udělit mu milost","Medvěd, jsa fiktivní, milost vděčně přijímá."]]},"p-base-3":{"t":"Problém s merchem","x":"Váš kancléř hlásí, že internetový obchod má vyprodanou položku, která se prodává třikrát líp než cokoli jiného: hrnek s vaší tváří photoshopnutou na řvoucího orla.","c":[["Narychlo objednat padesát tisíc dalších, označit je jako limitovanou edici","Vyprodá se za jedenáct minut a několik jich dorazí už rozbitých."],["Žádat merch, který má důstojnost. Třeba slušnou sponu na kravatu","Spona se prodá čtyři kusy, všechny vašemu právníkovi."],["Přidat sesterský hrnek s plačícím soupeřem","Federální etický úřad otevře spis, který nikdy nezavře."],["Dát svou tvář na orla A na vlajku A na monster truck","Verze s monster truckem je stažena z prodeje kvůli konstrukčním důvodům, které s vaší tváří nesouvisí."]]},"p-base-4":{"t":"Skandování","x":"Dav na včerejším shromáždění bez vyzvání vymyslel skandování požadující uvěznění úřadujícího federálního soudce. Váš spisovatel projevů to zachytil na video a nemůže si to přestat pouštět dokola.","c":[["Vést skandování sám na příštím shromáždění, pomaleji, ať se může přidat každý","Soudce žádá o ochranku a dostane ji."],["Říct davu, že soudy takhle nefungují, a požádat je, ať přestanou","Vypískají vás z pódia o devět minut dřív."],["Přidat druhou sloku se jmény soudcových asistentů","Dva asistenti se potichu stáhnou z veřejného života."],["Tvrdit, že skandování ve skutečnosti mluví o maskotovi ligy nižší třídy se stejným jménem","Maskot, zmatený mýval, se odmítá vyjádřit."]]},"p-base-5":{"t":"Teorie o sklepě","x":"Podstatná část vaší základny je přesvědčena, že viceprezident je hologram ovládaný ze sklepa ve státě, který, přísně vzato, žádné sklepy nemá kvůli hladině spodní vody. Váš tiskový poradce potřebuje instrukce.","c":[["Na tiskovce na to mrkněte a nechte to bujet.","Hologramové zboží se prodává lépe než to skutečné."],["Jasně prohlaste, že viceprezident je skutečná, fyzická osoba.","Věřící usoudí, že přesně tohle by hologram řekl."],["Naznačte, že hologramy jsou možná DVA, střídají se na směny.","Sklep v onom bezesklepém státě je pod dohledem amatérů."],["Nechte skutečného viceprezidenta žonglovat naživo, aby dokázal svou tělesnost.","V přímém přenosu mu upadne kuželka a teorie se, jaksi, jen posílí."]]},"p-base-6":{"t":"Světec z parkoviště","x":"Muž, kterého mírně obtěžovali na úřadě dopravní evidence o tři státy dál, byl vaší základnou svatořečen jako mučedník hnutí, včetně svíček a hashtagu. On sám z toho vypadá zmateně. Vaše tisková mluvčí potřebuje formulaci.","c":[["Pozvěte ho na pódium a udělte mu medaili, kterou jste vymysleli před hodinou.","Medaili přijme, přestože stále netuší, co vlastně udělal."],["Jemně poznamenejte, že dlouhá fronta na úřadě není, historicky vzato, mučednictvím.","Jste obviněni z neúcty k jeho oběti."],["Vyhlaste na jeho počest státní svátek a přejmenujte úřad.","Přejmenovaný úřad má pořád dlouhou frontu."],["Odhalte, že je náhodou váš bratranec z třetího kolena.","Genealogové žádnou takovou příbuznost nenajdou, a nikdo si toho nevšímá."]]},"p-base-7":{"t":"Seznam k bojkotu","x":"Vaše základna chce bojkotovat řetězec kaváren za zločin duhového posypu na sezónním donutu. Vaše poradkyně pro vnitřní bezpečnost, zmatená, jak se jí to dostalo na stůl, vám to přesto přeposílá.","c":[["Tweetněte název řetězce a nazvěte to neamerickým donutařstvím.","Akcie řetězce den klesají, donut se vyprodá na týden."],["Řekněte, že posyp neohrožuje republiku.","Jste obviněni, že jste se postavili na stranu posypu."],["Jmenujte tři další řetězce a pekárnu, která kdysi použila duhový ubrousek.","Rodinná pekárna, fungující od roku 1962, do měsíce zavírá."],["Ohlaste rivalský, vlastenecký donut bez posypu, jen s hvězdičkami.","Hvězdičky se prý špatně prokusují."]]},"p-base-8":{"t":"Špatně složená vlajka","x":"Virální fotka ukazuje dobrovolníka na stadionu, jak skládá vlajku s, podle vaší základny, o jeden záhyb méně. Kancelář vašeho generálního prokurátora obdržela čtyřicet formálních stížností s požadavkem na federální obžalobu.","c":[["Požadujte zveřejnění jména dobrovolníka.","Sedmnáctiletý dobrovolník je na týden vyloučen ze školy."],["Řekněte, že špatné složení vlajky není zločin.","Jeden kongresman vás nazve slabým ve věcech vlajky."],["Navrhněte federální Radu pro standardy skládání vlajky s pravomocí předvolávat svědky.","První slyšení rady trvá čtyři hodiny navíc kvůli jedinému záhybu."],["Osobně přeskládejte vlajku v přímém přenosu, špatně, ale sebevědomě.","Nikdo se neodváží zmínit, že vaše má stejný počet záhybů."]]},"p-base-9":{"t":"Zmizelý betlém","x":"Nákupní centrum o tři státy dál nahradilo svůj betlém obyčejným vánočním stromkem a vaše základna to považuje za zahajovací bitvu koordinovaného národního útoku na samotné svátky.","c":[["Vyhlaste nouzový stav Válka o Vánoce a požadujte navrácení betléma.","Centrum betlém vrátí a hlásí rekordní návštěvnost."],["Poznamenejte, že obchodní centra mění výzdobu každý rok a vždy tomu tak bylo.","Jste obviněni, že nenávidíte Vánoce i obchodní centra."],["Vyžadujte přísahu věrnosti od každého maloobchodníka ohledně sváteční výzdoby.","Nafukovací sněhulák jednoho železářství je vyšetřován pro nedostatečnou úctu."],["Osobně přivezte betlém do centra na valníku, naživo.","Jeden z tří králů poblíž food courtu spadne."]]},"p-base-10":{"t":"Žába v obleku","x":"Kreslená žába v obleku a kravatě jako vy se stala neoficiálním maskotem vašeho hnutí, objevuje se na vlajkách, tetováních i na dodávce jednoho velmi odhodlaného muže. Váš syn to považuje za skvělé a chce to zoficiálnit.","c":[["Přijměte žábu jako oficiálního maskota kampaně.","Žabí zboží do týdne překoná to vaše skutečné."],["Řekněte, že politické hnutí by nemělo zastupovat kreslená žába.","Základna usoudí, že vy osobně nejste žábin největší fanoušek, a to je podezřelé."],["Nechte žábu vystoupit na příštím mítinku v plném kostýmu a mávat.","Dítě v první řadě pláče, ze strachu nebo z nadšení, není jasné."],["Nechte si žábu právně ochránit ochrannou známkou, než na ní vydělá někdo jiný.","Během pár dní přichází žaloba od nesouvisející značky žabích cereálií."]]},"p-base-11":{"t":"Zjevně příliš umírněný","x":"Neznámý poslanec zastupitelstva má v primárkách, které nikdo nevypsal, šest procent proti vám a kandiduje napravo od vás na programu, který váš stratég popisuje jen jako hlasitější.","c":[["Útočte na něj osobně, každou noc, dokud nezmizí.","Jeho sbírka peněz se díky té pozornosti ztrojnásobí."],["Ignorujte ho a soustřeďte se na vládnutí.","Základna usoudí, že mlčení znamená, že má pravdu."],["Předběhněte ho politikou tak extrémní, že to i on nazve extrémismem.","Obrátí se a nazve vás napodobitelem, správně."],["Nabídněte mu vymyšlené velvyslanectví v zemi bez pobřeží.","Nadšeně přijme a už o něm nikdy nikdo neuslyší."]]},"p-base-12":{"t":"Pastor Combs chce laskavost","x":"Pastor Combs z dvanáctitisícové arény Liberty Now Arena Church je připraven vás v neděli podpořit z kazatelny. Rád by si ale promluvil o územní výjimce pro svou novou parkovací budovu.","c":[["Potichu schvalte výjimku a přijměte podporu.","Parkovací budova vyroste vedle mokřadu, o kterém už nikdo nikdy nemluví."],["Odmítněte laskavost a požádejte o podporu na základě jejích vlastních zásluh.","Pastor Combs se slzami v očích podpoří vašeho protikandidáta v primárkách."],["Schvalte výjimku, plus daňovou úlevu, plus druhou parkovací budovu.","Mokřad je teď oficiálně parkovací budova."],["Požádejte pastora Combse, aby vás znovu pokřtil, na pódiu, kvůli sledovanosti.","Voda byla podle několika svědků podezřele teplá."]]},"p-base-13":{"t":"Test loajality","x":"Prominentní příznivec zveřejnil online test čistoty o dvanácti otázkách. Váš viceprezident v něm získal osm z dvanácti bodů a lidé, kteří neumí definovat slovo měkkýš, ho tak nyní nazývají.","c":[["Vyplňte test veřejně a odpovídejte na každou otázku s maximální extrémností.","Získáte dvanáct z dvanácti a mírně vyděsíte vlastní personál."],["Řekněte, že testy čistoty rozkládají jakoukoli skutečnou koalici.","Autor testu napíše jízlivou reakci nazvanou Já Vám To Říkal."],["Zveřejněte VLASTNÍ test o třiceti otázkách a nechte viceprezidenta test opakovat.","Tentokrát skóruje ještě hůř, na testu, který jste napsali sami."],["Prohlaste samotný test za operaci hlubokého státu a požadujte jeho stažení.","Návštěvnost testu se přes noc zečtyřnásobí."]]},"p-base-14":{"t":"Pověst","x":"Váš tiskový asistent slyšel, z druhé ruky, že se mezi základnou šíří pověst, že jste ve dvaceti letech osobně zápasili s pumou a porazili ji. Není to pravda. Chce vědět, co s tím má dělat.","c":[["Nic nepotvrzujte ani nevyvracejte a nechte legendu růst.","Pamětní mince s pumou se čile prodává."],["Vydejte prosté, nudné popření. Nikdy jste s pumou nezápasili.","Popření samo je bráno jako další důkaz, že se souboj konal."],["Potvrďte to, přidejte medvěda a řekněte, že jste medvěda ze soucitu nechali žít.","Organizace na ochranu zvěře vás zdvořile žádá, abyste přestal."],["Předveďte svědka, starého muže, který tvrdí, že u toho byl.","Svědek si nevzpomíná, na které hoře k tomu vlastně došlo."]]},"p-base-15":{"t":"Falešná zpráva","x":"Vymyšlený titulek tvrdící, že váš protikandidát chce zdanit dešťovou vodu, se šíří vaší základnou tempem, které váš ředitel sociálních sítí obdivně nazývá bezprecedentní.","c":[["Sdílejte to sami s poznámkou někteří lidé říkají.","Oprava od ověřovatele faktů dosáhne jen desetiny záběru falešné zprávy."],["Veřejně uveďte věc na pravou míru. Nikdo dešťovou vodu nezdaňuje.","Jste obviněni z ověřování faktů proti vlastní straně, což je kardinální hřích."],["Přidejte navazující tvrzení, že chce zdanit i SNÍH.","Meteoroložka je v obchodě s potravinami napadena z důvodů, které se nikdy nedozví."],["Tvrďte, že jste osobně zachytili zákon o dani z dešťové vody a roztrhali ho.","Žádný takový zákon nikdy neexistoval, detail, na který se nikdo neptá."]]},"p-base-16":{"t":"Zákaz slova","x":"Slovo, dříve zcela nevýrazné, prohlásila jedna frakce vaší základny za urážlivé poté, co ho ve svém projevu použil politický soupeř. Váš právník potřebuje vědět, zda federální vláda může slovo skutečně zakázat. Nemůže.","c":[["Oznamte, že zvažujete všechny právní možnosti, jak ho zakázat.","Vyhledávání slova ve slovníku vzroste o devět set procent."],["Trpělivě vysvětlete, že existuje první dodatek ústavy.","Jste obviněni, že to slovo osobně milujete."],["Zakažte slovo ve federálních budovách i jeho blízká synonyma.","Tezaurus je krátce, docela vážně, považován za kontraband."],["Vymyslete nové slovo jako náhradu a nařiďte jeho používání ve svých projevech.","Nikdo, včetně vás, ho neumí vyslovovat pokaždé stejně."]]},"p-base-17":{"t":"Buck chce požehnání","x":"Vůdce milice, který si říká Buck, se objevil už na třech mítincích s dvěma tucty ozbrojených mužů ve stejných vestách a rád by od vás dostal veřejné uznání. Vaše zástupkyně pro záležitosti veteránů, sama veteránka, je z toho nesvá.","c":[["Ze pódia Bucka pochvalte jako skutečné vlastence.","Buckova skupina se do měsíce ztrojnásobí."],["Odmítněte Buckovu skupinu jakkoli uznat.","Buck vás do mikrofonu na livestreamu nazve podvodníkem."],["Pozvěte Buckovy muže, aby sloužili jako neoficiální ostraha mítinku.","Novinář je krátce zadržen muži, kteří k tomu nemají žádnou zákonnou pravomoc."],["Udělte Buckovi čestný titul bez skutečné moci, třeba Polní maršál v.v.","Buck si do hodiny nechává vytisknout vizitky."]]},"p-base-18":{"t":"Velká latte panika","x":"Váš stratég hlásí sílící přesvědčení mezi základnou, že pobřežní elity potichu rozmisťují pražírny řemeslné kávy do každého města v zemi, aby, slovy jednoho respondenta, nahradily skutečné Američany lidmi, kteří říkají artisanal.","c":[["Na příštím mítinku ponuře varujte před kávou, která si jde po jejich jídelnách.","Jídelna o tři města dál hlásí čtyřicetiprocentní nárůst prodeje kávy, ironicky ze zvědavosti."],["Poukažte, že kavárny ve skutečnosti nejsou demografickou hrozbou.","Jste obviněni, že jste se postavili na stranu ovesného mléka."],["Navrhněte clo na nadutá nápoje podle definice výboru, který sami jmenujete.","Výbor se nedokáže shodnout, co je nadutost, a věnuje tématu sedm zasedání."],["Otevřete si na příštím mítinku rivalský stánek s jídelní kávou, deset dolarů za šálek.","Vyprodá se, přesně za cenu, ze které si dělal legraci."]]},"p-base-19":{"t":"Vyhoďte toho intelektuála","x":"Vysoce kvalifikovaná poradkyně z ministerstva zahraničí na briefingu třikrát použila slovo nuance. Vaše základna ji chce mít pryč do západu slunce.","c":[["Veřejně ji vyhoďte a jako důvod uveďte její elitářskou slovní zásobu.","Další tři přijatí na ministerstvu jsou znatelně horší ve své práci a mnohem hlasitější."],["Nechte ji. Nuance, poznamenáte, je v zahraniční politice obecně užitečná.","Rozhlasový moderátor stráví celou reláci zesměšňováním samotného slova nuance."],["Vyhoďte ji a pak i dva kolegy, kteří se jí zastali.","Zbylý personál ministerstva ze samé opatrnosti přestává na poradách používat víceslabičná slova."],["Přesuňte ji do kanceláře bez oken, ať studuje jednu extrémně nevýznamnou smlouvu.","Dokončí o ní definitivní zprávu, kterou si nikdo nikdy nepřečte."]]},"p-base-20":{"t":"Patnáctimetrový vy","x":"Občanský výbor, devět lidí, jeden z nich váš bratranec, vybral z drobných darů dost na patnáctimetrovou sochu vás na dálničním odpočívadle. Váš šéf kanceláře potřebuje rozhodnutí o odhalení.","c":[["Zúčastněte se odhalení a nechte se vyfotit u paty sochy.","Několik řidičů hlásí, že výraz sochy je z jistých úhlů dálnice znepokojivý."],["Požádejte je, ať peníze místo toho věnují na opravu silnic.","Výbor je zmatený a mírně dotčený."],["Schvalte sochu plus druhou na hranici státu, mávající.","Mávající ruka sochy se při bouři do měsíce utrhne."],["Požádejte, aby socha byla o pět metrů vyšší, než se původně plánovalo.","Nyní vyžaduje vlastní územní výjimku, která je samozřejmě udělena."]]},"p-base-21":{"t":"Tvář na jeho paži","x":"Superfanoušek si nechal na předloktí vytetovat překvapivě věrný portrét vašeho obličeje a právě teď stojí u zábrany, s vyhrnutým rukávem, v naději, že si toho všimnete. Váš asistent si není jistý, že je tohle normální.","c":[["Podepište to tetování přímo, permanentní fixou, v přímém přenosu.","Tetovací salon o tři státy dál hlásí náhlý, velmi konkrétní nárůst zákazníků."],["Zdvořile mu řekněte, že to je na politika docela závazek.","Vypadá opravdu zraněně, a nějak tak i celá základna."],["Pozvěte ho na pódium, ať tetování ukáže celé aréně.","Do rána si stejný motiv nechá udělat čtyřicet lidí u stejného tatéra."],["Nechte si na oplátku udělat malé, nenápadné tetování jeho tváře.","Podle všech je to, se vší úctou, dost špatná podobizna."]]},"p-base-22":{"t":"Vůdce skandování chce místo v kabinetu","x":"Muž, který vede skandování davu na úplně každém mítinku už rok, funkce bez formálního titulu a bez kvalifikací kromě obrovského hlasu, by rád byl zvažován na post ministra něčeho. Váš syn to považuje za skvělý nápad.","c":[["Jmenujte ho do skutečné funkce v kabinetu s kamennou tváří.","Jeho první politické memorandum je, slovo od slova, pokřik."],["Poděkujte mu za službu a vysvětlete, že práce vyžaduje přinejmenším relevantní zkušenosti.","To odpoledne vede dav v pokřiku o vaší nevděčnosti."],["Jmenujte ho A udělejte ze skandování oficiální vládní funkci s vlastním rozpočtem.","Úřad pro vedení skandování si do týdne žádá další personál."],["Jmenujte ho čestným Vícevůdcem skandování a nechte skutečné místo neobsazené.","Je nadšený; nikdo neumí vysvětlit, co ten titul znamená."]]},"p-pardon-1":{"t":"Kruh zakladatele","x":"Právní zástupce vysvětluje, že Trevor Bulwark, zakladatel zkrachovalého penzijního fondu Pinnacle Retirement Trust, vyvedl osmdesát milionů dolarů z penzí důchodců, aby si koupil flotilu vodních skútrů. \"Říká, že je duchovně napravený,\" poznamenává právník. \"Také říká, že by chtěl zpátky svou jachtu.\"","c":[["Podepište milost","Bulwark otevírá Pinnacle Retirement Trust Dva pod mírně pozměněným logem."],["Odmítněte, ať se potí","Důchodci dostanou zpět zlomek svých peněz a přísně formulovaný dopis."],["Udělte milost a jmenujte ho ředitelem pro bezpečnost důchodů","Jeho první politické memorandum doporučuje víc vodních skútrů pro všechny."],["Udělte mu milost, ale musí každému důchodci osobně vrátit peníze u bankomatu, naživo","Přenos má víc diváků než projev o stavu unie."]]},"p-pardon-2":{"t":"Prostředí bohaté na cíle","x":"Generální prokurátor čte spis generála Marcuse Thorna, odsouzeného za nařízení útoku na svatbu, kterou nazval \"bohatou na cíle\". Thornův dopis o milost má čtyři strany stížností a jednu fotku, na které salutuje. \"Je oblíbený u základny,\" říká prokurátor, \"tak jako je oblíbený ohňostroj.\"","c":[["Podepište milost","Thorne pořádá uvítací mítink v bowlingové hale, kterou trvá na tom, že je \"strategicky významná.\""],["Odmítněte","Rodiny obětí vydávají prohlášení. Skoro nikdo si ho nepřečte."],["Udělte milost a jmenujte ho zvláštním vyslancem pro mír","Jeho první čin v zahraničí je, že se ministra zeptá, jestli \"chce problémy.\""],["Udělte mu milost pod podmínkou, že napíše omluvné paměti","Paměti se čile prodávají pod názvem \"Udělal bych to znovu, asi.\""]]},"p-pardon-3":{"t":"Přítel rodiny","x":"Sal Marchetti, odsouzený v jedenácti bodech za organizovaný zločin, byl podle žádosti o milost, kterou mu určitě nepsal jeho právník, po desetiletí \"drahým přítelem a štědrým podporovatelem\". \"Posílá pozdravy,\" říká právník, \"a velmi velkou šunku.\"","c":[["Podepište milost","Šunka byla ve skutečnosti nacpaná hotovostí. Nikdo se neptá, odkud ty peníze jsou."],["Odmítněte","Marchettiho společníci vyjadřují nespokojenost skrze několik malých, popiratelných požárů."],["Udělte milost a jmenujte ho velvyslancem na Maltě","Maltská vláda podává formální, nesmírně zdvořilou stížnost."],["Udělte mu milost výměnou za rodinný recept na calzone","Recept je skutečný. Je také, nezaměnitelně, výhrůžkou."]]},"p-pardon-4":{"t":"Slon v porcelánu","x":"Šerif \"Bull\" Haney podstrkoval důkazy desítkám obžalovaných a provozoval soukromou mýtnou budku pro řidiče bez dokladů projíždějící jeho okresem. Jeho příznivci tomu říkají \"policejní práce staré školy\". Předseda Nejvyššího soudu tomu říká několik federálních zločinů. \"Chce zpátky svůj odznak,\" říká předseda, \"konkrétně.\"","c":[["Podepište milost","Bull dostane zpátky odznak a tričko s nápisem \"Znovu ve službě.\""],["Odmítněte","Jeho oběti konečně dostanou slyšení, které není zmanipulované."],["Udělte milost a jmenujte ho pohraničním carem","Do týdne se objeví mýtné budky na třech dalších okresních hranicích."],["Udělte mu milost, přeřaďte ho k hlídání dárkového obchodu Bílého domu","Je, znepokojivě, velmi dobrý v prodeji hrnečků."]]},"p-pardon-5":{"t":"Offshore a na vaší straně","x":"Chip Renfro, velký dárce, ukryl před finančním úřadem zhruba dvě miliardy dolarů v devíti krycích firmách pojmenovaných podle jeho golfového handicapu. \"Rád by to nazval chybou ve výkazu,\" říká prokurátor, \"chybou ve výkazu za dvě miliardy dolarů.\"","c":[["Podepište milost","Renfro okamžitě otevírá desátou krycí firmu, tentokrát pojmenovanou podle vaší popularity."],["Odmítněte","Finanční úřad skutečně jednou vybere daně a nikdo mu nepoděkuje."],["Udělte milost a jmenujte ho poradcem ministerstva financí pro zjednodušení daní","Jeho plán zjednodušení má jednu stránku a prospívá přesně jednomu daňovému poplatníkovi."],["Udělte mu milost výměnou za \"manipulační poplatek\" deset procent","Je to podle jakékoli definice úplatek. Je to ale také, technicky, zpracované."]]},"p-pardon-6":{"t":"Na Měsíc a zpátky do vězení","x":"Dex Bramwell vytáhl peníze čtyřiceti tisícům investorů svým tokenem CoinDaddy a pak si koupil ponorku. \"Říká, že ta technologie předběhla svou dobu,\" hlásí váš syn se širokým úsměvem. \"Také říká, že vás nechá vydělat na CoinDaddy Dva.\"","c":[["Podepište milost","CoinDaddy Dva startuje do hodiny. Do dne se zhroutí."],["Odmítněte","Čtyřicet tisíc lidí dostane zhruba jedenáct centů každý a jedno ponaučení."],["Udělte milost a jmenujte ho krypto carem","Jeho první regulační pokyn je jediné emoji rakety."],["Přijměte poplatek za milost celý zaplacený jeho bezcennou mincí","Mince do večera nemá žádnou hodnotu. Ponorka je, jaksi, skutečná."]]},"p-pardon-7":{"t":"Mrazák plný dvacetidolarovek","x":"Kongresman Delbert Cranch byl přistižen se čtyřmi sty tisíci dolary v hotovosti nacpanými v kuchyňském mrazáku, zabalenými, jak trvá na tom, \"kvůli čerstvosti\". Tisková mluvčí čte žádost o milost nahlas s viditelnou fyzickou nevolností.","c":[["Podepište milost","Cranch si kupuje druhý, větší mrazák."],["Odmítněte","Cranch je vyloučen z kongresu a podle všeho vystěhován kvůli účtu za opravu mrazáku."],["Udělte milost a jmenujte ho předsedou etické komise","Jeho úvodní slovo je, jaksi, o správné organizaci mrazáku."],["Udělte mu milost, ale mrazák putuje do Smithsonova muzea","Je nyní nejnavštěvovanějším exponátem muzea."]]},"p-pardon-8":{"t":"Rodinný podnik","x":"Váš bratranec Wade předstíral vlastní únos kvůli pojistnému plnění a pak zveřejnil fotky ze \"zajetí\" z letoviska v Cabu. \"Říká, že rodina drží pohromadě,\" hlásí váš syn. \"Také říká, že letovisko má skvělý bar u bazénu.\"","c":[["Podepište milost","Wade vám na Díkůvzdání hlasitě poděkuje před kamerami, které jste nepozvali."],["Odmítněte","Wade si odsedí skutečný trest. Rodinná skupinová konverzace mlčí měsíc."],["Udělte milost a udělejte z něj regionálního styčného úředníka FEMA","Jeho první krizový briefing obsahuje podezřele mnoho doporučení baru u bazénu."],["Udělte mu milost, ale musí naživo předstírat, že ho tentokrát opravdu našli živého","Sledovanost je vynikající. Důvěryhodnost není."]]},"p-pardon-9":{"t":"Sleva ze skladu důkazů","x":"Detektiv Ray Kessler podstrkoval důkazy podezřelým, které neměl rád, a bral hotovost od kartelu za ty, které měl. Ředitel FBI mu přes stůl podává spis. \"Žádá o úplnou milost a, chci to zdůraznit, o své staré parkovací místo.\"","c":[["Podepište milost","Kessler dostane odznak, místo a okamžitě nového klienta."],["Odmítněte","Devět nespravedlivých odsouzení je díky jeho případu znovu otevřeno."],["Udělte milost a jmenujte ho šéfem interního vyšetřování","Stížnosti na interní vyšetřování vůči interním vyšetřovatelům se zečtyřnásobí."],["Udělte mu milost, natrvalo ho přeřaďte na inventarizaci skladu důkazů","Ukáže se, že je mimořádně dobrý v třídění ukradeného zboží."]]},"p-pardon-10":{"t":"Obležení soudu","x":"Plukovník Gid Strother držel okresní soud pod hlavní zbraně šest hodin kvůli sporu o územní plán. Viceprezident osobně doručuje žádost o milost, z nevysvětlených důvodů v maskáčové kravatě. \"Jeho muži ho milují,\" říká viceprezident. \"Stejně tak průzkumy.\"","c":[["Podepište milost","Strother pořádá vítězný mítink u stejného soudu, znovu ozbrojený."],["Odmítněte","Úřednice soudu, kterou ohrožoval, konečně může v klidu spát."],["Udělte milost a jmenujte ho oficiálním styčným důstojníkem pohraniční milice","Do měsíce hlásí tři další soudy podobné \"spory o územní plán.\""],["Udělte mu milost pod podmínkou, že jeho milice přejde na soutěžní patchwork","Přikrývky jsou, proti všem očekáváním, docela dobré."]]},"p-pardon-11":{"t":"Buvol se vrací","x":"Chad \"Buvol\" Merkins zaútočil na Kapitol s rohy na hlavě a vestou, na které nic konkrétního nestálo. Stal se lidovým hrdinou lidí, kteří na dvorku vlastní aspoň jednu vlajku na tyči. \"Chce zpátky své rohy z úschovy důkazů,\" říká váš tiskový asistent. \"Chybí mu.\"","c":[["Podepište milost","Rohy jsou vráceny. Merkins je nosí na brunch."],["Odmítněte","Merkins si odsedí trest a napíše z vězení ostře formulované, plné pravopisných chyb paměti."],["Udělte milost a udělejte z něj oficiálního průvodce po Kapitolu","Jeho prohlídka zahrnuje podrobnou rekonstrukci. Dvakrát denně. S rohy."],["Udělte mu milost a pak prodávejte rohy jako oficiální merchandise","Vyprodá se za hodinu. Merkins požaduje tantiémy."]]},"p-pardon-12":{"t":"Přirážka na inzulin","x":"Marlon Vance, generální ředitel farmaceutické firmy a spolehlivý dárce kampaně, ztrojnásobil ceny inzulinu během nedostatku, který sám osobně vyvolal. Jeho dopis o milost to popisuje jako \"reaktivní cenotvorbu\". Šéf personálu to soukromě nazývá \"zločinem s prezentací.\"","c":[["Podepište milost","Vance okamžitě oznamuje \"reaktivní cenotvorbu\" pro tři další léky."],["Odmítněte","Ceny inzulinu skutečně klesnou. Vance to nazve \"zásahem státu.\""],["Udělte milost a jmenujte ho poradcem pro zdravotní náklady","Jeho doporučení na snížení nákladů je, jaksi, vyšší ceny."],["Udělte mu milost, ale týden musí sám rozvážet inzulin od dveří ke dveřím","Nesnáší každou vteřinu. Fotky jsou ovšem skvělé."]]},"p-pardon-13":{"t":"Poslední z orlů","x":"Duke Callahan zastřelil poslední hnízdící pár chráněné kolonie orlů bělohlavých, protože, jeho slovy, \"jeden z nich se na mě divně díval\". Dokonce i pastor se cítí nesvůj, když tlumočí jeho žádost. \"Žádá o odpuštění,\" říká pastor, \"a o svou pušku zpátky.\"","c":[["Podepište milost","Callahan dostane pušku zpátky. Kolonie orly zpátky nedostane."],["Odmítněte","Ochránci přírody to nazývají vzácným vítězstvím. Callahan to nazývá \"pronásledováním.\""],["Udělte milost a jmenujte ho komisařem pro divokou zvěř","Jeho první politický návrh zkracuje seznam ohrožených druhů tím, že z něj druhy odstraňuje."],["Udělte mu milost, ale na každém mítinku musí nosit orlí kostým","Nosí ho. Nesnáší to. Dav ho, znepokojivě, miluje."]]},"p-pardon-14":{"t":"Fond na archu","x":"Reverend Silas Thorpe přesvědčil svou kongregaci, aby mu odevzdala své penzijní úspory na stavbu skutečné, plavbyschopné archy, a pak za peníze koupil menší, neplavbyschopnou jachtu. \"Říká, že Pán se pohybuje tajemnými cestami,\" povzdechne si pastor. \"Většinou směrem k jeho jachtě.\"","c":[["Podepište milost","Thorpe oznamuje Fond na archu Dva, \"tentokrát se skutečnou lodí.\""],["Odmítněte","Jeho kongregace dostane náhradu a konečně i trochu skepse."],["Udělte milost a jmenujte ho poradcem pro víru při administrativě","Jeho první kázání pro personál je nezaměnitelně sbírkovou kampaní."],["Udělte mu milost výměnou za osobní požehnání","Požehnání je nezvykle konkrétní a zahrnuje desátek."]]},"p-pardon-15":{"t":"Devatenáct let","x":"Odell Pruitt si odseděl devatenáct let za loupež, kterou nyní DNA důkazy prokazují, že nespáchal. Jeho právnička, nezvykle mlčenlivá, jen přisune přes stůl složku. \"Není v tom žádný chytrý úhel pohledu,\" říká. \"Je prostě nevinný.\"","c":[["Nechte ho tam, kde je","Základna jásá nad \"pořádkem a zákonem\". Pruitt zůstává v cele, která nikdy neměla být jeho."],["Propusťte ho","Pruitt vychází ven do světa, který je o devatenáct let jinde. Základna to nazývá měkkostí."],["Potichu mu zmírněte trest, bez zásluh, bez tiskové zprávy","Je volný, ale záznam ho pořád vede jako odsouzence. Nikdo si toho stejně nevšimne."],["Propusťte ho, ale jen pokud vám osobně na kameru poděkuje","Udělá to skrz zaťaté zuby. Devatenáct let koupilo velmi krátký proslov."]]},"p-pardon-16":{"t":"Kvůli pojistce","x":"Nadia Volkovová vypálila vlastní dům s regulovaným nájemným kvůli pojistnému plnění a při tom vystěhovala čtyřicet rodin. Předseda Nejvyššího soudu prochází spis s nevzrušeným výrazem. \"Ona tomu říká 'zpoždění renovace,'\" říká.","c":[["Podepište milost","Volkovová si kupuje druhou budovu. Zasvěcení očekávají druhý požár."],["Odmítněte","Čtyřicet rodin dostane náhradu. Volkovová dostane, co si zaslouží."],["Udělte milost a jmenujte ji do komise pro dostupné bydlení","Její první doporučení se týká zápalek, metaforicky, jak trvá na tom."],["Udělte jí milost pod podmínkou, že dům vlastnoručně znovu postaví","Ukáže se, že je opravdu mizerná tesařka."]]},"p-pardon-17":{"t":"Interní zpráva","x":"Ingrid Halvorsenová vynesla interní zprávu dokazující, že firma zakryla kontaminaci pitné vody, a byla odsouzena za \"krádež majetku vlády\" za papír, na kterém byla vytištěna. \"Neexistuje verze, ve které je záporák,\" přiznává váš mluvčí pro projevy, \"což je pro projev problém.\"","c":[["Nechte ji shnít","Základna ji nazve zrádkyní. Voda je pořád kontaminovaná."],["Propusťte ji","Halvorsenová vychází na svobodu a okamžitě pokračuje v odhalování. Základna zuří."],["Potichu jí udělte milost, bez tiskové zprávy, bez zásluh","Je volná. Nikdo z vaší základny se to nikdy nedozví, o to jde."],["Propusťte ji, ale utajte fakt, že jste to udělal","Milost je skutečná. Papíry, které to dokazují, oficiálně neexistují."]]},"p-pardon-18":{"t":"Kotec","x":"Chester Voss, spolehlivý dárce, provozoval ve stodole, kterou ve sbírkových e-mailech popisoval jako \"wellness ústraní\", psí zápasy. Generální prokurátorka čte obžalobu s viditelným odporem. \"Rád by to měl z krku před volbami v polovině období,\" říká.","c":[["Podepište milost","Voss stodolu znovu otevírá. Cedule teď hlásá \"wellness ústraní, fáze dvě.\""],["Odmítněte","Psi jsou umístěni do nových domovů. Vossovy sbírkové e-maily citelně utichnou."],["Udělte milost a jmenujte ho poradcem pro rozvoj venkova","Jeho první návrh zahrnuje federální dotace na \"wellness ústraní.\""],["Udělte mu milost pod podmínkou, že si osobně adoptuje každého psa","Nyní vlastní čtyřicet psů a podle všeho nesnáší úplně každého z nich stejnou měrou."]]},"p-pardon-19":{"t":"Eunice","x":"Eunice Radleyová, sedmdesát osm let, si odpykává doživotní trest za prodej malého množství marihuany podle zákona, který mezitím zrušili všude kromě jejího spisu. \"Nežádá o peníze ani o titul,\" poznamenává předseda Nejvyššího soudu. \"Jen chce znovu vidět svou zahradu.\"","c":[["Nechte ji tam, kde je","Základna tleská tvrdosti. Eunice zmešká další narozeniny za mřížemi."],["Propusťte ji","Eunice znovu uvidí svou zahradu. Základna reptá o \"měkkosti vůči zločinu.\""],["Propusťte ji jen pokud vám na kameru poděkuje","Udělá to, zdvořile, se slzami, které nejsou zcela vděčné."],["Propusťte ji a pak si ji najměte, ať peče pro Bílý dům","Její koláč je podle jednomyslného hlasování personálu lepší než ten od kuchaře Bílého domu."]]},"p-pardon-20":{"t":"Dokonalejší padělek","x":"Percival Ott prodal třem muzeím padělaný koncept Deklarace nezávislosti, ručně zestárlý čajovými sáčky a údajně opravdovou láskou k řemeslu. \"Není mu to líto,\" hlásí mluvčí pro projevy. \"Je na to hrdý. Chce, aby to bylo v milosti výslovně uvedeno.\"","c":[["Podepište milost","Ott okamžitě začíná pracovat na padělané Listině práv."],["Odmítněte","Muzea dostanou své peníze zpět. Ott dostane skutečný, nefalšovaný trest."],["Udělte milost a jmenujte ho kurátorem Národního archivu","Návštěvnost stoupá. Stejně tak, potichu, i počet padělků v archivu."],["Udělte mu milost, ale musí místo toho zfalšovat lichotivou biografii o vás","Stává se bestsellerem. Historikové poznamenávají, že je to přinejmenším ze sedmdesáti procent fikce."]]},"p-pardon-21":{"t":"Stál u popelnice","x":"Marcus Ibe byl obviněn z domácího terorismu za to, že stál poblíž hořící popelnice na pokojném shromáždění, které nezaložil a snažil se uhasit. \"Uhasil ten oheň,\" říká ředitel FBI. \"Je to ve zprávě. Tu část si nikdo nepřečetl.\"","c":[["Nechte ho shnít","Základna ho nazve hrozbou. Zůstává ve vězení za uhašení požáru popelnice."],["Propusťte ho","Ibe vychází na svobodu. Základna trvá na tom, že to dokazuje, že systém je \"nastaven ve prospěch zločinců.\""],["Potichu ho propusťte, ale obvinění z terorismu zůstává v jeho záznamu","Je venku, ale každá prověrka po zbytek jeho života ho označí jako hrozbu."],["Propusťte ho a nabídněte mu reality show o tom všem","Pilotní díl se jmenuje \"Požár v popelnici\". Dostane objednávku na celou sezónu."]]},"p-pardon-22":{"t":"Doktor cukrových pilulek","x":"Doktor Warrick Slate prodal tisícům onkologických pacientů chemoterapeutické pilulky, které podle laboratorního rozboru byly převážně cukr. \"Nazývá to 'obchodním modelem blízkým placebu,'\" čte jeho právník nahlas a pak papír odloží, jako by byl radioaktivní.","c":[["Podepište milost","Slate do týdne ohlašuje novou řadu pilulek \"blízkých wellness.\""],["Odmítněte","Oběti se konečně dočkají svého dne u soudu a svých peněz zpět."],["Udělte milost a jmenujte ho do poradního sboru úřadu pro potraviny a léčiva","Jeho první hlas je proti přísnějším požadavkům na označování pilulek."],["Udělte mu milost pod podmínkou, že nejdřív sní vlastní pilulky","Bez váhání je sní. To vypovídá o všem."]]}};
